def pr_node(number: int, state: str = "OPEN", rollup: str | None = "PENDING", checks: list | None = None) -> dict:
    return {
        "number": number, "url": f"https://github.com/o/r/pull/{number}", "title": "t", "state": state,
        "isDraft": False, "merged": state == "MERGED", "mergedAt": None, "mergeable": "MERGEABLE",
        "mergeStateStatus": "BLOCKED", "headRefOid": "a" * 40, "reviewDecision": None, "updatedAt": "x",
        "commits": {"nodes": [{"commit": {"statusCheckRollup": None if rollup is None else {
            "state": rollup,
            "contexts": {"totalCount": len(checks or []), "pageInfo": {"hasNextPage": False}, "nodes": checks or []},
        }}}]},
    }


def check_run(name: str, status: str = "COMPLETED", conclusion: str | None = "SUCCESS") -> dict:
    return {"__typename": "CheckRun", "name": name, "status": status, "conclusion": conclusion,
            "detailsUrl": f"https://ci/{name}"}


def graphql_requests(query: str, lists: dict[str, int] | None = None) -> int:
    """The requests GitHub counts for QUERY: each connection (a field with first: or last:, or nodes(ids:) over a
    list variable sized in LISTS) costs the product of the sizes of the connections it is nested in."""
    total, stack, pending = 0, [1], 1
    for m in re.finditer(r"(\w+)\s*(\((?:[^()]|\([^()]*\))*\))?|[{}]", query):
        token, args = m.group(0), m.group(2) or ""
        if token == "{":
            stack.append(stack[-1] * pending)
            pending = 1
        elif token == "}":
            stack.pop()
            pending = 1
        else:
            size = re.search(r"\b(?:first|last):\s*(\d+)", args)
            ids = re.search(r"\bids:\s*(\$\w+)", args)
            if size or ids:
                total += stack[-1]
                pending = int(size.group(1)) if size else (lists or {})[ids.group(1)]
            elif m.group(1) not in ("on",):
                pending = 1
    return total


def graphql_cost(query: str, lists: dict[str, int] | None = None) -> int:
    """GitHub's points for QUERY: its requests over 100, rounded, and at least 1."""
    return max(1, round(graphql_requests(query, lists) / 100))


class InheritedRedTest(unittest.TestCase):
    """A red the base also has (next-autoland's base-red set) is named inherited, apart from the PR's own reds, so
    an agent does not push or re-run for it (hq bottleneck doc 2026-11-21: 2,427 heads re-pushed for base reds)."""

    def setUp(self):
        self.dir = tempfile.mkdtemp(prefix="glaeda-gh-test-base-reds-")
        self.addCleanup(shutil.rmtree, self.dir, True)
        patcher = mock.patch.object(gg, "BASE", Path(self.dir))
        patcher.start()
        self.addCleanup(patcher.stop)
        self.now = time.time()
        self.reads = []

    def report(self, reds, age=60):
        at = dt.datetime.fromtimestamp(self.now - age, dt.timezone.utc).isoformat()

        def reader(repo, ref, path):
            self.reads.append((repo, ref, path))
            return {"at": at, "base_reds": reds}
        return reader

    def data(self, base="feat-cmux-next"):
        def run(name, conclusion, workflow="cmux-next"):
            return {**check_run(name, conclusion=conclusion),
                    "checkSuite": {"workflowRun": {"databaseId": 7, "event": "pull_request",
                                                   "workflow": {"name": workflow, "databaseId": 1}}}}
        node = pr_node(1, rollup="FAILURE", checks=[run("cmux-next checks", "FAILURE"), run("lint", "FAILURE"),
                                                     run("web", "CANCELLED"), run("ok", "SUCCESS")])
        node["url"] = "https://github.com/manaflow-ai/cmux/pull/1"
        node["baseRefName"] = base
        return gg.parse_pr(node)

    def test_a_red_in_the_base_set_is_inherited_and_the_rest_stay_own(self):
        reds = gg.base_reds("manaflow-ai/cmux", "feat-cmux-next", self.now,
                            reader=self.report(["cmux-next / cmux-next checks \u203a Crash safety", "cmux-next / web"]))
        data = self.data()
        failed = gg.classify(data, self.now)["failed"]
        own, inherited = gg.split_inherited(data, failed, self.now, reds)
        self.assertEqual([gg.label(c) for c in inherited], ["cmux-next / cmux-next checks"])
        # a cancelled check is never a base red, even when its name is in the set
        self.assertEqual(sorted(gg.label(c) for c in own), ["cmux-next / lint", "cmux-next / web"])

    def test_the_summary_lists_inherited_reds_with_do_nothing_advice(self):
        reader = self.report(["cmux-next / cmux-next checks", "cmux-next / lint"])
        with mock.patch.object(gg, "read_base_reds_report", reader):
            data = self.data()
            data["checks"] = [c for c in data["checks"] if c.get("name") != "web"]
            text = gg.summary("pr:manaflow-ai/cmux#1", {"data": data})
        self.assertIn("inherited from feat-cmux-next: ", text)
        self.assertIn("Do not push, re-run or chase it", text)
        self.assertIn("every red here is inherited", text)
        self.assertNotIn("  failed: cmux-next / lint", text)

    def test_one_read_per_ttl_and_a_stale_report_marks_nothing(self):
        reader = self.report(["cmux-next / lint"], age=gg.BASE_REDS_MAX_AGE + 60)
        self.assertIsNone(gg.base_reds("manaflow-ai/cmux", "feat-cmux-next", self.now, reader=reader))
        self.assertIsNone(gg.base_reds("manaflow-ai/cmux", "feat-cmux-next", self.now + 10, reader=reader))
        self.assertEqual(len(self.reads), 1)
        fresh = self.report(["cmux-next / lint"])
        got = gg.base_reds("manaflow-ai/cmux", "feat-cmux-next", self.now + gg.BASE_REDS_TTL + 1, reader=fresh)
        self.assertEqual(got, frozenset({"cmux-next / lint"}))

    def test_no_source_for_the_base_or_an_unread_report_marks_nothing(self):
        self.assertIsNone(gg.base_reds("manaflow-ai/cmux", "main", self.now, reader=self.report(["x"])))
        self.assertIsNone(gg.base_reds("o/r", "feat-cmux-next", self.now, reader=self.report(["x"])))
        self.assertEqual(self.reads, [])
        self.assertIsNone(gg.base_reds("manaflow-ai/cmux", "feat-cmux-next", self.now, reader=lambda *a: None))

    def test_the_field_view_has_own_and_inherited(self):
        with mock.patch.object(gg, "read_base_reds_report", self.report(["cmux-next / lint"])):
            view = gg.status_view("pr:manaflow-ai/cmux#1", {"data": self.data()})
        self.assertEqual(gg.field_text(view["checks"]["inherited"]), "lint")
        self.assertIn("cmux-next checks", gg.field_text(view["checks"]["own"]))


class AgentSummaryTest(unittest.TestCase):
    """The text summary is read by agents: it lists what needs action and counts the rest (--verbose lists all)."""

    def test_failed_checks_are_capped_at_ten_unless_verbose(self):
        data = gg.parse_pr(pr_node(1, rollup="FAILURE",
                                   checks=[check_run(f"job{i:02d}", conclusion="FAILURE") for i in range(15)]))
        with mock.patch.dict(os.environ, {"AGENT_VERBOSE": ""}):
            terse = gg.summary("pr:o/r#1", {"data": data})
        self.assertEqual(terse.count("  failed: "), gg.SUMMARY_FAILED)
        self.assertIn("  ... 5 more failed (--json lists them)", terse)
        full = gg.summary("pr:o/r#1", {"data": data}, verbose=True)
        self.assertEqual(full.count("  failed: "), 15)
        self.assertNotIn("more failed", full)

    def test_the_capped_list_leads_with_required_then_real_failures(self):
        checks = ([check_run(f"cancel{i:02d}", conclusion="CANCELLED") for i in range(12)]
                  + [check_run("lint", conclusion="FAILURE"), {**check_run("build", conclusion="FAILURE"), "isRequired": True}])
        data = gg.parse_pr(pr_node(1, rollup="FAILURE", checks=checks))
        listed = [line for line in gg.summary("pr:o/r#1", {"data": data}, verbose=False).splitlines()
                  if line.startswith(("  failed: ", "  cancelled: "))]
        self.assertTrue(listed[0].startswith("  failed: build"), listed[0])
        self.assertTrue(listed[1].startswith("  failed: lint (not required)"), listed[1])
        self.assertEqual(len(listed), gg.SUMMARY_FAILED)

    def test_a_run_lists_its_real_failure_before_cancelled_jobs(self):
        jobs = ([{"name": f"cancel{i:02d}", "status": "completed", "conclusion": "cancelled"} for i in range(10)]
                + [{"name": "build", "status": "completed", "conclusion": "failure"}])
        data = {"name": "CI", "status": "completed", "conclusion": "failure", "run_attempt": 1,
                "head_branch": "b", "head_sha": "a" * 40, "html_url": "https://x"}
        text = gg.summary("run:o/r/1", {"data": data, "jobs": jobs}, verbose=False)
        listed = [line for line in text.splitlines() if line.startswith(("  failed: ", "  cancelled: "))]
        self.assertTrue(listed[0].startswith("  failed: build"), listed[0])
        self.assertEqual(len(listed), gg.SUMMARY_FAILED)

    def test_the_wait_request_carries_verbose_to_the_daemon(self):
        with mock.patch.dict(os.environ, {"AGENT_VERBOSE": "1"}):
            self.assertTrue(gg.wait_request("run", "o/r/1", "done", 5, False, False, None, True, 0)["verbose"])
        with mock.patch.dict(os.environ, {"AGENT_VERBOSE": ""}):
            self.assertFalse(gg.wait_request("run", "o/r/1", "done", 5, False, False, None, True, 0)["verbose"])

    def test_verbose_flag_sets_agent_verbose(self):
        with mock.patch.dict(os.environ, {"AGENT_VERBOSE": ""}), \
                mock.patch.object(gg, "cmd_status", return_value=0) as status:
            gg.main(["status", "pr", "o/r#1", "--verbose"])
            self.assertEqual(os.environ["AGENT_VERBOSE"], "1")
        status.assert_called_once()


def iso(epoch: float) -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(epoch))


def job(name: str, conclusion: str = "failure", run_attempt: int = 1, runner: str = "cmuxs-mac-mini-3-glaeda-1",
        labels: tuple = ("glaeda-root-std-xcode-26.6",), failed_step: str = "Run selected tests",
        seconds: int = 300, end: float | None = None) -> dict:
    """A REST job; a failed one fails at `failed_step`, `seconds` after it started."""
    end = time.time() if end is None else end
    steps = [{"name": "Set up job", "conclusion": "success"}]
    if conclusion == "failure":
        steps.append({"name": failed_step, "conclusion": "failure"})
    return {"id": abs(hash(name)) % 1000, "name": name, "status": "completed", "conclusion": conclusion,
            "html_url": f"https://ci/job/{name}", "run_attempt": run_attempt, "runner_name": runner,
            "labels": list(labels), "started_at": iso(end - seconds), "completed_at": iso(end), "steps": steps}


def cached(*jobs: dict) -> dict:
    """Jobs as the daemon caches them."""
    return {"jobs": gg.slim_jobs({"jobs": list(jobs)})}


def refused(name: str = "build", **kw) -> dict:
    """What glaeda's runner hook leaves when it refuses a job: Set up runner failed within seconds."""
    return job(name, failed_step="Set up runner", seconds=7, **kw)


def status_context(context: str, state: str = "SUCCESS") -> dict:
    return {"__typename": "StatusContext", "context": context, "state": state, "targetUrl": f"https://ci/{context}",
            "createdAt": "2026-11-05T14:28:31Z"}


class FakeGitHub:
    """Answers GraphQL and REST like api.github.com; records every request."""

    def __init__(self) -> None:
        self.calls: list[tuple[str, str, dict, bytes | None]] = []
        self.prs: dict[tuple[str, str, int], dict] = {}
        self.runs: dict[int, dict] = {}
        self.jobs: dict[int, list] = {}
        self.issues: dict[tuple[str, str, int], dict] = {}
        self.steps: dict[str, list] = {}  # check run node id -> steps
        self.step_queries: list[list[str]] = []
        self.rest_remaining = 4000
        self.graphql_remaining = 4000
        self.rules: list[dict] = []  # GET .../rules/branches/B
        self.protected: list[str] = []  # the classic protection's required contexts
        self.job_steps: dict[int, list] = {}  # job (check run) database id -> steps, for GET .../actions/jobs/ID
        self.job_logs: dict[int, bytes] = {}  # job id -> its log, for GET .../actions/jobs/ID/logs (a redirect)
        self.base_gone = False  # the base branch was deleted: its rules and protection answer 404
        self.heads: dict[tuple[str, str, str], list] = {}  # (owner, repo, sha) -> that commit's check contexts
        # sha -> that commit's check suites [{"id", "latest": runs in its newest attempt, "runs": every attempt's}]
        self.suites: dict[str, list] = {}
        self.suites_unread = False  # GitHub failed the checkSuites field: null beside an error
        self.rate_limit_calls = 0  # GET /rate_limit: free, so it is counted separately
        self.throttle: dict[str, tuple[int, dict, bytes]] = {}  # "rest"|"graphql" -> the answer every read gets
        self.no_protection_feature = False  # a private repository's plan: rules and protection answer 403
        self.counts = False  # answer the fingerprint's counts (pr_fingerprint): off, no PR is ever probed
        self.probes = 0  # PR_PROBE queries answered
        self.full_reads = 0  # full PR queries answered
        self.named_calls: list[str] = []  # check-runs?check_name=NAME reads, by NAME
        self.suite_calls = 0  # GET commits/SHA/check-suites reads
        self.whole_heads = False  # REST check runs and statuses list self.heads (every page), not a PR's rollup page
        self.repo_pushes = 0  # pushes to the base repository: GET pulls/N embeds it, so each moves the pull's ETag

    def rate(self, resource: str, remaining: int) -> dict:
        return {"x-ratelimit-limit": "5000", "x-ratelimit-remaining": str(remaining),
                "x-ratelimit-reset": str(int(NOW + 1800)), "x-ratelimit-resource": resource}

    def __call__(self, method: str, url: str, headers: dict, body: bytes | None) -> tuple[int, dict, bytes]:
        self.calls.append((method, url, dict(headers), body))
        assert headers["Authorization"] == f"Bearer {TOKEN}"
        throttled = self.throttle.get("graphql" if url.endswith("/graphql") else "rest")
        if throttled and not url.endswith("/rate_limit"):
            return throttled
        if url.endswith("/graphql"):
            doc = json.loads(body)
            v, data, errors = doc["variables"], {}, []
            self.graphql_remaining -= 1
            data["rateLimit"] = {"limit": 5000, "remaining": self.graphql_remaining, "resetAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(NOW + 1800)), "cost": 1}
            if "suites" in v:  # every attempt's check runs of some suites, by id
                by_id = {suite["id"]: suite for suites in self.suites.values() for suite in suites}
                data["suiteRuns"] = [None if i not in by_id else {
                    "id": i, "conclusion": by_id[i].get("conclusion", "STARTUP_FAILURE"), "app": {"slug": "github-actions"},
                    "workflowRun": {"databaseId": by_id[i].get("run", 1), "workflow": {"name": "CI", "databaseId": 77}},
                    "checkRuns": {"pageInfo": {"hasNextPage": bool(by_id[i].get("runs_more"))},
                                  "nodes": [{k: v for k, v in r.items() if k not in ("__typename", "checkSuite")}
                                            for r in by_id[i]["runs"]]}} for i in v["suites"]]
                for n, i in enumerate(v["suites"]):  # a suite GitHub fails a field of: null beside a nested error
                    if by_id.get(i, {}).get("null_runs"):
                        data["suiteRuns"][n]["checkRuns"] = None
                        errors.append({"message": "Something went wrong", "path": ["suiteRuns", n, "checkRuns"]})
                body = {"data": data, **({"errors": errors} if errors else {})}
                return 200, self.rate("graphql", self.graphql_remaining), json.dumps(body).encode()
            if "nodes(ids:" in doc["query"]:
                self.step_queries.append(list(v["ids"]))
                data["nodes"] = [{"id": i, "steps": {"nodes": self.steps[i]}} if i in self.steps else None
                                 for i in v["ids"]]
            i = 0
            while f"u{i}" in v:  # runs by URL
                run = self.runs.get(int(v[f"u{i}"].rsplit("/", 1)[1]))
                data[f"w{i}"] = None if run is None else {
                    "__typename": "WorkflowRun", "databaseId": run["id"], "runAttempt": run.get("run_attempt"),
                    "event": run.get("event"), "createdAt": run.get("created_at"), "updatedAt": run.get("updated_at"),
                    "url": run.get("html_url"), "displayTitle": run.get("display_title"),
                    "workflow": {"name": run.get("name")},
                    "checkSuite": {"status": (run.get("status") or "").upper() or None,
                                   "conclusion": (run.get("conclusion") or "").upper() or None,
                                   "commit": {"oid": run.get("head_sha")},
                                   "branch": {"name": run["head_branch"]} if run.get("head_branch") else None}}
                i += 1
            if "object(oid:" in doc["query"]:
                for m in re.finditer(r'(?:([hm]\d+): )?repository\(owner:"([^"]+)",name:"([^"]+)"\)\{object\(oid:"([0-9a-f]+)"\)'
                                     r'\{\.\.\. on Commit\{statusCheckRollup\{contexts\(first:100(?:, after:"(\d+)")?\)', doc["query"]):
                    alias, owner, repo, sha, after = m.groups()
                    nodes = self.heads.get((owner, repo, sha))
                    start = int(after or 0)
                    node = None if nodes is None else {"statusCheckRollup": {"contexts": {
                        "pageInfo": {"hasNextPage": start + 100 < len(nodes), "endCursor": str(start + 100)},
                        "nodes": nodes[start:start + 100]}}, **self.suite_counts(sha, f"{owner}/{repo}")}
                    data["repository" if alias is None else alias] = {"object": node}
                out = {"data": data}
                return 200, self.rate("graphql", self.graphql_remaining), json.dumps(out).encode()
            comments = "issueOrPullRequest" in doc["query"]
            if not comments:
                if "checkSuites(first: 1) { totalCount }" in doc["query"]:
                    self.probes += 1
                else:
                    self.full_reads += 1
            alias, field, table = ("c", "issueOrPullRequest", self.issues) if comments else ("p", "pullRequest", self.prs)
            i = 0
            while f"o{i}" in v:
                node = table.get((v[f"o{i}"], v[f"r{i}"], v[f"n{i}"]))
                if comments and node is not None:  # comments(last: COMMENTS_LAST)
                    node = {**node, "comments": {**node["comments"], "nodes": node["comments"]["nodes"][-gg.COMMENTS_LAST:]}}
                if not comments and node is not None:
                    node = copy.deepcopy(node)
                    node["commits"]["nodes"][0]["commit"].update(self.suite_counts(node["headRefOid"]))
                    if self.counts:
                        self.add_counts(node, doc["query"])
                data[f"{alias}{i}"] = {field: node}
                if node is None:
                    errors.append({"type": "NOT_FOUND", "path": [f"{alias}{i}", field], "message": "Could not resolve"})
                i += 1
            out = {"data": data, **({"errors": errors} if errors else {})}
            return 200, self.rate("graphql", self.graphql_remaining), json.dumps(out).encode()
        path = url.split("api.github.com", 1)[1]
        parts = path.split("?")[0].split("/")
        if path == "/rate_limit":
            # Free: GitHub does not charge this against either primary limit, so neither does the fake.
            self.rate_limit_calls += 1
            body = {"resources": {"core": {"limit": 5000, "remaining": self.rest_remaining,
                                           "reset": int(NOW + 1800)},
                                  "graphql": {"limit": 5000, "remaining": self.graphql_remaining,
                                              "reset": int(NOW + 1800)}}}
            return 200, self.rate("core", self.rest_remaining), json.dumps(body).encode()
        if parts[4] == "issues":
            payload = self.rest_issue(parts, path)
            if payload is None:
                self.rest_remaining -= 1
                return 404, self.rate("core", self.rest_remaining), b'{"message": "Not Found"}'
        elif parts[4] in {"rules", "branches"} and self.no_protection_feature:
            self.rest_remaining -= 1
            return 403, self.rate("core", self.rest_remaining), json.dumps({"message": (
                "Upgrade to GitHub Pro or make this repository public to enable this feature.")}).encode()
        elif parts[4] == "actions" and parts[5] == "jobs" and parts[-1] == "logs":
            # GitHub answers a log with a redirect to signed blob storage, which no quota counts (blob())
            self.rest_remaining -= 1
            if int(parts[6]) not in self.job_logs:
                return 404, self.rate("core", self.rest_remaining), b'{"message": "Not Found"}'
            return 302, {**self.rate("core", self.rest_remaining),
                         "location": f"https://blob.example/{int(parts[6])}"}, b""
        elif parts[4] == "actions" and parts[5] == "jobs":
            steps = self.job_steps.get(int(parts[6]))
            payload = None if steps is None else {"id": int(parts[6]), "steps": steps}
            if payload is None:
                self.rest_remaining -= 1
                return 404, self.rate("core", self.rest_remaining), b'{"message": "Not Found"}'
        elif parts[4] == "actions" and len(parts) > 6:
            run_id = int(parts[6])
            payload = {"jobs": self.jobs.get(run_id, [])} if parts[-1] == "jobs" else self.runs.get(run_id)
            if payload is None:
                self.rest_remaining -= 1
                return 404, self.rate("core", self.rest_remaining), b'{"message": "Not Found"}'
        else:
            payload = self.rest_pr(parts, path)
            if payload is None:
                self.rest_remaining -= 1
                return 404, self.rate("core", self.rest_remaining), b'{"message": "Not Found"}'
        etag = '"' + str(abs(hash(json.dumps(payload, sort_keys=True)))) + '"'
        if headers.get("If-None-Match") == etag:
            return 304, self.rate("core", self.rest_remaining), b""
        self.rest_remaining -= 1
        return 200, {**self.rate("core", self.rest_remaining), "etag": etag}, json.dumps(payload).encode()

    @staticmethod
    def add_counts(node: dict, query: str) -> None:
        """The connection-level counts GitHub answers beside the contexts (and the suites' totalCount), when the
        query asks for them: a full read that forgot one would never match its probe."""
        commit = node["commits"]["nodes"][0]["commit"]
        if isinstance(commit.get("checkSuites"), dict) and re.search(r"checkSuites\(first: \d+\) \{ totalCount", query):
            commit["checkSuites"]["totalCount"] = len(commit["checkSuites"].get("nodes") or [])
        rollup = commit.get("statusCheckRollup")
        if not rollup or "checkRunCountsByState" not in query:
            return
        contexts = rollup["contexts"]
        runs: dict[str, int] = {}
        statuses: dict[str, int] = {}
        for c in contexts.get("nodes") or []:
            if not isinstance(c, dict):
                continue
            if c.get("__typename") == "StatusContext":
                statuses[c["state"]] = statuses.get(c["state"], 0) + 1
            else:
                state = c.get("conclusion") or c.get("status")
                runs[state] = runs.get(state, 0) + 1
        contexts["checkRunCount"] = sum(runs.values())
        contexts["checkRunCountsByState"] = [{"state": k, "count": v} for k, v in runs.items()]
        contexts["statusContextCount"] = sum(statuses.values())
        contexts["statusContextCountsByState"] = [{"state": k, "count": v} for k, v in statuses.items()]

    def suite_counts(self, sha: str, repo: str | None = None) -> dict:
        """A commit's checkSuites as SUITE_ATTEMPTS asks: each suite's check runs in its newest attempt
        (only the suites of REPO when a suite names its "repo"; "more": True cuts the page past 100 suites)."""
        if self.suites_unread:
            return {"checkSuites": None}
        suites = [suite for suite in self.suites.get(sha, []) if repo is None or suite.get("repo", repo) == repo]
        return {"checkSuites": {"pageInfo": {"hasNextPage": any(suite.get("more") for suite in suites)}, "nodes": [
            {"id": suite["id"], "latest": suite["latest"] if suite["latest"] is None else {"totalCount": suite["latest"]}}
            for suite in suites]}}

    @staticmethod
    def pr_updated(node: dict) -> str:
        """A PR's updated_at, the pull's and its issue's alike: it moves with what moves GitHub's (a push, a title, a
        draft flip, a close or merge, updatedAt itself), not with mergeability, which a base move changes on its own."""
        return json.dumps([node.get(k) for k in ("state", "headRefOid", "title", "isDraft", "merged", "mergedAt",
                                                 "updatedAt")])

    def rest_issue(self, parts: list[str], path: str) -> Any:
        """The REST view of the GraphQL issue nodes in self.issues: the issue, or a page of its comments."""
        node = self.issues.get((parts[2], parts[3], int(parts[5])))
        pr = self.prs.get((parts[2], parts[3], int(parts[5])))
        if node is None and pr is not None and len(parts) == 6:
            # Every PR is an issue too, with the pull's updated_at.
            return {"number": pr["number"], "html_url": pr["url"], "state": "open" if pr["state"] == "OPEN" else "closed",
                    "updated_at": self.pr_updated(pr), "pull_request": {"merged_at": pr.get("mergedAt")}}
        if node is None:
            return None
        comments = node["comments"]["nodes"]
        if len(parts) == 6:
            pull = {"merged_at": "x" if node["state"] == "MERGED" else None} if node["__typename"] == "PullRequest" else None
            return {"html_url": node["url"], "state": "open" if node["state"] == "OPEN" else "closed",
                    "comments": len(comments), **({"pull_request": pull} if pull else {})}
        page = int(path.split("page=")[-1])
        return [{"id": c["databaseId"], "html_url": c["url"], "created_at": c["createdAt"],
                 "user": {"login": c["author"]["login"] + "[bot]" if c["author"]["login"].endswith("-bot")
                          else c["author"]["login"]}, "body": c["body"]}
                for c in comments[100 * (page - 1):100 * page]]

    def rest_pr(self, parts: list[str], path: str) -> Any:
        """The REST view of the GraphQL PR nodes in self.prs: pulls, check runs, statuses, a head's
        workflow runs, and the base branch's rules and protection."""
        owner, repo, what = parts[2], parts[3], parts[4]
        if what == "pulls" and len(parts) == 5:  # the list (the read-token prime asks for one): the repo's newest pull
            nums = sorted(n for (o, r, n) in self.prs if (o, r) == (owner, repo))[-1:]
            return [self.rest_pr(["", "repos", owner, repo, "pulls", str(n)], path) for n in nums]
        if what == "pulls":
            node = self.prs.get((owner, repo, int(parts[5])))
            if node is None:
                return None
            state = "open" if node["state"] == "OPEN" else "closed"
            return {"number": node["number"], "html_url": node["url"], "title": node["title"], "state": state,
                    "draft": node["isDraft"], "merged": node["merged"], "merged_at": node["mergedAt"],
                    "mergeable": {"MERGEABLE": True, "CONFLICTING": False}.get(node["mergeable"]),
                    "mergeable_state": node["mergeStateStatus"].lower(), "updated_at": self.pr_updated(node),
                    "head": {"sha": node["headRefOid"], "ref": node.get("headRefName")},
                    # GitHub embeds the base repository whole, so any push to it moves the pull's ETag
                    "base": {"ref": "main", "repo": {"pushed_at": self.repo_pushes}}}
        if what in {"rules", "branches"} and self.base_gone:
            return None
        if what == "rules":
            return self.rules
        if what == "actions" and parts[5] == "workflows":
            return {"workflows": [{"id": 77, "name": "CI"}, {"id": 78, "name": "Lint"}]}
        if what == "branches":
            return {"name": parts[5], "protection": {"required_status_checks": {"contexts": self.protected}}}
        sha = parts[5] if what == "commits" else path.split("head_sha=", 1)[1].split("&")[0]
        contexts = self.heads.get((owner, repo, sha)) or []
        for node in self.prs.values():
            if node["headRefOid"] == sha:
                contexts = ((node["commits"]["nodes"][0]["commit"]["statusCheckRollup"] or {}).get("contexts") or {}).get("nodes") or []
        if self.whole_heads and (owner, repo, sha) in self.heads:  # REST lists the whole commit, not a rollup page
            contexts = self.heads[(owner, repo, sha)]
        runs = {c["checkSuite"]["workflowRun"]["databaseId"]: c for c in contexts
                if ((c.get("checkSuite") or {}).get("workflowRun") or {}).get("databaseId")}
        if what == "actions":
            page = int(path.split("page=")[-1]) if "&page=" in path else 1
            listed = list(runs.items())[100 * (page - 1):100 * page]
            return {"total_count": len(runs), "workflow_runs": [{"id": rid, "name": "run-name " + str(rid),  # REST: the run-name
                                       "workflow_id": {"CI": 77, "Lint": 78}.get(c["checkSuite"]["workflowRun"]["workflow"]["name"]),
                                       "check_suite_id": rid, "conclusion": (c["checkSuite"].get("conclusion") or "").lower() or None}
                                      for rid, c in listed]}
        if parts[-1] == "check-suites":
            # One suite per workflow run (its check runs' checkSuite), as GET commits/SHA/check-suites lists them: a
            # suite is completed when every run in it is, and its conclusion is known only then.
            self.suite_calls += 1
            grouped: dict = {}
            for c in contexts:
                if c.get("__typename") == "CheckRun":
                    rid = ((c.get("checkSuite") or {}).get("workflowRun") or {}).get("databaseId") or 0
                    grouped.setdefault(rid, []).append(c)
            suites = []
            for rid, runs in grouped.items():
                done = all(r["status"] == "COMPLETED" for r in runs)
                failed = any((r.get("conclusion") or "") in {"FAILURE", "TIMED_OUT", "CANCELLED", "STARTUP_FAILURE"}
                             for r in runs)
                suites.append({"id": rid, "status": "completed" if done else "in_progress",
                               "conclusion": ("failure" if failed else "success") if done else None,
                               "updated_at": json.dumps([[r["status"], r.get("conclusion")] for r in runs]),
                               "latest_check_runs_count": len(runs), "app": {"slug": "github-actions"}})
            return {"total_count": len(suites), "check_suites": suites}
        if parts[-1] == "status":
            listed = [c for c in contexts if c["__typename"] == "StatusContext"]
            page = int(path.split("page=")[-1]) if "&page=" in path else 1
            return {"total_count": len(listed), "statuses": [
                {"context": c["context"], "state": c["state"].lower(), "target_url": c.get("targetUrl"),
                 "created_at": c.get("createdAt")} for c in listed[100 * (page - 1):100 * page]]}
        checks = [c for c in contexts if c["__typename"] == "CheckRun"]
        if "check_name=" in path:
            name = urllib.parse.unquote(path.split("check_name=", 1)[1].split("&")[0])
            self.named_calls.append(name)
            checks = [c for c in checks if c["name"] == name]
        page = int(path.split("page=")[-1]) if "&page=" in path else 1
        checks_page = checks[100 * (page - 1):100 * page]
        return {"total_count": len(checks), "check_runs": [
            {"id": c.get("databaseId"), "node_id": c.get("id"), "name": c["name"], "status": c["status"].lower(),
             "conclusion": (c.get("conclusion") or "").lower() or None, "details_url": c.get("detailsUrl"),
             "started_at": c.get("startedAt"), "completed_at": c.get("completedAt"),
             "check_suite": {"id": ((c.get("checkSuite") or {}).get("workflowRun") or {}).get("databaseId")},
             "app": {"slug": ((c.get("checkSuite") or {}).get("app") or {}).get("slug")}}
            for c in checks_page]}

    def rest_calls(self) -> list:
        return [c for c in self.calls if not c[1].endswith("/graphql")]

    def gql_calls(self) -> list:
        return [c for c in self.calls if c[1].endswith("/graphql")]

    def run_calls(self) -> list:
        return [c for c in self.rest_calls() if "/jobs" not in c[1]]

    def job_calls(self) -> list:
        return [c for c in self.rest_calls() if "/jobs" in c[1]]


def assert_json_refusal(test: unittest.TestCase, stdout: str, code: str | None) -> None:
    """stdout is exactly one agent-output-contract object (ok false, code, reason, next) and nothing else: no
    usage text, notice or waiting line leaked into the document."""
    doc = json.loads(stdout)
    test.assertEqual(stdout.count("\n"), 1, stdout)
    test.assertIs(doc["ok"], False)
    test.assertTrue(doc["next"] and doc["reason"], doc)
    if code is not None:
        test.assertEqual(doc["code"], code)
    test.assertNotIn("usage:", stdout)
    test.assertNotIn("waiting on", stdout)


class Base(unittest.TestCase):
    def setUp(self) -> None:
        # watch files carry real mtimes, so the fake clock starts at each test, not at import:
        # a test reached 20 s into the suite saw its registrations as newer than NOW + 10 ticks
        global NOW
        NOW = float(int(time.time()))
        self.tmp = tempfile.TemporaryDirectory()
        self.saved = (gg.BASE, gg.WAIT_POLL, gg.DOWN_GRACE, gg.UPSTREAM_DOWN_GRACE, gg.DOWN_PATIENCE, gg.BUDGET_REFRESH)
        gg.BASE = Path(self.tmp.name) / "gh"
        gg.WAIT_POLL = 0.05
        gg.DOWN_GRACE = gg.UPSTREAM_DOWN_GRACE = 0.3
        gg.DOWN_PATIENCE = 0.6
        # An idle tick ends with a free GET /rate_limit; these tests count the daemon's requests, so
        # it is off here and BudgetRefreshTest turns it back on.
        gg.BUDGET_REFRESH = 0
        # A watch's reader comes from the session running the suite unless pinned: every test registers as one tool.
        self.saved_reader, gg._reader = gg._reader, "tool:test"
        self.gh = FakeGitHub()
        self.daemon = gg.Daemon(transport=self.gh, token=lambda: TOKEN, controller=None)
        # A `wait pr|run` against a daemon that serves waits execs into bash: never the test runner.
        execv = mock.patch.object(gg.os, "execv", side_effect=AssertionError("os.execv in a test process"))
        execv.start()
        self.addCleanup(execv.stop)
        # The land pool is sized from the host's cores (land_worker_ceiling): pinned to 8 here, so a suite on any
        # runner sizes as one 8-core host (4 workers); the load is reported only, pinned unknown, and the free RAM and
        # CPU unreported (headroom_left admits; the pool's count holds).
        for name, value in (("land_cores", 8), ("land_load_per_core", None), ("land_mem_available", None),
                            ("land_cpu_free", None)):
            pin = mock.patch.object(gg, name, return_value=value)
            pin.start()
            self.addCleanup(pin.stop)

    def tearDown(self) -> None:
        gg.BASE, gg.WAIT_POLL, gg.DOWN_GRACE, gg.UPSTREAM_DOWN_GRACE, gg.DOWN_PATIENCE, gg.BUDGET_REFRESH = self.saved
        gg._reader = self.saved_reader
        self.tmp.cleanup()

    def age_watch(self, key: str, seconds: float) -> None:
        path = gg.watch_dir() / gg.file_name(key)
        os.utime(path, (NOW - seconds, NOW - seconds))

    @contextlib.contextmanager
    def diagnostics_in(self, buffer: io.StringIO):
        """Route `say_waiting` into `buffer` for a test that asserts on *what* it says.

        `say_waiting` writes file descriptor 2, which `contextlib.redirect_stderr` does not touch
        (it swaps `sys.stderr`), so an in-process test cannot read it through a `StringIO` -- and
        must not, because the point of fd 2 is that it survives the stream being gone. The two
        halves are tested apart: the wording and the call sites here, through this seam; what the
        body does with fd 2 -- a dead pipe, a closed stream, a full pipe -- through the real CLI,
        in `WaitLineTest`. Patching the seam here is not a way around that: `WaitLineTest` reads fd
        2 of a subprocess, where no patch of ours is in effect."""
        with mock.patch.object(gg, "say_waiting", lambda line: print(line, file=buffer)):
            yield


class UnfinishedStatusTest(Base):
    """teamleaderleo/leo-workspace#3538 at f40f2a3d (2026-11-05): `wait pr --sha` returned success on GitGuardian's
    pass alone, before the fleet-reconciler posted the ws-check status its merges wait on. A pending status, an
    expected status not posted yet, and a head with nothing on it are never success."""

    SHA = "f" * 40

    def data(self, *nodes: dict, repo: str = "o/r", pushed: float | None = None) -> dict:
        node = pr_node(3538, checks=list(nodes))
        node.update(url=f"https://github.com/{repo}/pull/3538", headRefOid=self.SHA, mergeStateStatus="UNSTABLE",
                    updatedAt=iso(NOW if pushed is None else pushed))
        return gg.parse_pr(node)

    def test_a_pending_status_is_not_success(self) -> None:
        data = self.data(check_run("GitGuardian Security Checks"), status_context("ws-check", "PENDING"))
        for until in ("green", "done", "required"):
            self.assertIsNone(gg.verdict("pr", data, until, self.SHA, now=NOW), until)
        view = gg.status_view("pr:o/r#3538", {"data": data})
        self.assertEqual(view["checks"]["state"], "PENDING")
        self.assertEqual([c["name"] for c in view["checks"]["pending"]], ["ws-check"])

    def test_an_expected_status_not_posted_yet_is_not_success(self) -> None:
        # the #3538 head at 14:28: only GitGuardian had reported, ws-check was not posted yet
        data = self.data(check_run("GitGuardian Security Checks"), repo="teamleaderleo/leo-workspace",
                         pushed=NOW - 1500)
        self.assertIsNone(gg.verdict("pr", data, "green", self.SHA, now=NOW))
        self.assertEqual(gg.status_view("pr:teamleaderleo/leo-workspace#3538", {"data": data})["checks"]["state"],
                         "PENDING")
        self.assertIn("expected, not posted yet: ws-check",
                      gg.summary("pr:teamleaderleo/leo-workspace#3538", {"data": data}))
        posted = self.data(check_run("GitGuardian Security Checks"), status_context("ws-check", "PENDING"),
                           repo="teamleaderleo/leo-workspace", pushed=NOW - 1500)
        self.assertIsNone(gg.verdict("pr", posted, "green", self.SHA, now=NOW))
        green = self.data(check_run("GitGuardian Security Checks"), status_context("ws-check"),
                          repo="teamleaderleo/leo-workspace", pushed=NOW - 1500)
        self.assertEqual(gg.verdict("pr", green, "green", self.SHA, now=NOW), gg.EXIT_OK)
        red = self.data(check_run("GitGuardian Security Checks"), status_context("ws-check", "FAILURE"),
                        repo="teamleaderleo/leo-workspace", pushed=NOW - 1500)
        self.assertEqual(gg.verdict("pr", red, "green", self.SHA, now=NOW), gg.EXIT_FAIL)
        # the config file names a repo's contexts, and wins over the built-in list
        gg.write_json(gg.EXPECTED_CONFIG, {"o/r": ["deploy-check"], "teamleaderleo/leo-workspace": []})
        self.addCleanup(gg.EXPECTED_CONFIG.unlink)
        self.assertEqual(gg.verdict("pr", data, "green", self.SHA, now=NOW), gg.EXIT_OK)
        self.assertIsNone(gg.verdict("pr", self.data(check_run("ci")), "green", self.SHA, now=NOW))

    def test_an_empty_head_inside_the_settle_window_is_not_started(self) -> None:
        data = self.data(pushed=NOW - 60)
        self.assertIsNone(gg.verdict("pr", data, "green", self.SHA, now=NOW))
        self.assertIn("not started", gg.summary("pr:o/r#3538", {"data": data}))
        # past the window it says nothing reported, a distinct code, never success
        late = NOW - 60 + gg.SETTLE_GRACE + 1
        self.assertEqual(gg.verdict("pr", data, "green", self.SHA, now=late), gg.EXIT_NOTHING)
        self.assertNotIn(gg.EXIT_NOTHING, (gg.EXIT_OK, gg.EXIT_FAIL, gg.EXIT_TIMEOUT, gg.EXIT_DOWN, gg.EXIT_CONFLICT))
        self.assertEqual(gg.verdict("pr", data, "green", self.SHA, now=NOW, settle=30), gg.EXIT_NOTHING)
        # the daemon's first sighting of the head bounds the push when the PR's updatedAt moved later (a comment)
        seen = {**self.data(pushed=NOW), "headSeenAt": NOW - gg.SETTLE_GRACE - 5}
        self.assertEqual(gg.verdict("pr", seen, "green", self.SHA, now=NOW), gg.EXIT_NOTHING)

    def test_green_statuses_and_green_checks_are_success(self) -> None:
        data = self.data(check_run("build"), check_run("lint", conclusion="SKIPPED"), status_context("ci/legacy"),
                         pushed=NOW - 5)
        for until in ("green", "done", "required"):
            self.assertEqual(gg.verdict("pr", data, until, self.SHA, now=NOW), gg.EXIT_OK, until)

    def test_the_wait_says_so(self) -> None:
        key = "pr:o/r#3538"
        req = gg.wait_request("pr", "o/r#3538", "green", 60, False, False, self.SHA, True, gg.RESCUE_GRACE, settle=0)
        req["began"] = NOW - 5

        def cached(data: dict) -> None:
            gg.write_json(gg.cache_dir() / gg.file_name(key),
                          {"key": key, "fetchedAt": NOW, "dataAt": NOW, "data": data, "error": None})

        cached(self.data(check_run("GitGuardian Security Checks"), status_context("ws-check", "PENDING")))
        self.assertIsNone(gg.wait_step(req, NOW))
        cached(self.data(pushed=NOW - 60))
        code, text = gg.wait_step(req, NOW)
        self.assertEqual(code, gg.EXIT_NOTHING)
        self.assertIn("result: nothing-reported", text)
        self.assertIn("not a pass", text)
        cached(self.data(check_run("GitGuardian Security Checks"), status_context("ws-check")))
        self.assertEqual(gg.wait_step(req, NOW)[0], gg.EXIT_OK)

    def test_the_daemon_keeps_the_first_sighting_of_a_head(self) -> None:
        key = "pr:o/r#3538"
        self.daemon.now = NOW - 100
        self.daemon.store(key, None, data={"headRefOid": "a" * 40, "checks": []}, dataAt=NOW - 100)
        self.assertEqual(gg.read_cache(key)["data"]["headSeenAt"], NOW - 100)
        self.daemon.now = NOW
        self.daemon.store(key, None, data={"headRefOid": "a" * 40, "checks": []}, dataAt=NOW)
        self.assertEqual(gg.read_cache(key)["data"]["headSeenAt"], NOW - 100)
        self.daemon.store(key, None, data={"headRefOid": "b" * 40, "checks": []}, dataAt=NOW)
        self.assertEqual(gg.read_cache(key)["data"]["headSeenAt"], NOW)


class ExpectedUnpostedTest(Base):
    """teamleaderleo/leo-workspace#8794 at 31a84d01 (2026-11-23): one `wait pr` spent 2401 s and ended `ended_by:
    no-progress`, `progress_changes: 0`, on a PR that was MERGEABLE (CLEAN) with a SUCCESS rollup, 1 of 1 checks
    passed, 0 required, and ws-check -- expected, required by nothing, published by one timer -- the only thing
    absent. Its `next:` was the same wait with the same `--timeout 2400 --max 9600`.
    docs/handbook/done-wait-held-by-stragglers.md: a done wait ends once every check that decides has ended, and
    names what it ended without."""

    SHA = "31a84d018232f37cf187b49c6499bde10f2c2e5d"
    REPO = "teamleaderleo/leo-workspace"
    KEY = f"pr:{REPO}#8794"
    LAND = f"glaeda-gh land {REPO}#8794 --match-head-commit {SHA}"

    def head(self, pushed: float, *nodes: dict, required: list[str] | None = None, rollup: str = "SUCCESS") -> dict:
        """#8794's state as the cache held it: CLEAN, one passed check, nothing required, ws-check not posted."""
        node = pr_node(8794, rollup=rollup, checks=list(nodes) or [check_run("GitGuardian Security Checks")])
        node.update(url=f"https://github.com/{self.REPO}/pull/8794", headRefOid=self.SHA, mergeable="MERGEABLE",
                    mergeStateStatus="CLEAN", updatedAt=iso(pushed))
        data = gg.parse_pr(node)
        data["requiredNames"] = list(required or [])
        return data

    def request(self, timeout: float = 2400.0) -> dict:
        req = gg.wait_request("pr", f"{self.REPO}#8794", "done", timeout, False, False, self.SHA, True,
                              gg.RESCUE_GRACE, ceiling=9600.0)
        req["began"] = NOW - 2401
        return req

    def test_8794_an_unposted_expected_context_nothing_requires_does_not_hold_a_done_wait(self) -> None:
        data = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1)
        self.assertEqual(gg.expected_missing(data), ["ws-check"])
        self.assertEqual(gg.expected_unposted(data, NOW), ["ws-check"])
        for until in ("green", "done", "required"):
            # its own value: never folded into the pass that EXIT_OK is or the failure that EXIT_FAIL is
            self.assertEqual(gg.verdict("pr", data, until, self.SHA, now=NOW), gg.EXIT_INCONCLUSIVE, until)
        self.assertNotIn(gg.EXIT_INCONCLUSIVE, (gg.EXIT_OK, gg.EXIT_FAIL, gg.EXIT_TIMEOUT))
        out = gg.wait_outcome(self.request(), gg.EXIT_INCONCLUSIVE, {"data": data}, 2401)
        self.assertEqual(out["code"], "expected-unposted")
        self.assertIn("ws-check", out["reason"])
        self.assertIn("nothing requires it", out["reason"])
        self.assertIn("not a pass", out["reason"])
        self.assertIn("land-judge still counts it", out["reason"])
        # the step is the land queue pinned to the head this wait read: it judges that head and holds the row
        self.assertEqual(out["next"], self.LAND)
        self.assertNotEqual(out["next"], gg.wait_command(self.request()))
        self.assertIn("ws-check", gg.inconclusive_note(data, NOW))
        self.assertIn("expected, not posted yet: ws-check", gg.summary(self.KEY, {"data": data}))
        self.assertIn("a wait ends without them", gg.summary(self.KEY, {"data": data}))

    def test_this_state_takes_the_exit_code_that_already_means_no_verdict(self) -> None:
        """The value is not new and is not a red: EXIT_INCONCLUSIVE is the code the stragglers incident created
        (docs/handbook/done-wait-held-by-stragglers.md) and the one `glaeda-gh wait`'s callers already bucket as
        neither pass nor fail. A thing with no verdict read as a red is the failure this lane has fixed four times;
        this pins that nobody quietly turns this state into one."""
        self.assertEqual(gg.EXIT_INCONCLUSIVE, 7)
        data = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1)
        self.assertEqual(gg.verdict("pr", data, "done", self.SHA, now=NOW), gg.EXIT_INCONCLUSIVE)
        # the same word the stragglers case already renders (status_view, origin/main): INCONCLUSIVE, never FAILURE
        said = gg.summary(self.KEY, {"data": data})
        self.assertNotIn("FAILURE", said)
        self.assertIn("checks INCONCLUSIVE", said)
        out = gg.wait_outcome(self.request(), gg.EXIT_INCONCLUSIVE, {"data": data}, 2401)
        self.assertFalse(out["ok"])
        self.assertNotIn(out["code"], ("fail", "timeout", "ok"))

    def test_it_still_holds_the_wait_while_the_publisher_may_still_post_it(self) -> None:
        # leo-workspace#3538: the head was pushed at 14:02 and ws-check went pending at 14:28:31 (26.5 min)
        data = self.head(NOW - 1590)
        self.assertEqual(gg.expected_unposted(data, NOW), [])
        self.assertIsNone(gg.verdict("pr", data, "done", self.SHA, now=NOW))
        self.assertNotIn("a wait ends without them", gg.summary(self.KEY, {"data": data}))
        # nor when the push cannot be placed at all
        blind = {**self.head(NOW - 9999), "updatedAt": None, "headSeenAt": None}
        self.assertEqual(gg.expected_unposted(blind, NOW), [])

    def test_a_required_context_in_the_same_state_never_ends_the_wait(self) -> None:
        old = NOW - gg.EXPECTED_UNPOSTED_AFTER - 1
        for required in (["ws-check"],):
            data = self.head(old, required=required)
            self.assertEqual(gg.expected_unposted(data, NOW), [])
            self.assertIsNone(gg.verdict("pr", data, "done", self.SHA, now=NOW))
        held = self.head(old)
        held["requiredMissing"] = ["ws-check"]
        self.assertEqual(gg.expected_unposted(held, NOW), [])
        unread = self.head(old)
        unread["requiredUnread"] = ["ws-check"]
        self.assertEqual(gg.expected_unposted(unread, NOW), [])

    def test_the_detector_that_names_a_stuck_check_also_names_the_one_never_posted(self) -> None:
        """One enumeration of the absences: #2564's lone pending check got "usually stuck, not slow", which check and
        a run to look at; #8794's never-posted context got silence. Same detector, both absences."""
        done = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1)
        note = gg.stuck_note(self.KEY, {"data": done}, gg.WAIT_STUCK_AFTER, gg.RESCUE_GRACE, NOW)
        self.assertIsNotNone(note)
        self.assertIn("never posted: ws-check", note)
        self.assertIn("ends without it", note)
        self.assertIn(f"next: {self.LAND}", note)
        self.assertNotIn("glaeda-gh wait pr", note)
        # and while it may still arrive, the step is the bound after which this tool answers differently
        young = self.head(NOW - 1590)
        soon = gg.stuck_note(self.KEY, {"data": young}, gg.WAIT_STUCK_AFTER, gg.RESCUE_GRACE, NOW)
        self.assertIn("never posted: ws-check", soon)
        self.assertIn("may still arrive", soon)
        self.assertIn("next: glaeda-gh wait until ", soon)
        self.assertIn("glaeda-gh status pr", soon)
        self.assertNotIn("glaeda-gh wait pr", soon)

    def test_a_check_that_is_genuinely_still_running_keeps_the_wait(self) -> None:
        data = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1, check_run("GitGuardian Security Checks"),
                         check_run("build", "IN_PROGRESS", None), rollup="PENDING")
        self.assertIsNone(gg.verdict("pr", data, "done", self.SHA, now=NOW), "a running check still decides")
        red = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1, check_run("build", "COMPLETED", "FAILURE"),
                        rollup="FAILURE")
        self.assertEqual(gg.verdict("pr", red, "done", self.SHA, now=NOW), gg.EXIT_FAIL, "a red is still a red")

    def test_the_wait_ends_on_its_first_read_instead_of_spending_its_timeout(self) -> None:
        """The measured bug: 2401 s and no answer. On the same state the wait now answers at its first read."""
        data = self.head(NOW - gg.EXPECTED_UNPOSTED_AFTER - 1)
        gg.write_json(gg.cache_dir() / gg.file_name(self.KEY),
                      {"key": self.KEY, "fetchedAt": NOW, "dataAt": NOW, "data": data, "error": None})
        req = self.request()
        req["began"] = NOW - 1  # one second in, far inside its 2400 s no-progress budget and its 9600 s ceiling
        done = gg.wait_step(req, NOW)
        self.assertIsNotNone(done, "a wait with nothing left to learn must not sit out its timeout")
        code, text = done
        self.assertEqual(code, gg.EXIT_INCONCLUSIVE)
        self.assertIn("result: inconclusive", text)
        self.assertIn("ws-check", text)
        self.assertIn("not a pass", text)
        self.assertIn(f"next: {self.LAND}", text)
        self.assertNotIn("result: timeout", text)
        self.assertNotIn(f"next: {gg.wait_command(req)}", text)


class TimeoutNextStepTest(Base):
    """docs/handbook/wait-that-cannot-end.md over every `next:` this wait path can print: a wait that ended with
    nothing moving never names itself. #8794 printed `next: glaeda-gh wait pr ... --timeout 2400 --max 9600` after
    2401 s with `progress_changes: 0`; an agent that takes it waits another 2400 s on the same unchanged state."""

    SHA = "3" * 40

    def request(self, timeout: float = 2400.0) -> dict:
        req = gg.wait_request("pr", "o/r#8794", "done", timeout, False, False, self.SHA, True, gg.RESCUE_GRACE,
                              ceiling=9600.0)
        req["began"] = NOW - 2401
        req["moved"] = {"at": NOW - 2401, "changes": 0}  # nothing moved for the whole wait
        return req

    def head(self, *nodes: dict, repo: str = "o/r", rollup: str = "PENDING", counts: dict | None = None,
             pushed: float = 0.0) -> dict:
        node = pr_node(8794, rollup=rollup, checks=list(nodes))
        node.update(url=f"https://github.com/{repo}/pull/8794", headRefOid=self.SHA, mergeStateStatus="CLEAN",
                    updatedAt=iso(pushed or NOW - 3600))
        data = gg.parse_pr(node)
        if counts:
            data.update(checksTruncated=True, checkCounts=counts)
        return data

    def states(self) -> list[tuple[str, dict | None]]:
        """Every shape this wait can time out on with nothing moving."""
        return [
            ("nothing read at all", None),
            ("a check still pending", {"data": self.head(check_run("build", "IN_PROGRESS", None))}),
            ("every check passed", {"data": self.head(check_run("build"), rollup="SUCCESS")}),
            ("an expected context never posted",
             {"data": self.head(check_run("GitGuardian Security Checks"), repo="teamleaderleo/leo-workspace",
                                rollup="SUCCESS")}),
            ("unfinished past the first 100",
             {"data": self.head(*[check_run(f"c{i}") for i in range(100)], rollup="PENDING",
                                counts={"runs": {"SUCCESS": 100, "QUEUED": 3}, "statuses": {}})}),
        ]

    def test_a_no_progress_timeout_never_names_the_wait_that_just_ended(self) -> None:
        req = self.request()
        again = gg.wait_command(req)
        self.assertEqual(gg.wait_ended_by(req, NOW), "no-progress")
        for why, entry in self.states():
            with self.subTest(state=why):
                nxt = gg.wait_outcome(req, gg.EXIT_TIMEOUT, entry, 2401)["next"]
                self.assertNotEqual(nxt, again, why)
                self.assertNotIn("glaeda-gh wait pr", nxt, f"{why}: it named a wait on the state that did not move")
                self.assertTrue(nxt.startswith(("glaeda-gh", "gh ")), nxt)

    def test_a_wait_still_moving_at_its_ceiling_may_name_itself(self) -> None:
        """The one allowed self-naming, kept honest: a wait whose target kept changing can end next time."""
        req = self.request()
        req["began"] = NOW - 9601  # at its --max, and still moving ten seconds ago
        req["moved"] = {"at": NOW - 10, "changes": 7}
        self.assertEqual(gg.wait_ended_by(req, NOW), "ceiling")
        out = gg.wait_outcome(req, gg.EXIT_TIMEOUT, {"data": self.head(check_run("build", "IN_PROGRESS", None))}, 9601)
        self.assertEqual(out["next"], gg.wait_command(req))
        self.assertIn("still changing", out["reason"])


class PinnedHeadStatedTest(Base):
    """teamleaderleo/glaeda#2564 (3700 s, 2026-11-23): the wait was pinned `--sha 41092a54...`, which was never the
    head in those 3700 s. Every line it printed was about 4ce5d079 and later ca129622, and none of them said the state
    being reported was not the commit the caller pinned. A pin is an assertion about which commit matters; a wait may
    wait for a push GitHub has not seen, but not silently."""

    PIN = "41092a541e1b43d4c696f2d5704a7f1c8803a943"
    HEAD = "4ce5d07926" + "0" * 30
    KEY = "pr:teamleaderleo/glaeda#2564"

    def data(self, head: str) -> dict:
        node = pr_node(2564, rollup="PENDING", checks=[check_run("Verify / scripts", "IN_PROGRESS", None)])
        node.update(url="https://github.com/teamleaderleo/glaeda/pull/2564", headRefOid=head)
        return gg.parse_pr(node)

    def test_a_pinned_commit_that_is_not_the_head_is_named_beside_the_head_it_reports(self) -> None:
        said = gg.progress_state(self.KEY, {"data": self.data(self.HEAD)}, "done", gg.RESCUE_GRACE, self.PIN)
        self.assertIn(self.PIN[:10], said)
        self.assertIn(self.HEAD[:10], said)
        self.assertIn("is not the head GitHub shows", said)

    def test_it_says_nothing_when_the_pin_is_the_head_or_is_no_full_commit(self) -> None:
        entry = {"data": self.data(self.PIN)}
        self.assertIsNone(gg.pin_mismatch(self.PIN, entry["data"]))
        self.assertNotIn("is not the head GitHub shows",
                         gg.progress_state(self.KEY, entry, "done", gg.RESCUE_GRACE, self.PIN))
        for pin in (None, "", "41092a5", "green", "HEAD"):
            self.assertIsNone(gg.pin_mismatch(pin, self.data(self.HEAD)), pin)

    def test_the_wait_itself_carries_it_on_its_first_progress_line(self) -> None:
        req = gg.wait_request("pr", "teamleaderleo/glaeda#2564", "done", 1800.0, False, False, self.PIN, True,
                              gg.RESCUE_GRACE, ceiling=9600.0)
        seen: dict = {}
        first = gg.progress_update(seen, req, {"data": self.data(self.HEAD)}, NOW)
        self.assertIn(self.PIN[:10], first or "")
        self.assertIn(self.HEAD[:10], first or "")


class UnseenPinnedShaTest(Base):
    """efficiency-standing-lane, 2026-11-23: a wait on teamleaderleo/leo-workspace#9346 was armed with a full
    id padded out of a short one -- a commit that exists in no checkout and that GitHub never showed -- and it was
    accepted, to wait out all 3600 s and then print a note naming the head it had seen the whole time. A full id may
    be a push GitHub has not seen (resolve_sha), but one that is in no checkout here either is a typo or another
    repo's commit (land --match-head-commit from the wrong worktree), and such a wait can only time out."""

    PIN = "a" * 40
    HEAD = "b" * 40
    KEY = "pr:o/r#9346"

    def request(self) -> dict:
        req = gg.wait_request("pr", "o/r#9346", "green", 3600.0, False, False, self.PIN, True, gg.RESCUE_GRACE,
                              settle=0)
        req["began"] = NOW - 5
        return req

    def cache(self, head: str) -> None:
        node = pr_node(9346, rollup="PENDING", checks=[check_run("ws-check", "IN_PROGRESS", None)])
        node.update(url="https://github.com/o/r/pull/9346", headRefOid=head)
        gg.write_json(gg.cache_dir() / gg.file_name(self.KEY),
                      {"key": self.KEY, "fetchedAt": NOW, "dataAt": NOW, "data": gg.parse_pr(node), "error": None})

    def test_a_pin_in_no_checkout_that_is_never_the_head_is_refused_at_the_grace(self) -> None:
        req = self.cache(self.HEAD) or self.request()
        with mock.patch.object(gg, "git_rev_parse", return_value=None):
            self.assertIsNone(gg.wait_step(req, NOW), "inside the grace it is still an unseen push")
            with self.assertRaises(gg.WatchError) as caught:
                gg.wait_step(req, NOW + gg.UNSEEN_SHA_GRACE + 1)
        said = str(caught.exception)
        self.assertIn(self.HEAD[:12], said, "it names the head GitHub does show")
        self.assertIn(self.PIN[:12], said)

    def test_a_pin_this_checkout_holds_keeps_waiting_for_the_push(self) -> None:
        req = self.cache(self.HEAD) or self.request()
        with mock.patch.object(gg, "git_rev_parse", return_value=self.PIN):
            self.assertIsNone(gg.wait_step(req, NOW))
            self.assertIsNone(gg.wait_step(req, NOW + gg.UNSEEN_SHA_GRACE * 10),
                              "a commit that exists here may still be pushed")

    def test_the_clock_starts_over_once_the_head_catches_up(self) -> None:
        req = self.cache(self.HEAD) or self.request()
        with mock.patch.object(gg, "git_rev_parse", return_value=None):
            self.assertIsNone(gg.wait_step(req, NOW))
            self.assertEqual(req["unseenSince"], NOW)
            self.cache(self.PIN)
            gg.wait_step(req, NOW + 1)
            self.assertIsNone(req.get("unseenSince"), "the pin became the head: nothing left to refuse")


class StatusStateTest(unittest.TestCase):
    """cmuxterm-hq#8968 review (2026-11-10): a head's data folded a status `error` into `failure`, the same answer a
    real red gives, so a reader could not tell a poster that gave no verdict (compile-status with the results service
    down) from a failed check. `found` keeps the fold (every gate reads `error` as red), and `statusStates` keeps each
    status's own state beside it."""

    def test_an_error_status_is_red_in_found_and_error_in_status_states(self) -> None:
        runs: dict = {}
        statuses: dict = {}
        ids: dict = {}
        gg.fold_contexts([status_context("cmux-next/compile", "ERROR"), status_context("ci/red", "FAILURE"),
                          status_context("ci/wait", "PENDING"), status_context("ci/ok", "SUCCESS")],
                         runs, statuses, ids)
        data = gg.head_data("a" * 40, runs, statuses, ids)
        self.assertEqual(data["found"]["status / cmux-next/compile"], ["completed", "failure"])
        self.assertEqual(data["found"]["status / ci/red"], ["completed", "failure"])
        self.assertEqual(data["statusStates"], {"status / cmux-next/compile": "error", "status / ci/red": "failure",
                                                "status / ci/wait": "pending", "status / ci/ok": "success"})
        self.assertFalse(data["settled"])

    def test_the_rest_path_keeps_the_state_too(self) -> None:
        nodes = gg.rest_contexts({"check_runs": []}, [{"context": "cmux-next/compile", "state": "error"}], [], set())
        runs: dict = {}
        statuses: dict = {}
        gg.fold_contexts(nodes, runs, statuses, {})
        self.assertEqual(gg.head_data("b" * 40, runs, statuses, {})["statusStates"],
                         {"status / cmux-next/compile": "error"})


class HeadRunOrderTest(unittest.TestCase):
    """head_data's `runs` (head_data's `runs`): every check run at a head with its own id and times, over GraphQL and
    REST alike, and `checks --json` serves it, so a reader can order a replay against its shard's newest rerun from the
    cache (leo-workspace merge_hold's webview verdict; cmux#46128, #46236, #46782 sat 6 h on green heads)."""

    @staticmethod
    def node(name: str, ident: int, started: str, done: str, conclusion: str = "SUCCESS") -> dict:
        return {"__typename": "CheckRun", "databaseId": ident, "name": name, "status": "COMPLETED",
                "conclusion": conclusion, "startedAt": started, "completedAt": done,
                "checkSuite": {"app": {"slug": "github-actions"}, "databaseId": 5,
                               "workflowRun": {"databaseId": 900 + ident, "event": "pull_request",
                                               "workflow": {"name": "CI", "databaseId": 77}}}}

    def test_graphql_nodes_keep_every_run_with_its_id_and_times(self) -> None:
        runs: dict = {}
        statuses: dict = {}
        order: dict = {}
        gg.fold_contexts([self.node("web / react-apps-check (1)", 20, "2026-11-20T02:00:00Z", "2026-11-20T02:10:00Z"),
                          self.node("web / react-apps-check (1)", 10, "2026-11-20T01:00:00Z", "2026-11-20T01:10:00Z",
                                    "FAILURE")], runs, statuses, {}, order=order)
        data = gg.head_data("a" * 40, runs, statuses, {}, order)
        self.assertEqual(data["found"]["CI / web / react-apps-check (1)"], ["completed", "success"])
        self.assertEqual(data["runs"]["CI / web / react-apps-check (1)"],
                         [[10, "completed", "failure", "2026-11-20T01:00:00Z", "2026-11-20T01:10:00Z",
                           {"run": 910, "workflow": 77, "workflowName": "CI", "event": "pull_request", "app": "github-actions", "suite": 5}],
                          [20, "completed", "success", "2026-11-20T02:00:00Z", "2026-11-20T02:10:00Z",
                           {"run": 920, "workflow": 77, "workflowName": "CI", "event": "pull_request", "app": "github-actions", "suite": 5}]])
        self.assertIn("completedAt", gg.HEAD_CONTEXTS)  # the GraphQL read asks for both times

    def test_a_failed_run_stores_its_job_step_count_once(self) -> None:
        """land-judge judges a stored red as a live one (runner_refused: a failed job with no step run is the runner's
        refusal): each failure row's identity gets `steps`, read once per job by node id; a read that fails leaves
        it absent (unknown, never 0)."""
        runs: dict = {}
        order: dict = {}
        failed: dict = {}
        nodes = [{**self.node("web / a", 10, "t0", "t1", "FAILURE"), "id": "CR_10"},
                 {**self.node("web / b", 11, "t0", "t1", "FAILURE"), "id": "CR_11"},
                 {**self.node("web / c", 12, "t0", "t1"), "id": "CR_12"}]
        gg.fold_contexts(nodes, runs, {}, {}, order=order, failed=failed)
        self.assertEqual(failed, {10: "CR_10", 11: "CR_11"})  # only failures
        asked: list = []

        def graphql(query: str, variables: dict, _route: list | None = None) -> tuple:
            asked.append(variables["ids"])
            return {"data": {"nodes": [{"id": "CR_10", "steps": {"nodes": []}},
                                       {"id": "CR_11", "steps": {"nodes": [{"name": "x"}, {"name": "y"}]}}]}}, None

        fake = types.SimpleNamespace(job_steps={}, gql_reason=None, errors=[], mode=lambda bucket: "go", graphql_stopped_for=lambda *a: False,
                                     graphql=graphql)
        data = gg.head_data("a" * 40, runs, {}, {}, order)
        gg.Daemon.head_steps(fake, data, failed)
        rows = {r[0]: r for rs in data["runs"].values() for r in rs}
        self.assertEqual((rows[10][5]["steps"], rows[11][5]["steps"]), (0, 2))
        self.assertNotIn("steps", rows[12][5])
        gg.Daemon.head_steps(fake, data, failed)  # a completed job never changes: not read again
        self.assertEqual(asked, [["CR_10", "CR_11"]])
        down = types.SimpleNamespace(job_steps={}, gql_reason=None, errors=[], mode=lambda bucket: "go", graphql_stopped_for=lambda *a: False,
                                     graphql=lambda q, v, _route=None: (None, "graphql: down"))
        again = gg.head_data("a" * 40, runs, {}, {}, order)
        again["runs"] = {k: [[*r[:5], {k2: v for k2, v in r[5].items() if k2 != "steps"}] for r in rs]
                         for k, rs in again["runs"].items()}
        gg.Daemon.head_steps(down, again, failed)
        self.assertTrue(all("steps" not in r[5] for rs in again["runs"].values() for r in rs))
        self.assertIn("id databaseId", gg.HEAD_CONTEXTS)  # the read asks for the node id

    def test_rest_nodes_keep_them_too_and_no_order_writes_none(self) -> None:
        nodes = gg.rest_contexts({"check_runs": [{"id": 7, "name": "web / react-apps-base-check", "status": "completed",
                                                  "conclusion": "success", "started_at": "2026-11-20T03:00:00Z",
                                                  "completed_at": "2026-11-20T03:05:00Z", "app": "github-actions",
                                                  "suite": 3}]},
                                 [], [], set())
        runs: dict = {}
        order: dict = {}
        gg.fold_contexts(nodes, runs, {}, {}, order=order)
        self.assertEqual(gg.head_data("b" * 40, runs, {}, {}, order)["runs"],
                         {"github-actions / web / react-apps-base-check":
                          [[7, "completed", "success", "2026-11-20T03:00:00Z", "2026-11-20T03:05:00Z",
                            {"app": "github-actions", "suite": 3}]]})
        self.assertNotIn("runs", gg.head_data("b" * 40, runs, {}, {}))

    def test_each_row_keeps_its_run_identity_over_rest_and_graphql(self) -> None:
        """land-judge's head checks read the cache first and collapse attempts by run as a live rollup read does:
        each row names its Actions run, workflow, event, app and suite; a lastRealAttempt row and a null app say so."""
        doc = {"workflow_runs": [{"id": 41, "name": "CI", "workflow_id": 77, "check_suite_id": 3,
                                  "conclusion": "success", "event": "pull_request", "status": "completed"}]}
        runs_kept = gg.slim_head_runs(doc)
        self.assertEqual(runs_kept[0]["event"], "pull_request")
        nodes = gg.rest_contexts({"check_runs": [{"id": 7, "name": "build", "status": "completed",
                                                  "conclusion": "success", "started_at": "2026-11-20T03:00:00Z",
                                                  "completed_at": "2026-11-20T03:05:00Z", "app": "github-actions",
                                                  "suite": 3}]}, [], runs_kept, set(), {"77": "CI"})
        order: dict = {}
        gg.fold_contexts(nodes, {}, {}, {}, order=order)
        self.assertEqual(order["CI / build"][0][5], {"run": 41, "workflow": 77, "workflowName": "CI", "event": "pull_request",
                                                     "app": "github-actions", "suite": 3})
        late = {**self.node("build", 30, "2026-11-20T04:00:00Z", "2026-11-20T04:01:00Z"), "lastRealAttempt": True,
                "isRequired": True}
        bare = {"__typename": "CheckRun", "databaseId": 31, "name": "lint", "status": "COMPLETED",
                "conclusion": "SUCCESS", "startedAt": "2026-11-20T04:00:00Z", "completedAt": "2026-11-20T04:01:00Z",
                "checkSuite": {"app": None, "databaseId": 8, "workflowRun": None}}
        order = {}
        gg.fold_contexts([late, bare], {}, {}, {}, order=order)
        self.assertEqual(order["CI / build"][0][5], {"run": 930, "workflow": 77, "workflowName": "CI", "event": "pull_request",
                                                     "app": "github-actions", "suite": 5, "lastRealAttempt": True})
        self.assertEqual(order["check / lint"][0][5], {"suite": 8, "appNull": True})

    def test_a_status_keeps_its_description_over_rest_and_graphql(self) -> None:
        statuses: dict = {}
        gg.fold_contexts([{"__typename": "StatusContext", "context": "cmux-next/fast-gates", "state": "SUCCESS",
                           "description": "passed at base 1234567"}], {}, statuses, {})
        nodes = gg.rest_contexts({"check_runs": []}, gg.slim_statuses(
            {"statuses": [{"context": "ws-check", "state": "pending", "description": "in line"}]}), [], set())
        gg.fold_contexts(nodes, {}, statuses, {})
        data = gg.head_data("c" * 40, {}, statuses, {})
        self.assertEqual(data["statusDescriptions"], {"status / cmux-next/fast-gates": "passed at base 1234567",
                                                      "status / ws-check": "in line"})
        self.assertEqual(data["statusStates"]["status / ws-check"], "pending")


class FakeController:
    """Stands in for the cmux build controller: /v1/github/runs/<id> and the change feed. A change
    to `runs` shows up in the feed, as a webhook delivery would; suites and comments are queued."""

    def __init__(self) -> None:
        self.runs: dict[int, dict] = {}
        self.suites: list[dict] = []
        self.comments: list[dict] = []
        self.calls: list[int] = []  # run() reads
        self.feeds: list[int | None] = []  # events() reads, by cursor
        self.down = False
        self.token = "t"
        self.seq = 0
        self.sent: dict[int, dict] = {}

    def fail(self) -> None:
        if self.down:
            raise self.down if isinstance(self.down, gg.WatchError) else gg.WatchError("controller: URLError")

    def run(self, run_id: int) -> dict | None:
        self.calls.append(run_id)
        self.fail()
        return self.runs.get(run_id)

    def events(self, since: int | None) -> dict:
        self.feeds.append(since)
        self.fail()
        changed = [dict(r) for i, r in self.runs.items() if self.sent.get(i) != r]
        self.sent = {i: dict(r) for i, r in self.runs.items()}
        page = {"cursor": self.seq, "more": False, "runs": [], "suites": [], "comments": [],
                "receiver_last_delivery": "2026-09-25T10:00:00Z"}
        if since is None:  # the start: only the cursor
            self.suites, self.comments = [], []
            return page
        self.seq += len(changed) + len(self.suites) + len(self.comments)
        page.update(cursor=self.seq, runs=changed, suites=self.suites, comments=self.comments)
        self.suites, self.comments = [], []
        return page


def ctl_run(run_id: int, status: str, conclusion: str = "", updated: str = "2026-09-25T10:00:00Z", repo: str = "o/r") -> dict:
    return {"id": run_id, "repo": repo, "name": "seed", "event": "workflow_dispatch", "head_sha": "a" * 40,
            "attempt": 1, "status": status, "conclusion": conclusion, "url": f"https://x/{run_id}", "updated_at": updated}


class ControllerTest(Base):
    def setUp(self) -> None:
        super().setUp()
        self.ctl = FakeController()
        feed_every, gg.CONTROLLER_FEED_EVERY = gg.CONTROLLER_FEED_EVERY, 0  # these tests read the feed each tick
        self.addCleanup(setattr, gg, "CONTROLLER_FEED_EVERY", feed_every)
        self.daemon = gg.Daemon(transport=self.gh, token=lambda: TOKEN, controller=self.ctl)

    def test_a_controller_request_ends_at_the_ticks_controller_budget(self) -> None:
        # air-blue 2026-11-18 22:4xZ: 17.1 of a 19.1 s tick went to a controller answering TimeoutError. A controller
        # that accepts the connection and never answers is cut at the budget the daemon gave this tick, not at
        # CONTROLLER_READ_TIMEOUT per request.
        hole = socket.socket()
        hole.bind(("127.0.0.1", 0))
        hole.listen(8)
        self.addCleanup(hole.close)
        ctl = gg.Controller(f"http://127.0.0.1:{hole.getsockname()[1]}", None)
        ctl.budget_end = time.monotonic() + 0.5
        began = time.monotonic()
        with self.assertRaises(gg.WatchError):
            ctl.events(5)
        self.assertLess(time.monotonic() - began, 1.5)

    def test_no_controller_request_starts_that_the_budget_would_cut(self) -> None:
        # #2201 review: a request started with less than a whole request's deadline left is cut by the daemon's own
        # budget, and that cut reads as the controller failing. It waits for the next tick instead. The allowance is
        # the read deadline: the read is the part a slow answer spends, and waiting it out is what keeps the run it
        # carries off the shared REST quota.
        self.daemon.controller_budget_end = time.monotonic() + gg.CONTROLLER_READ_TIMEOUT - 0.5
        self.assertFalse(self.daemon.controller_room())
        self.daemon.controller_budget_end = time.monotonic() + gg.CONTROLLER_READ_TIMEOUT + 0.5
        self.assertTrue(self.daemon.controller_room())
        # and one whole request has to fit in the budget at all, or no tick would ever reach the controller
        self.assertLessEqual(gg.CONTROLLER_READ_TIMEOUT, gg.CONTROLLER_TICK_BUDGET)

    def slow_controller(self, delay: float, once: bool = True) -> Any:
        """A controller that accepts at once and then takes `delay` seconds over its first answer (`once`) or
        every one. Answers the two paths a tick reads: the change feed and a run's state."""
        import http.server
        state = {"delay": delay, "runs": {21: ctl_run(21, "in_progress")}}

        class Handler(http.server.BaseHTTPRequestHandler):
            protocol_version = "HTTP/1.0"

            def log_message(self, *args: Any) -> None:
                pass

            def do_GET(self) -> None:
                time.sleep(state["delay"])
                if once:
                    state["delay"] = 0.0
                split = urllib.parse.urlsplit(self.path)
                if split.path.startswith("/v1/github/runs/"):
                    run = state["runs"].get(int(split.path.rsplit("/", 1)[1]))
                    doc: dict = {"known": run is not None, "run": run}
                else:
                    since = urllib.parse.parse_qs(split.query).get("since")
                    doc = {"cursor": 1, "more": False, "suites": [], "comments": [],
                           "runs": [] if since is None else list(state["runs"].values()),
                           "receiver_last_delivery": "2026-09-25T10:00:00Z"}
                body = json.dumps(doc).encode()
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self.send_header("Content-Length", str(len(body)))
                self.end_headers()
                self.wfile.write(body)

        server = http.server.ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        threading.Thread(target=server.serve_forever, daemon=True).start()
        self.addCleanup(server.server_close)
        self.addCleanup(server.shutdown)
        return gg.Controller(f"http://127.0.0.1:{server.server_address[1]}", None)

    def test_an_unreachable_controller_fails_at_the_connect_deadline(self) -> None:
        # The original point of one 3 s timeout: a tick must not stall on a controller that is not there. Splitting
        # it kept that in CONTROLLER_CONNECT_TIMEOUT, and this holds the line: a connect that never completes costs
        # the connect deadline, nowhere near the read deadline an answering controller is given.
        wall = socket.socket()
        wall.bind(("127.0.0.1", 0))
        wall.listen(1)  # a full backlog: the kernel drops the handshake, so connect hangs rather than refusing
        self.addCleanup(wall.close)
        port = wall.getsockname()[1]
        for _ in range(64):
            held = socket.socket()
            self.addCleanup(held.close)
            held.setblocking(False)
            held.connect_ex(("127.0.0.1", port))
        ctl = gg.Controller(f"http://127.0.0.1:{port}", None)
        began = time.monotonic()
        with self.assertRaises(gg.WatchError):
            ctl.events(None)
        took = time.monotonic() - began
        self.assertLess(took, gg.CONTROLLER_CONNECT_TIMEOUT + 0.5)
        self.assertLess(took, gg.CONTROLLER_READ_TIMEOUT)  # the read deadline is not what an absent host costs

    def test_a_slow_but_alive_controller_is_served_locally_and_spends_no_rest(self) -> None:
        # The defect: an answer slower than the old 3 s timeout was given up on, and every run read it would have
        # served went to the shared REST quota instead. It is now waited out, so no quota is spent.
        slow = 3.4
        self.assertGreater(slow, 3.0)  # slower than the timeout this replaced
        self.assertLess(slow, gg.CONTROLLER_READ_TIMEOUT)  # inside the read deadline that replaced it
        ctl = self.slow_controller(slow)
        daemon = gg.Daemon(transport=self.gh, token=lambda: TOKEN, controller=ctl)
        gg.register(gg.parse_key("run", "o/r/21"))
        began = time.monotonic()
        for i in range(3):
            daemon.tick(NOW + i * gg.CYCLE)
        self.assertGreater(time.monotonic() - began, slow)  # it waited the slow answer out
        self.assertEqual(daemon.controller_cursor, 1)  # and was served: the feed's cursor is the controller's
        self.assertEqual(self.gh.rest_calls(), [])  # the slow answer cost no REST
        self.assertEqual(daemon.controller_fallback, {})  # and counted no fallback
        self.assertEqual((daemon.controller_down_until, daemon.controller_failures), (0.0, 0))

    def test_a_controller_slower_than_the_read_deadline_still_falls_back(self) -> None:
        # The read deadline is a deadline, not a licence to wait: past it the fallback happens as before, and the
        # error says it was a deadline so it can be counted.
        read, gg.CONTROLLER_READ_TIMEOUT = gg.CONTROLLER_READ_TIMEOUT, 0.3
        self.addCleanup(setattr, gg, "CONTROLLER_READ_TIMEOUT", read)
        ctl = self.slow_controller(1.5, once=False)
        began = time.monotonic()
        with self.assertRaises(gg.ControllerTimeout):
            ctl.events(None)
        self.assertLess(time.monotonic() - began, 1.4)

    def test_a_missed_controller_deadline_is_counted_as_rest_spend(self) -> None:
        # The second half of the fix: a fallback used to be silent, so a controller that degraded looked like
        # nothing at all while it spent the one quota the whole fleet shares. It is counted where it happens.
        self.ctl.runs[21] = ctl_run(21, "in_progress")
        self.gh.runs[21] = {"id": 21, "status": "in_progress", "conclusion": None, "run_attempt": 1,
                            "updated_at": "2026-09-25T10:00:00Z"}
        self.gh.jobs[21] = [job("build")]
        gg.register(gg.parse_key("run", "o/r/21"))
        self.ctl.down = gg.ControllerTimeout("controller: TimeoutError")
        said = io.StringIO()
        with contextlib.redirect_stderr(said):
            self.daemon.tick(NOW)
        # said at the time, with the mechanism and the price, not only in the aggregate a later reader may not look at
        self.assertIn("spends the shared REST quota", said.getvalue())
        hours = self.daemon.controller_fallback.get("hours") or {}
        counts = next(iter(hours.values()), {})
        self.assertEqual(counts.get("deadline"), 1)  # the missed deadline
        self.assertGreaterEqual(counts.get("restRuns") or 0, 1)  # and what it sent to the shared quota
        self.assertEqual(self.daemon.controller_fallback.get("since"), NOW)
        # an error that is not a deadline is a different failure, and adds nothing to these counts (which a new
        # daemon on this host picks up where they were left: the window they report outlives one process)
        other = gg.Daemon(transport=self.gh, token=lambda: TOKEN, controller=self.ctl)
        self.assertEqual(other.controller_fallback, self.daemon.controller_fallback)
        before = json.dumps(other.controller_fallback, sort_keys=True)
        self.ctl.down = gg.WatchError("controller: URLError")
        said = io.StringIO()
        with contextlib.redirect_stderr(said):
            other.tick(NOW)
        self.assertEqual(json.dumps(other.controller_fallback, sort_keys=True), before)
        self.assertNotIn("spends the shared REST quota", said.getvalue())  # a claim only a deadline earns

    def test_tracked_run_costs_no_quota(self) -> None:
        self.ctl.runs[21] = ctl_run(21, "in_progress")
        key = gg.parse_key("run", "o/r/21")
        gg.register(key)
        for i in range(5):
            self.daemon.tick(NOW + i * gg.CYCLE)
        self.assertEqual(self.gh.rest_calls(), [])
        self.ctl.runs[21] = ctl_run(21, "completed", "failure", "2026-09-25T10:05:00Z")
        self.gh.runs[21] = {"id": 21, "status": "completed", "conclusion": "failure", "run_attempt": 1,
                            "updated_at": "2026-09-25T10:05:00Z"}
        self.gh.jobs[21] = [job("build", end=NOW)]
        self.daemon.tick(NOW + 5 * gg.CYCLE + gg.TICK)
        entry = gg.read_cache(key)
        self.assertEqual((entry["source"], entry["data"]["conclusion"]), ("controller", "failure"))
        self.assertEqual(gg.verdict("run", entry["data"], jobs=entry["jobs"]), gg.EXIT_FAIL)
        # the failed attempt's job list is read once, for its failed steps; nothing after that
        self.assertEqual((len(self.gh.run_calls()), len(self.gh.job_calls())), (1, 1))
        self.assertEqual(entry["jobs"][0]["failedSteps"], ["Run selected tests"])
        for i in range(1, 4):
            self.daemon.tick(NOW + 5 * gg.CYCLE + gg.TICK + i * gg.CYCLE)
        self.assertEqual(len(self.gh.rest_calls()), 2)

    def test_controller_run_supports_one_shot_long_poll(self) -> None:
        controller = gg.Controller("http://controller:18765", None)
        payload = {"known": True, "run": ctl_run(41, "completed", "success")}
        with mock.patch.object(controller, "get", return_value=payload) as get:
            self.assertEqual(controller.run(41, wait=7)["id"], 41)
        # the long poll waits out the wait it asked for, and then a read deadline on top of it
        get.assert_called_once_with("/v1/github/runs/41?wait=7", timeout=7 + gg.CONTROLLER_READ_TIMEOUT)

    def test_controller_run_rejects_unbounded_wait(self) -> None:
        controller = gg.Controller("http://controller:18765", None)
        with self.assertRaisesRegex(gg.WatchError, r"0\.\.300"):
            controller.run(41, wait=301)

    def test_cache_store_fails_closed_when_write_lock_times_out(self) -> None:
        @contextlib.contextmanager
        def unavailable_lock(*_args, **_kwargs):
            yield False

        key = "run:o/r/42"
        with mock.patch.object(gg, "bounded_lock", unavailable_lock):
            self.daemon.store(key, None, data={"id": 42, "status": "in_progress"})
        self.assertIsNone(gg.read_cache(key))

    def test_refusal_reported_by_the_controller_is_held_until_the_rescue_attempt(self) -> None:
        now = time.time()
        self.ctl.runs[31] = ctl_run(31, "completed", "failure", iso(now))
        self.gh.runs[31] = {"id": 31, "status": "completed", "conclusion": "failure", "run_attempt": 1,
                            "updated_at": iso(now)}
        self.gh.jobs[31] = [refused(end=now)]
        key = "run:o/r/31"
        gg.register(key)
        self.age_watch(key, 1)  # the reader came before the first fetch; a later one would get a REST confirmation
        self.daemon.tick(NOW)
        entry = gg.read_cache(key)
        self.assertIsNone(gg.verdict("run", entry["data"], jobs=entry["jobs"]))  # held for the rescue
        self.ctl.runs[31] = {**ctl_run(31, "in_progress", "", iso(now + 50)), "attempt": 2}
        self.daemon.tick(NOW + gg.TICK)
        entry = gg.read_cache(key)
        self.assertEqual((entry["data"]["run_attempt"], entry["data"]["status"]), (2, "in_progress"))
        self.ctl.runs[31] = {**ctl_run(31, "completed", "success", iso(now + 600)), "attempt": 2}
        self.daemon.tick(NOW + 2 * gg.TICK)
        entry = gg.read_cache(key)
        self.assertEqual(gg.verdict("run", entry["data"], jobs=entry.get("jobs")), gg.EXIT_OK)
        # attempt 1's run and job list; attempt 2's finish is confirmed a cycle after the last read
        self.assertEqual(len(self.gh.rest_calls()), 2)

    def test_a_finish_only_the_controller_reported_is_confirmed_before_a_wait_rules(self) -> None:
        """manaflow-ai/cmux run 40434431701, 2026-10-27: the controller kept attempt 1's "cancelled" (its rerun's
        deliveries were lost) while GitHub had attempt 2 queued, and `wait run` returned cancelled. A finish only
        the controller has reported is not ruled on until REST reads the run, which shows the rerun."""
        now = time.time()
        key = "run:o/r/46"
        self.ctl.runs[46] = ctl_run(46, "in_progress", "", iso(now - 120))
        self.gh.runs[46] = {"id": 46, "status": "in_progress", "conclusion": None, "run_attempt": 1,
                            "updated_at": iso(now - 120)}
        gg.register(key)
        self.daemon.tick(NOW)
        req = gg.wait_request("run", "o/r/46", "done", 60, False, False, None, True, gg.RESCUE_GRACE)
        req["began"] = time.time() - 1  # the reads below come after the wait began
        self.ctl.runs[46] = ctl_run(46, "completed", "cancelled", iso(now - 60))
        self.gh.runs[46] = {"id": 46, "status": "queued", "conclusion": None, "run_attempt": 2,
                            "updated_at": iso(now - 30)}
        calls = len(self.gh.rest_calls())
        controller = mock.Mock()
        controller.run.return_value = self.ctl.runs[46]
        with mock.patch.object(gg.Controller, "from_env", return_value=controller):
            gg.controller_wait_run(key, 5)  # the client's own long-poll stores the controller's finish
        self.assertEqual(gg.read_cache(key)["data"]["conclusion"], "cancelled")
        self.assertIsNone(gg.wait_step(req, time.time()), "never ruled on the controller's word alone")
        self.daemon.tick(NOW + gg.TICK)  # the daemon confirms it over REST
        self.assertEqual(len(self.gh.rest_calls()), calls + 1)
        entry = gg.read_cache(key)
        self.assertEqual((entry["data"]["status"], entry["data"]["run_attempt"], entry["source"]), ("queued", 2, "rest"))
        self.assertIsNone(gg.wait_step(req, time.time()), "the rerun is still queued")
        self.daemon.tick(NOW + 2 * gg.TICK)
        self.assertEqual(len(self.gh.rest_calls()), calls + 1, "a newer REST read keeps the controller's stale finish out")
        self.assertEqual(gg.read_cache(key)["data"]["status"], "queued")
        # once GitHub shows the rerun finished, the wait rules on it
        self.gh.runs[46] = {"id": 46, "status": "completed", "conclusion": "success", "run_attempt": 2,
                            "updated_at": iso(now)}
        self.ctl.runs[46] = {**ctl_run(46, "completed", "success", iso(now)), "attempt": 2}
        self.daemon.tick(NOW + 3 * gg.TICK)
        self.assertIsNone(gg.wait_step(req, time.time()), "the controller's success is confirmed first")
        self.daemon.tick(NOW + gg.TICK + gg.CYCLE)  # confirmations are paced at one per cycle
        self.assertEqual(len(self.gh.rest_calls()), calls + 2)
        result = gg.wait_step(req, time.time())
        self.assertIsNotNone(result)
        self.assertEqual(result[0], gg.EXIT_OK)

    def test_a_controller_success_is_confirmed_over_rest_once(self) -> None:
        """A green finish takes no failed-attempt read, so only the confirmation reads REST, once, and finds the
        rerun the controller missed."""
        now = time.time()
        key = "run:o/r/47"
        self.ctl.runs[47] = ctl_run(47, "in_progress", "", iso(now - 120))
        gg.register(key)
        self.age_watch(key, 1)  # the reader came before the first fetch, so a reader is not the reason to read REST
        self.daemon.tick(NOW)
        self.ctl.runs[47] = ctl_run(47, "completed", "success", iso(now - 60))
        self.gh.runs[47] = {"id": 47, "status": "queued", "conclusion": None, "run_attempt": 2,
                            "updated_at": iso(now - 30)}
        self.daemon.tick(NOW + gg.TICK)
        self.daemon.tick(NOW + 2 * gg.TICK)
        self.assertEqual(len(self.gh.rest_calls()), 1)
        self.assertEqual(gg.read_cache(key)["data"]["run_attempt"], 2)
        self.daemon.tick(NOW + 3 * gg.TICK)
        self.assertEqual(len(self.gh.rest_calls()), 1, "confirmed once, not every tick")

    def test_a_failed_confirmation_is_retried_once_a_cycle(self) -> None:
        now = time.time()
        key = "run:o/r/48"
        self.ctl.runs[48] = ctl_run(48, "completed", "success", iso(now - 60))
        gg.register(key)
        self.age_watch(key, 1)
        # no self.gh.runs[48]: every GitHub read of it fails (404 here; a 500 or a transport error is the same)
        for t in range(10):
            self.daemon.tick(NOW + t * gg.TICK)
        self.assertEqual(len(self.gh.rest_calls()), 1, "one failed read, not one a tick")
        self.daemon.tick(NOW + gg.CYCLE + 1)
        self.assertEqual(len(self.gh.rest_calls()), 2)

    def test_an_outage_is_read_once_a_cycle_even_with_a_waiting_reader_past_the_safety_age(self) -> None:
        now = time.time()
        key = "run:o/r/49"
        self.ctl.runs[49] = ctl_run(49, "completed", "success", iso(now - 60))
        gg.register(key)
        self.daemon.tick(NOW)
        reads = len(self.gh.rest_calls())  # its confirmation: the run is unknown to GitHub here, so it fails
        start = NOW + gg.REST_SAFETY + 1  # past the safety-net age, with a reader touching it every tick
        for t in range(10):
            self.age_watch(key, -(gg.REST_SAFETY + 1 + t * gg.TICK))
            self.daemon.tick(start + t * gg.TICK)
        self.assertEqual(len(self.gh.rest_calls()), reads + 1, "one failed read a cycle, not one a tick")

    def test_a_confirmation_ignores_an_etag_from_before_the_controller_record(self) -> None:
        """A cache from before restRun, or one whose ETag is from a read the controller's record replaced: a 304 would
        prove nothing about the finish, so the confirmation asks without the ETag and records what GitHub shows."""
        now = time.time()
        key = "run:o/r/50"
        self.gh.runs[50] = {"id": 50, "status": "completed", "conclusion": "success", "run_attempt": 1,
                            "updated_at": iso(now - 60)}
        self.ctl.runs[50] = ctl_run(50, "completed", "success", iso(now - 60))
        gg.register(key)
        self.daemon.tick(NOW)
        entry = gg.read_cache(key)
        self.assertTrue(entry.get("etag"))
        # an older version's cache: an ETag, no restRun
        entry.pop("restRun", None)
        gg.write_json(gg.cache_dir() / gg.file_name(key), entry)
        self.assertTrue(gg.controller_unconfirmed(gg.read_cache(key), time.time()))
        self.daemon.tick(NOW + gg.CYCLE + 1)
        self.assertNotIn("If-None-Match", self.gh.rest_calls()[-1][2])
        self.assertFalse(gg.controller_unconfirmed(gg.read_cache(key), time.time()))

    def test_safety_net_reads_rest_every_15_minutes(self) -> None:
        self.ctl.runs[22] = ctl_run(22, "in_progress")
        self.gh.runs[22] = {"id": 22, "status": "in_progress", "updated_at": "2026-09-25T10:00:00Z"}
        gg.register("run:o/r/22")
        self.daemon.tick(NOW)
        self.daemon.tick(NOW + gg.REST_SAFETY - gg.CYCLE)
        self.assertEqual(len(self.gh.rest_calls()), 0)
        # the waiting reader keeps touching its watch; without that it expires at IDLE_EXPIRY,
        # which equals REST_SAFETY (the test passed only while NOW trailed the registration)
        self.age_watch(gg.parse_key("run", "o/r/22"), -(gg.REST_SAFETY - gg.CYCLE))
        self.daemon.tick(NOW + gg.REST_SAFETY + 1)
        self.assertEqual(len(self.gh.rest_calls()), 1)

