    def test_a_running_head_on_a_covered_repository_waits_for_its_check_events(self) -> None:
        sha = "a" * 40
        self.gh.heads[("o", "r", sha)] = [check_run("CI / build", "IN_PROGRESS", None)]
        key = gg.parse_key("head", f"o/r@{sha}")
