        self.assertEqual(len(self.gh.gql_calls()), 2)
        self.assertEqual(gg.verdict("pr", data, "done"), gg.EXIT_FAIL)
        self.assertEqual([c["name"] for c in gg.classify(data, NOW, gg.RESCUE_GRACE)["failed"]], ["deploy/preview"])

