    def test_a_stale_graphql_counter_rate_limit_cannot_see_does_not_force_a_read_every_tick(self) -> None:
        """Review of #1834 (F3): a poorer GraphQL counter seen long ago, which /rate_limit does not report, made every
        tick ask /rate_limit. Like REST's counters, a recent /rate_limit answer makes it fresh enough."""
        self.addCleanup(setattr, gg, "BUDGET_REFRESH", gg.BUDGET_REFRESH)
        gg.BUDGET_REFRESH = 120.0
        self.daemon.now = NOW
        self.daemon.budget = {"rest": {"limit": 5000, "remaining": 4000, "reset": NOW + 900, "seenAt": NOW - 1}}
        self.daemon.note_budget("graphql", 5000, 1200, NOW + 1500)
        self.daemon.now = NOW + 2 * gg.BUDGET_REFRESH
        self.daemon.budget["rest"]["seenAt"] = self.daemon.now - 1
        self.daemon.note_budget("graphql", 5000, 4000, NOW + 3000)  # the counter /rate_limit sees, fresh
        self.daemon.rate_limit_at = self.daemon.now - 1
        before = len([c for c in self.gh.calls if c[1].endswith("/rate_limit")])
        self.daemon.refresh_budget()
        self.assertEqual(len([c for c in self.gh.calls if c[1].endswith("/rate_limit")]), before)

    def test_the_ceiling_takes_every_kind_in_turn(self) -> None:
        """Review of #1834 at e482a2a: with every kind due each tick and a full ceiling, the order skipped a held kind
        that had read nothing (pchch...: runs never read). Every kind reads within a few minutes."""
        reads: list[str] = []

        def fetcher(kind: str):
            def fetch(chunk: list[dict]) -> None:
                reads.append(kind)
                self.daemon.gql_log.append((self.daemon.now, kind, 1))
            return fetch

        fetchers = {k: fetcher(k) for k in ("pr", "comment", "run", "head")}
        keys = {"pr": [f"pr:o/r#{n}" for n in range(30)], "comment": ["comment:o/r#1"], "run": ["run:o/r/1"],
                "head": ["head:o/r@" + "a" * 40]}
        due = lambda kind, entries: [{"key": k, "cache": None} for k in keys[kind]]  # noqa: E731
        self.budgets(rest=(300, 3000), graphql=(4000, 3000))
        self.daemon.paths.update({k: "graphql" for k in keys})
        self.daemon.batch["pr"] = 10
        policy = {**self.daemon.policy, "graphqlPerMinute": 1, "restShare": 0.0}
        with mock.patch.object(gg, "daemon_policy", return_value=policy), \
                mock.patch.object(gg.Daemon, "graphql_fetch", property(lambda d: fetchers)), \
                mock.patch.object(self.daemon, "due", side_effect=due), \
                mock.patch.object(self.daemon, "serve_waits", return_value=0):
            for t in range(0, 8 * 60, 2):
                self.daemon.tick(NOW + t)
        self.assertEqual(set(reads), {"pr", "comment", "run", "head"}, "".join(k[0] for k in reads))
        self.assertTrue(all(reads.count(k) >= 1 for k in ("comment", "run", "head")), reads)

    def blocked_fleet(self, pr_path: str, seconds: float, heavy: int = 0, every: int = 40,
                      pace: int = 40) -> tuple[dict[str, list[float]], list[dict]]:
        """800 watched PRs, each read lately (so due every cycle), 20 of them blocked on by a wait or a due land (their
        waitedAt renewed every tick, as a wait's touches do), and 100 comment watches due as well; GraphQL paced at 40
        points a minute (a point a PR, as a heavy rollup costs); PRs over PR_PATH, with REST's share leaving room for
        3 reads a minute and the rest spilling to GraphQL; HEAVY unblocked PRs read alone (batched's heavy entries).
        EVERY: one PR in that many is blocked; PACE: graphqlPerMinute.
        Ticks every TICK for SECONDS; the times each PR was read."""
        d = self.daemon
        reads: dict[str, list[float]] = {}
        rest_log: list[float] = []
        cache = lambda key, at: {"key": key, "fetchedAt": at, "dataAt": at, "source": "graphql",  # noqa: E731
                                 "data": {"state": "OPEN", "number": 1} if key.startswith("pr:") else []}
        entries = [{"key": key, "cache": cache(key, NOW - 30), "touched": NOW, "waitedAt": None, "waitBegan": None,
                    "readers": [], "reader": "", "consumers": {}, "since": None, "jobs": False}
                   for key in [f"pr:o/r#{n}" for n in range(800)] + [f"comment:o/r#{n}" for n in range(100)]]
        blocked = [e for e in entries if e["key"].startswith("pr:")][7::every]

        def watches() -> list[dict]:
            for e in entries:
                e["touched"] = d.now
            for e in blocked:
                e["waitedAt"] = d.now
                e["waitBegan"] = NOW - 60
            for e in entries[:heavy]:
                d.heavy[e["key"]] = {"at": d.now, "fails": 1, "oks": 0}
            return entries

        def read(e: dict) -> None:
            e["cache"] = cache(e["key"], d.now)
            reads.setdefault(e["key"], []).append(d.now)

        def gql(kind: str):
            def fetch(chunk: list[dict]) -> None:
                if not d.gql_room():
                    raise AssertionError("a query past the pace")
                for e in chunk:
                    read(e)
                d.gql_log.append((d.now, kind, len(chunk)))
            return fetch

        def rest(e: dict) -> None:
            read(e)
            rest_log.append(d.now)

        def route(kind: str) -> str:
            d.paths[kind] = pr_path if kind == "pr" else "graphql"
            return d.paths[kind]

        self.budgets(rest=(4000, 3000), graphql=(4000, 3000))
        d.batch["pr"] = 10
        policy = {**d.policy, "graphqlPerMinute": pace}
        fetchers = {k: gql(k) for k in ("pr", "comment", "run", "head")}
        with mock.patch.object(gg, "daemon_policy", return_value=policy), \
                mock.patch.object(gg.Daemon, "graphql_fetch", property(lambda _: fetchers)), \
                mock.patch.object(gg.Daemon, "rest_fetch", property(lambda _: {"pr": rest})), \
                mock.patch.object(d, "watches", side_effect=watches), \
                mock.patch.object(d, "route", side_effect=route), \
                mock.patch.object(d, "rest_room", side_effect=lambda cost: sum(1 for t in rest_log if d.now - t < 60) < 3), \
                mock.patch.object(d, "serve_waits", return_value=0), \
                mock.patch.object(d, "check_alarms"):
            for t in range(0, int(seconds), gg.TICK):
                d.tick(NOW + t)
        return reads, blocked

    def assert_read_within_the_stale_bound(self, reads: dict[str, list[float]], blocked: list[dict], end: float) -> None:
        for e in blocked:
            times = [NOW - 30] + reads.get(e["key"], []) + [end]
            gap = max(b - a for a, b in zip(times, times[1:]))
            self.assertLessEqual(gap, gg.STALE_DATA_AFTER, f"{e['key']}: data {gap:.0f}s old at worst; read at "
                                 f"{[int(t - NOW) for t in reads.get(e['key'], [])]}")

    def test_twenty_blocked_of_800_paced_prs_over_graphql_are_read_within_one_stale_bound(self) -> None:
        # huge-blue 2026-11-18 21:5xZ: pr data waits were blocked on 3403 s old (heartbeat fresh) with GraphQL paced at
        # 40 points a minute. The pace can read the 20 blocked PRs every minute; they go ahead of the 780 others (60 of
        # them heavy, each read alone) and the comment watches in every window, so none waits past STALE_DATA_AFTER.
        reads, blocked = self.blocked_fleet("graphql", 2 * gg.STALE_DATA_AFTER, heavy=60)
        self.assert_read_within_the_stale_bound(reads, blocked, NOW + 2 * gg.STALE_DATA_AFTER)
        self.assertGreater(sum(len(v) for k, v in reads.items() if k.startswith("pr:")), 20 * 10,
                           "the unblocked PRs get what is left of the pace")

    def test_twenty_blocked_of_800_prs_over_a_spent_rest_share_are_read_within_one_stale_bound(self) -> None:
        # The same over REST, its share leaving room for 3 reads a minute: the rest spill to GraphQL at its pace, and
        # a blocked PR deferred lately goes ahead of plain watches deferred long before it.
        reads, blocked = self.blocked_fleet("rest", 2 * gg.STALE_DATA_AFTER)
        self.assert_read_within_the_stale_bound(reads, blocked, NOW + 2 * gg.STALE_DATA_AFTER)

    def assert_plain_read_every_floor(self, reads: dict[str, list[float]], blocked: list[dict], seconds: float) -> None:
        plain = sorted(t for k, v in reads.items() if k.startswith("pr:") and k not in {e["key"] for e in blocked}
                       for t in v)
        times = [NOW] + plain + [NOW + seconds]
        gap = max(b - a for a, b in zip(times, times[1:]))
        self.assertLessEqual(gap, gg.PLAIN_FLOOR_EVERY + gg.CYCLE, f"no plain PR read for {gap:.0f}s")

    def test_a_blocked_set_past_the_pace_still_leaves_plain_watches_a_floor(self) -> None:
        # Review of glaeda#2199: blocked first with no floor let 400 blocked PRs at 40 points a minute take every
        # point, and the 400 plain watches were never read. One unblocked batch a minute (PLAIN_FLOOR_EVERY) still is.
        reads, blocked = self.blocked_fleet("graphql", gg.STALE_DATA_AFTER, every=2)
        self.assert_plain_read_every_floor(reads, blocked, gg.STALE_DATA_AFTER)

    def test_a_blocked_set_past_the_rest_share_still_leaves_plain_watches_a_floor(self) -> None:
        reads, blocked = self.blocked_fleet("rest", gg.STALE_DATA_AFTER, every=2)
        self.assert_plain_read_every_floor(reads, blocked, gg.STALE_DATA_AFTER)

