    def test_two_graphql_counters_read_as_the_poorer_one(self) -> None:
        """2026-11-04 06:02Z: one daemon's GraphQL reading jumped to the other counter (3938 left, :21 reset) while
        the counter /graphql spends had 1664 (:26 reset). The poorer live counter is the reading, both are kept,
        and one past its reset leaves the other."""
        self.daemon.now = NOW
        self.daemon.budget = {}
        self.daemon.note_budget("graphql", 5000, 1664, NOW + 1440)
        self.daemon.note_budget("graphql", 5000, 3938, NOW + 1140)
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 1664)
        self.assertEqual(len(self.daemon.budget["graphqlCounters"]), 2)
        self.daemon.note_budget("graphql", 5000, 900, NOW + 1440)  # the spending counter goes on down
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 900)
        self.daemon.note_budget("graphql", 5000, 400, NOW + 1140)  # now the other counter is the poorer
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 400)
        self.daemon.now = NOW + 1141  # its window ended; the one still live is the reading
        self.daemon.settle_counters("graphql")
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 900)
        self.assertEqual(len(self.daemon.budget["graphqlCounters"]), 1)

    def test_graphql_reading_is_the_counter_its_own_queries_draw_from(self) -> None:
        """2026-11-25 22:40Z: a daemon held its GraphQL reads (and NOW paged ci-quota) on a counter with 0 left
        resetting at 22:41:25Z while the counter the login's queries spent had 4459 left until 23:11:10Z. The reading
        is the counter the daemon's own queries name (cost given), and each counter keeps the points drawn from it."""
        self.daemon.now = NOW
        self.daemon.budget = {}
        self.daemon.note_budget("graphql", 5000, 0, NOW + 85)  # /rate_limit's counter: no query of ours drew on it
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 0)  # no draw yet: the poorest
        self.daemon.note_budget("graphql", 5000, 4459, NOW + 1870, cost=3)
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 4459)
        self.assertTrue(self.daemon.budget["graphql"]["drawn"])
        self.assertEqual(self.daemon.mode("graphql"), "normal")
        self.daemon.note_budget("graphql", 5000, 0, NOW + 85)  # /rate_limit again: still not the hold
        self.daemon.note_budget("graphql", 5000, 4457, NOW + 1870, cost=2)
        self.daemon.settle_counters("graphql")
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 4457)
        self.assertEqual(self.daemon.mode("graphql"), "normal")
        counters = {c["reset"]: c for c in self.daemon.budget["graphqlCounters"]}
        self.assertEqual(counters[NOW + 1870]["spent"], 5)  # the settle's own re-merge counts no point twice
        self.assertTrue(counters[NOW + 1870]["drawn"])
        self.assertNotIn("drawn", counters[NOW + 85])
        self.assertNotIn("spent", counters[NOW + 85])
        view = self.daemon.graphql_counters_view()
        self.assertEqual(sorted((c["remaining"], c["drawn"]) for c in view), [(0, False), (4457, True)])

    def test_a_drawn_counter_that_runs_low_holds_the_reads(self) -> None:
        """The other side: when the counter the queries draw from is the poor one, it is the hold, however rich the
        other counter /rate_limit reports."""
        self.daemon.now = NOW
        self.daemon.budget = {}
        self.daemon.note_budget("graphql", 5000, 40, NOW + 600, cost=1)
        self.daemon.note_budget("graphql", 5000, 4751, NOW + 2040)
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 40)
        self.assertEqual(self.daemon.mode("graphql"), "stop")

    def test_a_drawn_counter_past_its_reset_is_dropped_not_held(self) -> None:
        """The counter the queries draw from reset: that is a fresh window, so neither its last "0 left" nor the
        other, poorer counter the daemon does not draw from holds the reads; the next query names the new one."""
        self.daemon.now = NOW
        self.daemon.budget = {}
        self.daemon.note_budget("graphql", 5000, 0, NOW + 60, cost=1)
        self.daemon.note_budget("graphql", 5000, 10, NOW + 3000)
        self.assertEqual(self.daemon.mode("graphql"), "stop")
        self.daemon.now = NOW + 61
        self.daemon.settle_counters("graphql")
        self.assertEqual([c["reset"] for c in self.daemon.budget["graphqlCounters"]], [NOW + 3000])
        self.assertEqual(self.daemon.mode("graphql"), "normal")
        self.daemon.note_budget("graphql", 5000, 4990, NOW + 3661, cost=1)  # the new window's first answer
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 4990)
        self.assertEqual(len(self.daemon.budget["graphqlCounters"]), 2)

    def test_a_graphql_answer_names_its_counter_with_its_cost(self) -> None:
        """Daemon.graphql passes the answer's rateLimit cost, so the counter it drew from is the reading."""
        self.daemon.now = NOW
        self.daemon.budget = {"graphqlCounters": [{"limit": 5000, "remaining": 0, "reset": NOW + 85, "seenAt": NOW}]}
        reset = dt.datetime.fromtimestamp(NOW + 1870, dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        doc = {"data": {"rateLimit": {"limit": 5000, "remaining": 4459, "resetAt": reset, "cost": 4}}}
        with mock.patch.object(self.daemon, "request", return_value=(200, {}, doc)):
            got, error = self.daemon.graphql("query { rateLimit { limit remaining resetAt cost } }", {})
        self.assertIsNone(error)
        self.assertEqual(self.daemon.budget["graphql"]["remaining"], 4459)
        drawn = next(c for c in self.daemon.budget["graphqlCounters"] if c.get("drawn"))
        self.assertEqual(drawn["spent"], 4)

    def test_graphql_reads_past_the_per_minute_ceiling_wait_for_the_next_minute(self) -> None:
        """A tick that would spend past graphqlPerMinute sends nothing more: its reads are deferred (first next tick),
        not spilled to REST, and once the minute has passed they are read."""
        self.gh.prs[("o", "r", 21)] = pr_node(21, checks=[workflow_check("build", 5)])
        self.budgets(rest=(300, 3000), graphql=(4000, 3000))
        self.daemon.gql_log = [(NOW - 30, "pr", gg.GRAPHQL_PER_MINUTE)]  # this minute's points already spent
        gg.register("pr:o/r#21")
        self.daemon.tick(NOW)
        self.assertEqual(self.gh.gql_calls(), [])
        self.assertEqual([c for c in self.gh.rest_calls() if "/pulls/" in c[1]], [])  # paced, not spilled to REST
        self.assertIn("pr:o/r#21", self.daemon.deferred)
        self.daemon.tick(NOW + 31)  # the spent points are a minute old
        self.assertEqual(len(self.gh.gql_calls()), 1)
        self.assertEqual(gg.read_cache("pr:o/r#21")["data"]["number"], 21)

    def test_the_pace_counts_points_by_the_wall_clock_not_the_ticks_start(self) -> None:
        """huge-blue, 2026-11-20: ticks of ~90 s, and every GraphQL point was logged at the tick's start (self.now),
        which stands still for the whole tick. A tick's first 40 points kept "this minute" full until the tick ended
        ("41 of 40 points this minute", every later batch deferred) though the real minute had room, and the next
        tick, 90 s on, found the window empty and spent 40 at once. Points are logged and counted by one clock."""
        d = self.daemon
        d.policy = {**d.policy, "graphqlPerMinute": 40}
        wall = [NOW]
        d.now, d.clock_real = NOW, True  # tick() at NOW, its clock pinned there; the wall clock moves on
        with mock.patch.object(gg.time, "time", side_effect=lambda: wall[0]):
            d.gql_reason = "pr"
            d.gql_log.append((d.clock(), "pr", 40))  # a tick's first query, at its start
            self.assertFalse(d.gql_room())
            wall[0] = NOW + 61  # the same tick, a minute later: its own points have left the window
            self.assertTrue(d.gql_room(), "the tick's own start held the window shut")
            # the outbox's query, logged mid-tick by the wall clock, counts in the same window as the reads'
            d.gql_log.append((d.clock(), "outbox", 30))
            self.assertEqual(d.gql_minute_points(), 30)

    def test_the_pace_admits_a_query_only_when_its_cost_fits(self) -> None:
        """A gate that only asked "under 40?" let a 39th point admit a query of several ("41 of 40 points this minute").
        A query is admitted when its expected cost (the most of its kind's last queries) fits; one costing more than
        the whole pace still goes out alone, in a minute with nothing else spent."""
        d = self.daemon
        d.policy = {**d.policy, "graphqlPerMinute": 40}
        d.gql_log = [(NOW - 50, "pr", 3)] * 12 + [(NOW - 5, "comment", 1)] * 2  # 38 points this minute
        d.now = NOW
        self.assertEqual(d.gql_expected("pr"), 3)
        self.assertEqual(d.gql_expected("run"), 1)  # none of its kind yet
        self.assertFalse(d.gql_room(d.gql_expected("pr")), "38 + 3 is past 40")
        self.assertTrue(d.gql_room(d.gql_expected("comment")))
        d.gql_log = []
        self.assertTrue(d.gql_room(55), "a query costing past the pace is read alone, not never")
        # batched() asks the cost: a 3-point PR batch at 38 waits for the next minute instead of making 41
        self.gh.prs[("o", "r", 22)] = pr_node(22, checks=[workflow_check("build", 5)])
        self.budgets(rest=(300, 3000), graphql=(4000, 3000))
        d.gql_log = [(NOW - 50, "pr", 3)] * 12 + [(NOW - 5, "comment", 1)] * 2
        gg.register("pr:o/r#22")
        d.tick(NOW)
        self.assertEqual(self.gh.gql_calls(), [])
        self.assertIn("pr:o/r#22", d.deferred)
        self.assertLessEqual(d.gql_minute_points(), 40)

    def test_a_refresh_of_every_pr_after_a_reset_is_spread_over_minutes(self) -> None:
        """Every watched PR due at once (a reset, a re-exec, a stop below the reserve): at most graphqlPerMinute
        points a minute go out, the rest first in line next tick, so the shared login sees no burst."""
        for n in range(30, 60):
            self.gh.prs[("o", "r", n)] = pr_node(n, checks=[workflow_check("build", 5)])
            gg.register(f"pr:o/r#{n}")
        self.budgets(rest=(300, 3000), graphql=(4000, 3000))
        self.daemon.policy = {**self.daemon.policy, "graphqlPerMinute": 1}
        self.daemon.batch["pr"] = 10
        with mock.patch.object(gg, "daemon_policy", return_value=self.daemon.policy):
            self.daemon.tick(NOW)
            self.assertEqual(len(self.gh.gql_calls()), 1)  # one query (10 PRs); 20 wait
            self.assertEqual(len(self.daemon.deferred), 20)
            self.daemon.tick(NOW + 61)
            self.assertEqual(len(self.gh.gql_calls()), 2)
            self.daemon.tick(NOW + 122)
            self.assertEqual(len(self.gh.gql_calls()), 3)
        unread = [n for n in range(30, 60) if (gg.read_cache(f"pr:o/r#{n}") or {}).get("data") is None]
        self.assertEqual(unread, [], [len(q[1].get("query", "")) if isinstance(q[1], dict) else q for q in self.gh.gql_calls()])

    def test_steps_come_from_rest_so_a_refused_check_is_still_held(self) -> None:
        """PRs move to REST when GraphQL is stopped; the failed steps must not need GraphQL."""
        now = time.time()
        build = {**workflow_check("build", 5, conclusion="FAILURE", node_id="CR_build"),
                 "startedAt": iso(now - 7), "completedAt": iso(now)}
        self.gh.prs[("o", "r", 4)] = pr_node(4, rollup="FAILURE", checks=[build])
        self.gh.job_steps[50] = [{"name": "Set up job", "conclusion": "success"},
                                 {"name": "Set up runner", "conclusion": "failure"}]
        self.budgets(rest=(4000, 1800), graphql=(50, 3000))  # GraphQL below its reserve
        gg.register("pr:o/r#4")
        self.daemon.tick(NOW)
        self.assertEqual(self.gh.gql_calls(), [])
        data = gg.read_cache("pr:o/r#4")["data"]
        self.assertEqual(data["checks"][0]["failedSteps"], ["Set up runner"])
        self.assertIsNone(gg.verdict("pr", data, "green"))  # held for the rescue, not red
        jobs = [c for c in self.gh.rest_calls() if "/actions/jobs/" in c[1]]
        self.assertEqual(len(jobs), 1)
        self.daemon.tick(NOW + gg.CYCLE)  # a completed job's steps are read once
        self.assertEqual(len([c for c in self.gh.rest_calls() if "/actions/jobs/" in c[1]]), 1)
        self.assertEqual(gg.read_cache("pr:o/r#4")["data"]["checks"][0]["failedSteps"], ["Set up runner"])

