    def dispatched_run(self, title: str | None, conclusion: str | None = "success", event: str = "workflow_dispatch") -> dict:
        """A fast-checks dispatch: its head is main's tip (cccc...), whatever commit it tested."""
        return {"id": 9, "name": "Fast checks", "display_title": title, "status": "completed" if conclusion else "in_progress",
                "conclusion": conclusion, "html_url": "https://github.com/o/r/actions/runs/9", "head_sha": "c" * 40,
                "head_branch": "main", "event": event, "run_attempt": 1, "created_at": None, "updated_at": None}

    def test_a_dispatch_naming_the_full_commit_in_its_run_name_is_that_commits(self) -> None:
        tested = "b" * 40
        green = self.dispatched_run(f"Fast checks {'a' * 40} tests o/r@{tested}")
        self.assertEqual(self.wait("run", "o/r/9", fill=(green, {}), sha=tested)[0], 0)
        red = self.dispatched_run(f"Fast checks {'a' * 40} tests o/r@{tested}", "failure")
        self.assertEqual(self.wait("run", "o/r/9", fill=(red, {}), sha=tested)[0], 1)
        running = self.dispatched_run(f"Fast checks {'a' * 40} tests o/r@{tested}", None)
        code, text = self.wait("run", "o/r/9", fill=(running, {}), sha=tested, timeout=0.4)
        self.assertEqual(code, 2)
        self.assertNotIn("GitHub still shows head", text)  # it is the right run, still running
        # its own head still counts, as for any run
        self.assertEqual(self.wait("run", "o/r/9", fill=(green, {}), sha="c" * 40)[0], 0)

    def test_a_run_name_never_matches_another_commit_a_prefix_or_another_repo(self) -> None:
        tested = "b" * 40
        title = f"Fast checks {'a' * 40} tests o/r@{tested}"
        refused = [
            (self.dispatched_run(title), "d" * 40),  # another commit
            (self.dispatched_run(title), "bbbbbbbbbb"),  # a prefix of the named commit (resolves nowhere here)
            (self.dispatched_run(title), "a" * 40),  # the snapshot named bare: not the tested commit
            (self.dispatched_run(f"Fast checks {'a' * 40} tests o/other@{tested}"), tested),  # another repo's
            (self.dispatched_run(f"Fast checks {'a' * 40} tests o/r@{tested}0"), tested),  # longer than an id
            (self.dispatched_run(title, event="push"), tested),  # only a dispatch names what it tested
            (self.dispatched_run(f"Fast checks {tested}"), tested),  # no repo: the old run-name
        ]
        for run, sha in refused:
            with self.subTest(title=run["display_title"], sha=sha, event=run["event"]):
                with self.assertRaisesRegex(gg.WatchError, "is for commit cccccccccc"):
                    self.wait("run", "o/r/9", fill=(run, {}), sha=sha)
                self.assertIsNone(gg.verdict("run", run, sha=sha, repo="o/r"))

    def test_a_dispatch_without_its_run_name_waits_for_one(self) -> None:
        # the controller's record has no run-name: neither accepted nor refused until GitHub's own read
        code, _ = self.wait("run", "o/r/9", fill=(self.dispatched_run(None), {}), sha="b" * 40, timeout=0.4)
        self.assertEqual(code, 2)

    def test_names_commit_is_exact(self) -> None:
        sha = "0123456789abcdef0123456789abcdef01234567"
        self.assertTrue(gg.names_commit(f"Fast checks {'a' * 40} tests manaflow-ai/cmux@{sha}", "manaflow-ai/cmux", sha))
        self.assertTrue(gg.names_commit(f"x Manaflow-AI/cmux@{sha.upper()}", "manaflow-ai/cmux", sha))
        self.assertFalse(gg.names_commit(f"x manaflow-ai/cmux@{sha}", "manaflow-ai/cmux", sha[:12]))
        self.assertFalse(gg.names_commit(f"x manaflow-ai/cmux@{sha[:12]}", "manaflow-ai/cmux", sha))
        self.assertFalse(gg.names_commit(f"x evil/manaflow-ai/cmux@{sha}", "manaflow-ai/cmux", sha))
        self.assertFalse(gg.names_commit(None, "manaflow-ai/cmux", sha))

    def test_missing_pr_fails(self) -> None:
        code, text = self.wait("pr", "o/r#404", fill=(None, {"error": "Could not resolve", "missing": True}))
        self.assertEqual(code, 1)
        self.assertIn("Could not resolve", text)
        # the agent output contract: what is wrong, then `next:` last, on the stream the answer uses
        lines = text.strip().splitlines()
        self.assertEqual(lines[-1], "next: gh pr list -R o/r --state all --limit 5")
        self.assertIn("no such PR or issue on GitHub", lines[-2])

    def test_a_missing_pr_is_not_found_in_json(self) -> None:
        self.put("pr:o/r#404", None, error="Could not resolve", missing=True)
        req = gg.wait_request("pr", "o/r#404", "green", 60, False, True, None, True, 0)
        req["began"] -= 5
        code, out = gg.wait_step(req, time.time())
        doc = json.loads(out)
        self.assertEqual(code, gg.EXIT_FAIL)
        self.assertEqual((doc["ok"], doc["code"], doc["result"]), (False, "not-found", "failure"))
        self.assertEqual(doc["next"], "gh pr list -R o/r --state all --limit 5")
        run = gg.wait_request("run", "o/r/9", "green", 60, False, True, None, True, 0)
        self.assertEqual(gg.not_found_fields(run["key"])["next"], "gh run list -R o/r --limit 5")

    def test_a_timeout_names_its_deadline_and_the_wait_to_run_again(self) -> None:
        running = gg.parse_pr(pr_node(1, rollup="PENDING", checks=[check_run("a", "IN_PROGRESS", None)]))
        code, text = self.wait("pr", "o/r#1", fill=(running, {}), timeout=0.3)
        self.assertEqual(code, gg.EXIT_TIMEOUT)
        lines = text.strip().splitlines()
        # Never this same wait again (timeout_next, leo-workspace#8794): the pending check has no run to open, so
        # the step is the PR's own verbose status.
        self.assertEqual(lines[-1], "next: glaeda-gh status pr o/r#1 --verbose")
        self.assertRegex(lines[-2], r"^glaeda-gh: waited 0 s for o/r#1: no change for 0.3 s \(deadline "
                                    r"\d\d:\d\d:\d\dZ; no change since the wait began\); last seen: ")
        self.assertIn("checks PENDING", lines[-2])

    def test_a_wait_says_how_it_stands_while_it_blocks(self) -> None:
        running = gg.parse_pr(pr_node(1, rollup="PENDING", checks=[check_run("a", "IN_PROGRESS", None)]))
        with mock.patch.object(gg, "WAIT_PROGRESS_EVERY", 0.1):
            code, text = self.wait("pr", "o/r#1", fill=(running, {}), timeout=0.5)
        self.assertEqual(code, gg.EXIT_TIMEOUT)
        progress = [line for line in text.splitlines() if line.startswith("glaeda-gh: still waiting on pr:o/r#1: ")]
        self.assertTrue(progress, text)
        self.assertRegex(progress[0], r"no change for \d+s of 0.5s, deadline \d\d:\d\d:\d\dZ \(moves while it "
                                      r"progresses; ceiling \d\d:\d\d:\d\dZ\); o/r#1 OPEN .*; checks PENDING")

    def test_a_daemon_ruled_wait_keeps_the_state_its_blocker_prints(self) -> None:
        running = gg.parse_pr(pr_node(1, rollup="PENDING", checks=[check_run("a", "IN_PROGRESS", None)]))
        self.put("pr:o/r#1", running)
        req = gg.wait_request("pr", "o/r#1", "green", 60, False, False, None, True, 0)
        d = gg.waits_dir()
        d.mkdir(parents=True, exist_ok=True)
        gg.Daemon.note_wait_state(d, "1-x", req)
        state = (d / "1-x.out.state").read_text()
        self.assertTrue(state.startswith("o/r#1 OPEN") and state.count("\n") == 1, state)
        self.assertIn("checks PENDING", state)
        self.assertIn(".out.state", gg.WAIT_FILES)
        self.assertIn('$out.state', gg.BLOCKER)

    def test_status_reads_a_key_nobody_watches_directly_once_when_the_wait_ends_empty(self) -> None:
        """A key the daemon has not read when status's wait ends gets one direct read (as wait's starved branch),
        then status answers from the cache; a refused read (quota, upstream) leaves the old "no data yet" (3)."""
        reads: list[dict] = []

        def fill(req: dict) -> None:
            reads.append(req)
            self.put(req["key"], gg.parse_pr(pr_node(7, rollup="SUCCESS", checks=[check_run("a")])))
            return None
        out = io.StringIO()
        with mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "daemon_failing", return_value=None), \
                mock.patch.object(gg, "daemon_stale", return_value=None), \
                mock.patch.object(gg, "blocked_now", return_value=None), \
                mock.patch.object(gg, "say_waiting", lambda line: None), \
                mock.patch.object(gg, "direct_read", side_effect=fill), contextlib.redirect_stdout(out):
            self.assertEqual(gg.cmd_status("pr", "o/r#7", False, True, first_wait=0), 0)
        self.assertEqual([r["key"] for r in reads], ["pr:o/r#7"])
        self.assertEqual(json.loads(out.getvalue())["data"]["checkState"], "SUCCESS")
        # a key whose cache already answers is never read again, and a refusal is not an answer
        reads.clear()
        with mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "daemon_failing", return_value=None), \
                mock.patch.object(gg, "daemon_stale", return_value=None), \
                mock.patch.object(gg, "blocked_now", return_value=None), \
                mock.patch.object(gg, "say_waiting", lambda line: None), \
                mock.patch.object(gg, "direct_read", side_effect=lambda req: reads.append(req) or gg.DIRECT_QUOTA), \
                contextlib.redirect_stdout(io.StringIO()):
            self.assertEqual(gg.cmd_status("pr", "o/r#7", False, True, first_wait=0), 0)
            self.assertEqual(reads, [])
            self.assertEqual(gg.cmd_status("pr", "o/r#8", False, True, first_wait=0), gg.EXIT_DOWN)
        self.assertEqual([r["key"] for r in reads], ["pr:o/r#8"])

    def test_status_on_an_upstream_fed_host_reads_a_cold_key_directly_after_a_short_wait(self) -> None:
        """An upstream-fed host with a direct route waits STATUS_UPSTREAM_WAIT, not a cycle, before its direct read;
        a host without one keeps the cycle wait."""
        waits: list[float] = []
        clock = [0.0]

        def monotonic() -> float:
            return clock[0]

        def sleep(s: float) -> None:
            clock[0] += s

        def fill(req: dict) -> None:
            waits.append(clock[0])
            self.put(req["key"], gg.parse_pr(pr_node(9, rollup="SUCCESS", checks=[check_run("a")])))
            return None
        for upstream, expect in ((["lane-gh", "glaeda-read"], gg.STATUS_UPSTREAM_WAIT), (None, gg.CYCLE + 10.0)):
            waits.clear()
            clock[0] = 0.0
            with mock.patch.object(gg, "daemon_running", return_value=True), \
                    mock.patch.object(gg, "daemon_failing", return_value=None), \
                    mock.patch.object(gg, "daemon_stale", return_value=None), \
                    mock.patch.object(gg, "blocked_now", return_value=None), \
                    mock.patch.object(gg, "say_waiting", lambda line: None), \
                    mock.patch.object(gg, "upstream_command", return_value=upstream), \
                    mock.patch.object(gg, "direct_command", return_value=["lane-gh", "call", "get"] if upstream else None), \
                    mock.patch.object(gg, "daemon_policy", return_value={"cycle": gg.CYCLE}), \
                    mock.patch.object(gg.time, "monotonic", side_effect=monotonic), \
                    mock.patch.object(gg.time, "sleep", side_effect=sleep), \
                    mock.patch.object(gg, "direct_read", side_effect=fill), contextlib.redirect_stdout(io.StringIO()):
                self.assertEqual(gg.cmd_status("pr", f"o/r#{9 if upstream else 10}", False, True), 0)
            self.assertEqual(len(waits), 1)
            self.assertGreaterEqual(waits[0], expect)
            self.assertLess(waits[0], expect + 2)

    def test_status_says_not_found_and_could_not_judge_apart(self) -> None:
        self.put("pr:o/r#404", None, error="Could not resolve", missing=True)
        self.put("pr:o/r#5", None, error="graphql: HTTP 502")
        out = io.StringIO()
        reads: list[str] = []
        with mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "daemon_failing", return_value=None), \
                mock.patch.object(gg, "daemon_stale", return_value=None), \
                mock.patch.object(gg, "blocked_now", return_value=None), \
                mock.patch.object(gg, "say_waiting", lambda line: None), \
                mock.patch.object(gg, "direct_read", side_effect=lambda req: reads.append(req["key"]) or "rest: HTTP 502"), \
                contextlib.redirect_stdout(out):
            self.assertEqual(gg.cmd_status("pr", "o/r#404", False, False, first_wait=0), gg.EXIT_FAIL)
            self.assertEqual(gg.cmd_status("pr", "o/r#5", False, True, first_wait=0), gg.EXIT_DOWN)
        plain, doc = out.getvalue().split("\n{", 1)
        self.assertEqual(plain.strip().splitlines()[-1], "next: gh pr list -R o/r --state all --limit 5")
        doc = json.loads("{" + doc)
        self.assertEqual((doc["ok"], doc["code"], doc["next"]), (False, "no-data-yet", "glaeda-gh wait pr o/r#5 --timeout 600"))
        self.assertEqual(reads, ["pr:o/r#5"])  # missing is an answer; an error alone gets its one direct read

    def test_status_reads_directly_a_key_whose_entry_holds_only_an_error(self) -> None:
        """An entry with an error and no data (an upstream's failed read, kept for minutes) is unread: `status` makes
        its direct read and answers with the data, rather than exiting 3 at once."""
        self.put("pr:o/r#11", None, error="graphql: HTTP 200")

        def fill(req: dict) -> None:
            self.put(req["key"], gg.parse_pr(pr_node(11, rollup="SUCCESS", checks=[check_run("a")])))
            return None
        out = io.StringIO()
        with mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "daemon_failing", return_value=None), \
                mock.patch.object(gg, "daemon_stale", return_value=None), \
                mock.patch.object(gg, "blocked_now", return_value=None), \
                mock.patch.object(gg, "say_waiting", lambda line: None), \
                mock.patch.object(gg, "direct_read", side_effect=fill) as read, contextlib.redirect_stdout(out):
            self.assertEqual(gg.cmd_status("pr", "o/r#11", False, True, first_wait=0), gg.EXIT_OK)
        self.assertEqual(read.call_count, 1)
        self.assertTrue(json.loads(out.getvalue())["ok"])

    def test_a_run_github_cannot_resolve_is_missing_only_when_never_read(self) -> None:
        self.daemon.now = NOW
        entries = [{"key": "run:o/r/1", "cache": None}, {"key": "run:o/r/2", "cache": {"data": {"id": 2}}}]
        with mock.patch.object(self.daemon, "graphql", return_value=({"data": {"w0": None, "w1": None}}, None)):
            self.daemon.fetch_runs_graphql(entries)
        self.assertTrue(gg.read_cache("run:o/r/1")["missing"])
        self.assertFalse(gg.read_cache("run:o/r/2").get("missing"))  # it had data: an error, not gone
        limited = {"data": {"w0": None}, "errors": [{"type": "RATE_LIMITED", "message": "API rate limit exceeded"}]}
        with mock.patch.object(self.daemon, "graphql", return_value=(limited, None)):
            self.daemon.fetch_runs_graphql([{"key": "run:o/r/3", "cache": None}])
        self.assertFalse(gg.read_cache("run:o/r/3").get("missing"))

    def test_a_run_graphql_cannot_see_is_read_over_rest_once_not_retried_every_cycle(self) -> None:
        """leo-workspace runs 44343207314 and 44348360740 (2026-11-18): resource(url:) answered null for a private
        repo the GraphQL token cannot see, every cycle, "no workflow run at this URL", forever. REST (the login) sees it."""
        self.daemon.now = NOW
        run = {"id": 9, "name": "CI", "display_title": "x", "status": "completed", "conclusion": "success",
               "html_url": "https://github.com/o/r/actions/runs/9", "head_sha": "b" * 40, "head_branch": "x",
               "event": "push", "run_attempt": 1, "created_at": iso(NOW - 99), "updated_at": iso(NOW - 9)}
        self.gh.runs[9] = run
        entry = {"key": "run:o/r/9", "cache": None, "jobs": False, "touched": NOW}
        blind = ({"data": {"w0": None}}, None)
        with mock.patch.object(self.daemon, "graphql", return_value=blind) as gql:
            self.daemon.fetch_runs_graphql([entry])
            got = gg.read_cache("run:o/r/9")
            self.assertEqual(got["data"], gg.slim_run(run))  # REST's answer, not an error
            self.assertFalse(got.get("missing"))
            self.assertIsNone(got["error"])
            self.assertEqual(gql.call_count, 1)
            self.daemon.now = NOW + 60  # the next cycle asks REST directly: no GraphQL query is spent
            self.daemon.fetch_runs_graphql([{**entry, "cache": got}])
            self.assertEqual(gql.call_count, 1)
        self.assertEqual(len(self.gh.run_calls()), 2)
        # a run neither source shows: missing once, then not re-read every cycle
        gone = {"key": "run:o/r/404", "cache": None, "jobs": False, "touched": NOW}
        with mock.patch.object(self.daemon, "graphql", return_value=({"data": {"w0": None}}, None)):
            self.daemon.fetch_runs_graphql([gone])
        cache = gg.read_cache("run:o/r/404")
        self.assertTrue(cache["missing"])
        self.assertIsNone(cache.get("data"))
        self.daemon.now = cache["fetchedAt"] + gg.CYCLE
        self.daemon.last_cycle["run"] = 0
        self.assertEqual(self.daemon.due("run", [{**gone, "cache": cache}]), [])

    def test_a_blind_runs_read_window_ends_and_an_unread_one_is_not_stored(self) -> None:
        self.daemon.now = NOW
        self.gh.runs[9] = {"id": 9, "name": "CI", "display_title": "x", "status": "completed", "conclusion": "success",
                           "html_url": "u", "head_sha": "b" * 40, "head_branch": "x", "event": "push",
                           "run_attempt": 1, "created_at": iso(NOW - 99), "updated_at": iso(NOW - 9)}
        entry = {"key": "run:o/r/9", "cache": None, "jobs": False, "touched": NOW}
        with mock.patch.object(self.daemon, "graphql", return_value=({"data": {"w0": None}}, None)):
            self.daemon.fetch_runs_graphql([entry])
        stamp = gg.read_cache("run:o/r/9")["gqlBlindAt"]
        self.daemon.now = NOW + 60
        with mock.patch.object(self.daemon, "graphql") as gql:
            self.daemon.fetch_runs_graphql([{**entry, "cache": gg.read_cache("run:o/r/9")}])
        self.assertEqual(gg.read_cache("run:o/r/9")["gqlBlindAt"], stamp)  # reading inside the window keeps its end
        gql.assert_not_called()
        # out of time: nothing stored, the run is deferred
        fresh = {"key": "run:o/r/10", "cache": None, "jobs": False, "touched": NOW}
        with mock.patch.object(self.daemon, "graphql", return_value=({"data": {"w0": None}}, None)), \
                mock.patch.object(self.daemon, "fetch_run", side_effect=gg.OutOfTime()):
            self.daemon.fetch_runs_graphql([fresh])
        self.assertIsNone(gg.read_cache("run:o/r/10"))
        self.assertIn("run:o/r/10", self.daemon.deferred)
        # a timeout for the alias is not blindness: no fallback
        with mock.patch.object(self.daemon, "graphql", return_value=({"data": {"w0": None}, "errors": [
                {"path": ["w0"], "type": "SERVICE_UNAVAILABLE", "message": "timeout"}]}, None)), \
                mock.patch.object(self.daemon, "fetch_run") as rest:
            self.daemon.fetch_runs_graphql([{**fresh, "key": "run:o/r/11"}])
        rest.assert_not_called()

    def test_a_never_read_key_a_wait_is_on_goes_ahead_of_deferred_ones(self) -> None:
        self.daemon.now = NOW
        old = [{"key": f"pr:o/r#{n}", "cache": {"data": {}, "fetchedAt": NOW - 999}, "touched": NOW} for n in range(1, 4)]
        new = {"key": "pr:o/r#999", "cache": None, "touched": NOW, "waitedAt": NOW}
        self.daemon.deferred = {e["key"] for e in old}
        due = [e["key"] for e in self.daemon.due("pr", old + [new])]
        self.assertEqual(due[0], "pr:o/r#999")
        self.assertEqual(due[1:], [e["key"] for e in old])

    def test_a_call_without_its_kind_runs_as_the_call_meant(self) -> None:
        want = {
            ("wait", "o/r#5", "--until", "done"): ["wait", "pr", "o/r#5", "--until", "done"],
            ("wait", "https://github.com/o/r/pull/5"): ["wait", "pr", "https://github.com/o/r/pull/5"],
            ("status", "o/r#5", "o/r#6"): ["status", "pr", "o/r#5", "o/r#6"],
            ("wait", "o/r/123", "--timeout", "9"): ["wait", "run", "o/r/123", "--timeout", "9"],
            ("wait", "https://github.com/o/r/actions/runs/123"): ["wait", "run", "https://github.com/o/r/actions/runs/123"],
            ("land", "pr", "o/r#5"): ["land", "o/r#5"],
            ("wait", "pr", "o/r", "5", "--timeout", "9"): ["wait", "pr", "o/r#5", "--timeout", "9"],
            ("wait", "o/r", "#5"): ["wait", "pr", "o/r#5"],
            ("wait", "comment", "o/r", "5"): ["wait", "comment", "o/r#5"],
        }
        for given, fixed in want.items():
            got, note = gg.infer_kind(list(given))
            self.assertEqual(got, fixed)
            self.assertEqual(note, f"glaeda-gh: ran as `glaeda-gh {' '.join(fixed)}`")
            gg.parser().parse_args(got)  # argparse takes what it was handed
        for same in (["wait", "pr", "o/r#5"], ["wait", "file", "/x"], ["wait", "--help"], ["wait", "bogus"],
                     ["land", "o/r#5"], ["land", "status"], ["budget", "o/r#5"], ["wait"],
                     ["status", "pr", "o/r#5", "6"]):  # `wait run o/r 5` joins as o/r/5 (test_a_repo_and_a_number_are_joined)
            self.assertEqual(gg.infer_kind(list(same)), (same, ""))

