    def test_land_takes_a_head_pin_and_slash_targets(self) -> None:
        """Coordinator, 2026-11-21: `land manaflow-ai/cmux/48704 --match-head-commit SHA` was "unrecognized arguments"."""
        args = gg.parser().parse_args(["land", "manaflow-ai/cmux/48704", "--match-head-commit", "abc1234"])
        self.assertEqual((args.words, args.sha), (["manaflow-ai/cmux/48704"], "abc1234"))
        self.assertEqual(gg.land_key("manaflow-ai/cmux/48704")[1:], ("manaflow-ai/cmux", 48704))
        def only_local_git(argv, *a, **kw):
            # A pin is never checked by a GitHub read (test_land_pin_queues_with_the_shared_quota_spent). The one
            # thing it may run is the local checkout's own git: what repository this directory is, and its HEAD
            # (land_pin_is_another_checkouts_head). Neither touches the shared quota; an answer it cannot get
            # refuses nothing.
            self.assertEqual(argv[0], "git", "a pin is never checked by a read")
            self.assertIn(argv[-1], ("origin", "HEAD"), "a pin reads nothing but this checkout's repo and HEAD")
            return subprocess.CompletedProcess(argv, 1, "", "")
        with mock.patch.object(gg.subprocess, "run", side_effect=only_local_git):
            gg.check_land_pin("o/r", 1, None)
            gg.check_land_pin("o/r", 1, "aaaaaaa")
            gg.check_land_pin("o/r", 1, "a" * 40)
            with self.assertRaises(gg.WatchError):
                gg.check_land_pin("o/r", 1, "not-a-sha")

    def test_land_sha_head_pins_the_prs_current_head(self) -> None:
        """Leo: "You guys should now as standing rules start noticing and fixing tool calls ... Mistakes should also
        be auto fixed and ran properly". The forward_no_outcome stop says "--sha HEAD to pin it"; the tool refused it."""
        head = "c" * 40
        calls = []
        def read(argv):
            calls.append(argv)
            return head
        out = io.StringIO()
        with mock.patch.object(gg, "land_cached_head", return_value=""), mock.patch("sys.stderr", out):
            for word in ("HEAD", "head"):
                self.assertEqual(gg.land_resolve_head_word("o/r", 1, "k", word, read), head)
        self.assertIn(f"--sha HEAD: pinned to {head}", out.getvalue())
        self.assertEqual(calls[0][:3], ["gh", "api", "repos/o/r/pulls/1"])
        with mock.patch.object(gg, "land_cached_head", return_value="d" * 40), mock.patch("sys.stderr", io.StringIO()):
            self.assertEqual(gg.land_resolve_head_word("o/r", 1, "k", "HEAD", read), "d" * 40)
            self.assertEqual(gg.land_resolve_head_word("o/r", 1, "k", "abc1234", read), "abc1234")
            self.assertIsNone(gg.land_resolve_head_word("o/r", 1, "k", None, read))
        with mock.patch.object(gg, "land_cached_head", return_value=""):
            with self.assertRaises(gg.WatchError):
                gg.land_resolve_head_word("o/r", 1, "k", "HEAD", lambda a: None)
        with self.assertRaises(gg.WatchError):
            gg.check_land_pin_shape("not-a-sha")

    def test_the_word_for_a_pin_is_the_flag_for_a_pin(self) -> None:
        """gcp-agent-lane-2, 2026-11-22: `glaeda-gh land o/r#8293 --pin SHA` came back "unrecognized arguments:
        --pin" with the land unqueued, though `--pin` is what the rulebook ("land pinned <sha>") and every agent
        here call it. The word they type is the flag: --pin and --pinned are --sha, on land and on a wait."""
        sha = "a" * 40
        by_sha = gg.parser().parse_args(["land", "o/r#1", "--sha", sha])
        for word in ("--pin", "--pinned", "--match-head-commit"):
            args = gg.parser().parse_args(["land", "o/r#1", word, sha])
            self.assertEqual(args.sha, sha, word)
            self.assertEqual(vars(args), vars(by_sha), word)
        for kind, target in (("pr", "o/r#1"), ("run", "o/r/12")):
            waited = gg.parser().parse_args(["wait", kind, target, "--pin", sha])
            self.assertEqual(waited.sha, sha)
            self.assertEqual(vars(waited), vars(gg.parser().parse_args(["wait", kind, target, "--sha", sha])))

    def test_land_pin_queues_with_the_shared_quota_spent(self):
        """transcript-lessons (cmuxterm-hq#16805): `land --sha` refused "cannot read OWNER/REPO#N's head to check
        --match-head-commit" while the shared quota was short. Every gh read refused (gh-quota's exit 3): the pinned
        land is still queued, with its pin, and nothing was read."""
        refused = subprocess.CompletedProcess([], 3, "", "gh-quota: refused: REST rate limit is spent for login")
        tmp = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, tmp, True)
        with mock.patch.dict(os.environ, {"GLAEDA_STATE_DIR": str(tmp), "GH_QUOTA_STATE": str(tmp / "q")}), \
                mock.patch.object(gg.subprocess, "run", return_value=refused) as run, \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "land_judge", return_value=("/bin/true", [])), \
                mock.patch.object(gg, "land_queue_lane", return_value=""), \
                mock.patch.object(gg, "land_broker_client", return_value=False), \
                mock.patch.object(gg, "daemon_running", return_value=False), \
                mock.patch.object(gg, "land_request", return_value="rid-1") as req, \
                mock.patch("sys.stdout", io.StringIO()), mock.patch("sys.stderr", io.StringIO()):
            code = gg.cmd_land("o/r#1", [], "host/lane", 0, True, "b" * 40)
        self.assertEqual(code, gg.EXIT_DOWN)  # queued for the daemon (down in this test), not refused
        self.assertEqual(req.call_args.kwargs["sha"], "b" * 40)
        self.assertFalse([c for c in run.call_args_list if c.args and c.args[0][:1] == ["gh"]])

