    def test_the_stale_alarm_warns_when_waited_data_starves(self) -> None:
        """huge-blue 2026-11-11: a merged PR read OPEN for 50 minutes behind a fresh heartbeat, and nothing alarmed."""
        self.policy()
        key = gg.parse_key("pr", "o/r#5")
