    def test_an_upstream_with_no_broker_get_still_says_why_it_cannot_read(self) -> None:
        """An upstream that is not lane-gh, with no "direct" command: the fallback refuses as before, and the
        "upstream" explanation keeps such a wait on its blocker (its own read could not help)."""
        config = Path(self.tmp.name) / "upstream.json"
        gg.write_json(config, {"command": ["/usr/local/bin/other-upstream"]})
        with mock.patch.object(gg, "UPSTREAM_CONFIG", config), \
                mock.patch.object(gg, "run_bounded", side_effect=AssertionError("ran a program")):
            self.assertIsNone(gg.direct_command())
            self.assertEqual(gg.direct_read({"key": "pr:o/r#9", "kind": "pr", "began": time.time() - 700}),
                             gg.DIRECT_UPSTREAM)
            rid, _ = self.starved_request()
            self.daemon.upstream_status = {"state": "ok", "at": time.time()}
            self.daemon.serve_waits()
            self.assertTrue((gg.waits_dir() / f"{rid}.fifo").exists(), "handed back to a read that cannot happen")
        gg.write_json(config, {"command": ["/usr/local/bin/other-upstream"], "direct": ["/opt/broker-get"]})
        with mock.patch.object(gg, "UPSTREAM_CONFIG", config):
            self.assertEqual(gg.direct_command(), ["/opt/broker-get"])
        gg.write_json(config, {"command": ["/home/cmux/.local/bin/lane-gh", "glaeda-read"]})
        with mock.patch.object(gg, "UPSTREAM_CONFIG", config):
            self.assertEqual(gg.direct_command(), ["/home/cmux/.local/bin/lane-gh", "call", "get"])

    def starved_request(self) -> tuple[str, int]:
        gg.BASE.mkdir(parents=True, exist_ok=True)
        lock = open(gg.BASE / "daemon.lock", "a+")
        fcntl.flock(lock, fcntl.LOCK_EX)
        self.addCleanup(lock.close)
        gg.write_json(gg.BASE / "daemon.json", {"at": time.time(), "heartbeat": 30, "waits": gg.WAITS_CONTRACT})
        rid = gg.write_wait_request("pr", "o/r#9", "merged", 3600, False, False, None, True, gg.RESCUE_GRACE,
                                    os.getpid(), began=time.time() - gg.STALE_DATA_AFTER - 60)
        reader = os.open(gg.waits_dir() / f"{rid}.fifo", os.O_RDONLY | os.O_NONBLOCK)
        self.addCleanup(os.close, reader)
        self.put("pr:o/r#9", gg.parse_pr(pr_node(9)), at=time.time() - 3000)
        return rid, reader

    def test_no_hand_back_while_the_quota_explains_old_data(self) -> None:
        """Both buckets out: the wait's own read could not get through either, and every wait would turn into a
        Python poll for the rest of its timeout. It stays on the blocker."""
        rid, _ = self.starved_request()
        self.daemon.now = time.time()
        self.daemon.backoff = {"rest": time.time() + 600, "graphql": time.time() + 600}
        self.daemon.serve_waits()
        self.assertTrue((gg.waits_dir() / f"{rid}.fifo").exists(), "a quota-starved wait was handed back")
        self.assertIsNone(gg.read_json(gg.waits_dir() / f"{rid}.json").get("stale"))
        self.daemon.backoff = {"rest": 0.0, "graphql": 0.0}  # the quota is back and the data is still old
        self.daemon.serve_waits()
        self.assertFalse((gg.waits_dir() / f"{rid}.fifo").exists())

    def test_a_pr_wait_the_feed_shows_quiet_is_not_handed_back(self) -> None:
        """wait_feed_quiet: an old copy the feed shows nothing reached since it was read is current, so the wait stays
        on the blocker instead of reading its PR again through the broker; an event (or a copy past
        LAND_FEED_QUIET_MAX) hands it back as before."""
        rid, _ = self.starved_request()
        read_at = time.time() - gg.STALE_DATA_AFTER - 300
        self.put("pr:o/r#9", gg.parse_pr(pr_node(9)), at=read_at)
        asked = []
        quiet = [True]

        def feed_quiet(key, sha, since):
            asked.append((key, since))
            return quiet[0]

        self.daemon.land_feed_quiet = feed_quiet
        self.daemon.now = time.time()
        self.daemon.serve_waits()
        self.daemon.serve_waits()
        self.assertTrue((gg.waits_dir() / f"{rid}.fifo").exists(), "a wait on a quiet PR was handed back")
        self.assertEqual(asked[0][0], "pr:o/r#9")
        self.assertAlmostEqual(asked[0][1], read_at, delta=1)
        self.assertEqual(self.daemon.feed_unstarved, 1, "counted once per copy kept, not per pass")
        quiet[0] = False  # the feed delivered something for the PR
        self.daemon.serve_waits()
        self.assertFalse((gg.waits_dir() / f"{rid}.fifo").exists())

    def test_a_pr_copy_past_the_feed_bound_is_handed_back(self) -> None:
        rid, _ = self.starved_request()  # read 3000 s ago, past LAND_FEED_QUIET_MAX
        self.daemon.land_feed_quiet = lambda key, sha, since: True
        self.daemon.now = time.time()
        self.daemon.serve_waits()
        self.assertFalse((gg.waits_dir() / f"{rid}.fifo").exists())
        self.assertEqual(self.daemon.feed_unstarved, 0)

    def test_a_handed_back_request_past_its_deadline_is_dropped(self) -> None:
        rid, _ = self.starved_request()
        self.daemon.serve_waits()
        req = gg.read_json(gg.waits_dir() / f"{rid}.json")
        self.assertIsNotNone(req["stale"])
        gg.write_json(gg.waits_dir() / f"{rid}.json", {**req, "began": time.time() - float(req["timeout"]) - gg.WAITS_LEFTOVER - 10})
        self.daemon.serve_waits()
        self.assertFalse((gg.waits_dir() / f"{rid}.json").exists(), "a reused pid would keep it for ever")

