    def test_snapshot_waits_are_capped_and_an_expired_wait_keeps_its_place_while_workers_are_busy(self):
        pool = self.pooled(1)
        for n in range(1, 5):
            key = f"pr:o/r#{n}"
            self.pr(LA, key=key)
            self.w.cache[key]["fp"] = "F"  # no snapshot: each judgment waits for the daemon's read first
            self.land(f"o/r#{n}")
        self.tick()
        waiting = [k for k, e in self.q.entries.items() if e.get("snapshotWait")]
        self.assertEqual(len(waiting), 2)  # one per worker, one ahead: not all 4 (each nudges a read)
        self.assertEqual(self.w.nudged.count("pr:o/r#3") + self.w.nudged.count("pr:o/r#4"), 0)
        self.tick(gg.LAND_SNAPSHOT_WAIT + 1)
        self.assertEqual(len(pool.handed), 1)  # the first expired wait judged live in the same pass
        other = [k for k in waiting if k != pool.keys()[0]][0]
        events = [h.get("event") for h in self.q.entries[other]["history"]]
        self.assertEqual((events.count("snapshot_wait"), events.count("snapshot_missing")), (1, 0))
        self.tick()
        self.assertEqual(len(pool.handed), 1)
        pool.handed[0][1].finished = True
        self.tick()
        self.assertEqual(pool.keys()[1], other)  # the next free worker goes to it, no second two-minute wait
        events = [h.get("event") for h in self.q.entries[other]["history"]]
        self.assertEqual((events.count("snapshot_wait"), events.count("snapshot_missing")), (1, 1))

    def test_run_out_snapshot_waits_hold_no_place_while_a_worker_is_free(self):
        """huge-blue, 2026-11-22 06:59-09:50Z: 43 rows held snapshotWait, 14 of them hours old and no longer judged,
        so the waits filled every place ahead of the workers with 2 of 12 busy, and each row whose snapshot was not
        ready read "every worker busy"."""
        pool = self.pooled(2)
        for n in range(1, 4):
            key = f"pr:o/r#{n}"
            self.pr(LA, key=key)
            self.w.cache[key]["fp"] = "F"  # no snapshot: each judgment waits for the daemon's read first
        for n in (1, 2, 3):
            self.land(f"o/r#{n}")
        self.tick()
        self.assertEqual(len([e for e in self.q.entries.values() if e.get("snapshotWait")]), 3)
        stale = self.q.entries
        for n in (1, 2, 3):  # three rows left with a wait hours old that the pass no longer judges
            stale[f"pr:o/r#{n}"]["snapshotWait"] = {"sha": LA, "since": self.t - 3 * 3600}
        self.pr(LA, key="pr:o/r#9")
        self.w.cache["pr:o/r#9"]["fp"] = "F"
        self.land("o/r#9")
        consider = self.q.consider
        with mock.patch.object(self.q, "consider", lambda e: None if e["key"] != "pr:o/r#9" else consider(e)):
            self.tick()
        e = self.q.entries["pr:o/r#9"]
        self.assertTrue(e.get("snapshotWait"), "a new wait starts: run-out waits hold no place with workers free")
        self.assertIn("pr:o/r#9", self.w.nudged)
        self.assertEqual(self.q.snapshot_places(True), 1)
        self.assertEqual(self.q.snapshot_places(False), 4)  # every worker busy: each wait keeps its place, as before
        self.assertEqual(len(pool.handed), 0)

    def test_a_due_row_the_snapshot_room_keeps_out_is_judged_live_on_a_free_worker_after_a_waits_length(self):
        """cmux-cp-1, 2026-11-23 08:42-10:07Z: 6-10 of 24 workers busy, 42-45 snapshot waits renewed by other rows
        each pass, and 78 rows due late (the oldest 85 min), each "snapshot waits ahead fill the room": a row with no
        wait of its own never got a place, so it never reached the live judgment a run-out wait ends in."""
        pool = self.pooled(2)
        full = self.q.workers() * (1 + gg.LAND_SNAPSHOT_AHEAD)
        self.pr(LA, key="pr:o/r#1")
        self.w.cache["pr:o/r#1"]["fp"] = "F"  # no snapshot: a judgment would wait for the daemon's read first
        self.land("o/r#1")
        # the other rows' waits fill the room ahead of the workers, each renewed as the one before it ran out
        with mock.patch.object(self.q, "snapshot_places", lambda free: full):
            self.tick()
            e = self.q.entries["pr:o/r#1"]
            self.assertFalse(e.get("snapshotWait"))
            self.assertEqual(len(pool.handed), 0, "inside a wait's length the room still holds it")
            self.assertNotIn("pr:o/r#1", self.w.nudged)
            for _ in range(3):
                self.tick(gg.LAND_SNAPSHOT_WAIT / 2 + 1)
        self.assertEqual(pool.keys(), ["pr:o/r#1"], "judged live on the free worker, past a wait's length")
        events = [h.get("event") for h in self.q.entries["pr:o/r#1"]["history"]]
        self.assertEqual(events.count("snapshot_room_live"), 1)
        self.assertEqual(events.count("snapshot_wait"), 0)

