        self.land()
        self.w.answers.append(refusal("unreadable", LA, {"kind": "fetch", "argv": self.git_fetch()}))
        e = self.tick()
        self.assertEqual((e["state"], e["stop"]["code"], self.fetch_calls()), ("stopped", "policy", []))
        self.assertIn("not github.com/o/r", e["stop"]["reason"])

