        self.assertEqual((e["state"], e["wait"]["kind"], e["unrelatedReruns"]), ("waiting", "pr", [f"{LA}|{self.RUN}"]))
        self.assertIsNone(e.get("stop"))
        self.pr_red(False, running=True)
        self.tick()
        self.assertEqual(len(self.w.explains()), 1)
        self.pr_red(False)
