        self.assertEqual((e["state"], e["wait"]["kind"]), ("waiting", "pr"), e.get("history"))
        self.assertIn("refused at setup", json.dumps(e["history"]))
        self.pr_red(False)
        self.w.answers.append(ok_answer(LA))
        self.tick()
        self.assert_merged_at(LA)

