        e = self.tick(30)
        self.assertNotEqual(e["state"], "stopped", e.get("stop"))
        self.w.answers.append(ok_answer(LB))
        e = self.run_hour(lambda: ok_answer(LB), seconds=600, step=30.0)
        self.assertEqual((e["state"], e.get("stop"), e["pinSha"]), ("merged", None, LB))
