    def webview_wait(self, head: str = LA, timeout: int = 900) -> tuple[int, dict]:
        """land_judge's "webview" refusal, whose step is a wait on the checks (LAND_FALLBACK) and whose reason names
        the PR's own reds."""
        nxt = f"glaeda-gh wait pr o/r#1 --until done --sha {head} --timeout {timeout}"
        return refusal("webview", head, {"kind": "wait_pr", "sha": head, "until": "done", "timeout_s": timeout},
                       nxt=nxt, reason="land-judge: refused: its per-test webview verdict names its own reds "
                                       "(react-apps-base-check failed); fix them, or rerun if one is a flake")

    def test_a_check_read_differently_is_not_the_wait_making_progress(self):
        """A wait's stuck bound counts the checks it waits on, not every check's conclusion (LAND_WAIT_STUCK). Queue
        host, 2026-11-22: cmux#48267's reads 500 s apart changed 50 of their 223 checks, each a completed check whose
        workflow one read gave as its run's name and the next as its workflow's, and cmux#49430 read 175 of its 208
        checks under GitHub's rate limit; every flip reset movedAt."""
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS"), ("x", "COMPLETED", "SUCCESS")])
        self.land()
        self.w.answers.append(self.webview_wait())
        e = self.tick()
        moved = e["waitRefused"]["movedAt"]
        self.assertEqual(moved, self.t)
        for checks in ([("ci", "COMPLETED", "SUCCESS")],  # a check page the read could not finish: one check less
                       [("ci", "COMPLETED", "SUCCESS"), ("x", "COMPLETED", "NEUTRAL")],  # read differently
                       [("ci", "COMPLETED", "SUCCESS"), ("x", "COMPLETED", "SUCCESS")]):
            self.pr(LA, checks=checks)
            self.w.answers.append(self.webview_wait())
            e = self.tick(700)
            self.assertEqual(e["waitRefused"]["movedAt"], moved, checks)
        self.assertGreaterEqual(e["waitRefused"]["count"], 4)  # each was judged again: only the bound is unmoved
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS"), ("x", "COMPLETED", "SUCCESS"), ("y", "QUEUED", None)])
        self.w.answers.append(self.webview_wait())
        e = self.tick(1000)  # past the wait's own timeout, which judges it again
        self.assertEqual(e["waitRefused"]["movedAt"], self.t)  # a check started: the wait moved

    def test_a_wait_on_checks_that_never_move_stops_and_tells_its_requester(self):
        """cmux#49430, 2026-11-22: a "webview" refusal naming the PR's own reds took 51 waits in 9.8 h at one head,
        every one logged idle 0 while no check at that head was unfinished at all, because its check fingerprint
        flipped between two values in reads 60 s apart. 5 such rows were judged 52 times in 24 h past the 4 h bound
        they should have stopped at, 4 of them with no stop at all."""
        self.pr(LA, checks=[("ci", "COMPLETED", "FAILURE"), ("x", "COMPLETED", "SUCCESS")])
        self.land()
        end = self.t + gg.LAND_WAIT_STUCK + 2 * gg.LAND_WAIT_DEFAULT
        flip = 0
        e: dict = {}
        while self.t < end:
            flip += 1
            self.pr(LA, checks=[("ci", "COMPLETED", "FAILURE"),
                                ("x", "COMPLETED", "SUCCESS" if flip % 2 else "NEUTRAL")])
            while len(self.w.answers) < 2:
                self.w.answers.append(self.webview_wait())
            e = self.tick(300)
            if e.get("state") in gg.LAND_DONE:
                break
        self.assertEqual((e["state"], e["stop"]["code"]), ("stopped", "checks_stuck"), e.get("stop"))
        self.assertIn("none the cache shows", e["stop"]["reason"])
        self.assertIn("react-apps-base-check", e["stop"]["reason"])  # the requester is told what to fix
        self.assertEqual(len(self.w.sent()), 1, self.w.sent())
        # stopped on its own bound, not one flip later: nothing it waits for moved since its first refusal
        waited = e["stop"]["at"] - e["waitRefused"]["since"]
        self.assertLess(waited, gg.LAND_WAIT_STUCK + 600, waited)

    def queued_wait(self, head: str = LA, timeout: int = 1800) -> tuple[int, dict]:
        nxt = f"glaeda-gh wait pr o/r#1 --until done --sha {head} --timeout {timeout}"
        return refusal("checks_running", head, {"kind": "wait_pr", "sha": head, "until": "done", "timeout_s": timeout},
                       nxt=nxt, reason=f"land-judge: refused: checks still running at {head[:8]}")

    def test_each_judgment_logs_its_wall_time(self):
        # The entry pops judging after each judgment, so nothing else on the land host says how long one took.
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS")])
        self.w.answers.append(ok_answer(LA))
        self.land()
        lines: list[dict] = []
        with mock.patch.object(gg, "log", lines.append):
            self.tick()
        judged = [ln for ln in lines if ln.get("event") == "land-judged"]
        self.assertEqual(len(judged), 1, lines)
        self.assertEqual((judged[0]["key"], judged[0]["code"], judged[0]["step"], judged[0]["head"]),
                         (self.KEY, "ok", "merge", LA[:12]))
        self.assertIsInstance(judged[0]["took_s"], float)
        self.assertGreaterEqual(judged[0]["took_s"], 0.0)
        self.assertIsNone(judged[0]["from"])  # its first judgment ended no wait

    def test_a_judgment_logs_the_wait_it_ended(self):
        # "woke" alone did not say which wait's timer ran (queue host, 2026-11-22: 42 checks_running rows why=woke).
        self.pr(LA)
        self.w.answers.append(self.queued_wait(timeout=120))
        self.land()
        self.tick()
        self.w.answers.append(self.queued_wait(timeout=120))
        lines: list[dict] = []
        with mock.patch.object(gg, "log", lines.append):
            self.tick(121)
        judged = [ln for ln in lines if ln.get("event") == "land-judged"]
        self.assertEqual([(j["why"], j["from"]) for j in judged], [("woke", "pr:checks_running")], lines)

    def test_checks_running_refusals_at_one_head_never_stop(self):
        # hq#12626 (d5bf1325) and hq#12595 (db2a372b), 2026-11-18 ~15:50Z: hosted Linux runners queued ~50 min, each
        # 1800 s wait timed out with the checks still queued, and the third judgment stopped both: "checks_running: 3
        # identical refusals in a row". Checks still running are a wait: taken and judged again, never a stop.
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS"), ("linux", "QUEUED", None)])
        self.land()
        e = self.run_hour(self.queued_wait, seconds=3 * gg.LAND_WAIT_DEFAULT, step=60.0)
        judged = [h for h in e["history"] if h["event"] == "judged"]
        self.assertGreaterEqual(len(judged), 3)
        self.assertEqual({h["code"] for h in judged}, {"checks_running"})
        self.assertEqual((e["state"], e["wait"]["kind"], e["streak"], e["waitRefused"]["count"]),
                         ("waiting", "pr", None, len(judged)))
        self.assertEqual(self.w.sent(), [], "no stop, nobody asked to requeue")
        # Every one of those judgments after the first was made at the same head on the same check set: the queued
        # check never moved in these 3 h, so each could only reach the verdict above it (explain_unmoved).
        self.assertEqual([h.get("unmoved") for h in judged], [None] + [True] * (len(judged) - 1))
        # the checks start: progress, the wait goes on past the bound counted from the first refusal
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS"), ("linux", "IN_PROGRESS", None)])
        e = self.run_hour(self.queued_wait, seconds=gg.LAND_WAIT_STUCK - 2 * gg.LAND_WAIT_DEFAULT, step=60.0)
        self.assertEqual((e["state"], self.w.sent()), ("waiting", []))
        # they finish green: merged at that head
        self.pr(LA, checks=[("ci", "COMPLETED", "SUCCESS"), ("linux", "COMPLETED", "SUCCESS")])
        self.w.answers[:] = [ok_answer(LA)]
        self.tick()
        self.assert_merged_at(LA)

    def test_a_judgment_on_an_unmoved_check_set_is_counted(self):
        # The instrumentation the keep was measured with: a judgment at the same head on the same check runs,
        # statuses and conclusions could only reach the verdict above it (`land status`: explain_unmoved).
        self.pr(LA)
        self.land()
        for _ in range(4):
            self.w.answers.append(refusal("unreadable", LA, {"kind": "retry", "after_s": 120},
                                          reason="land-judge: refused: the classifier could not read the reds"))
        e = self.run_hour(lambda: refusal("unreadable", LA, {"kind": "retry", "after_s": 120},
                                          reason="land-judge: refused: the classifier could not read the reds"),
                          seconds=400.0, step=60.0)
        judged = [h for h in e["history"] if h["event"] == "judged"]
        day = (gg.read_json(gg.land_dir() / "counts.json").get("days") or {}).get(gg.land_day(self.t)) or {}
        self.assertGreaterEqual(len(judged), 2)
        self.assertEqual(day.get("explain_unmoved"), len(judged) - 1)
        self.assertEqual([h.get("unmoved") for h in judged], [None] + [True] * (len(judged) - 1))
        # Every one of them ran because the retry's own backoff ran out, which is the queue working as designed,
        # never work it could have skipped: the count says so by kind, so the total is not read as waste.
        self.assertEqual([h.get("why") for h in judged], ["queued"] + ["woke"] * (len(judged) - 1))
        self.assertEqual([h.get("due") for h in judged], [None] + [True] * (len(judged) - 1))
        self.assertEqual(day.get("explain_unmoved_woke"), len(judged) - 1)
        split = gg.land_unmoved_split(day)
        self.assertEqual((split["due"], split["redundant"], split["redundantByWhy"]),
                         (len(judged) - 1, 0, {}))

    def test_a_mergeability_flip_alone_never_judges_however_long_it_waits(self):
        # The other half of the same count, since removed: mergeable UNKNOWN <-> MERGEABLE turns on every push to the
        # base, and while land_fingerprint (which the wake reads) held that raw value, each push moved it twice at an
        # unchanged head on unchanged checks; past LAND_VERDICT_KEEP it judged again for an answer that cannot differ
        # (5 judgments an hour per parked PR, measure-land-wake-redundancy.py; 69 of 669 on one host 2026-11-25).
        # The wake now reads mergeability as the judge does -- CONFLICTING or not -- so no flip wakes it at any age,
        # and what the fingerprint cannot see is bounded by the wait's own timeout, as it always was.
        wait = lambda sha=LA: refusal("checks_running", sha, {"kind": "wait_pr", "sha": sha, "until": "done",
                                                              "timeout_s": 100 * gg.LAND_VERDICT_KEEP})
        self.pr(LA)
        self.land()
        self.w.answers.append(wait())
        e = self.tick()
        self.assertEqual((e["state"], e["wait"]["kind"]), ("waiting", "pr"))
        first = len(self.w.explains())
        for n, mergeable in enumerate(("UNKNOWN", "MERGEABLE", "UNKNOWN", "MERGEABLE")):
            self.pr(LA, mergeable=mergeable)  # a push to the base: same head, same checks
            e = self.tick(gg.LAND_VERDICT_KEEP)  # each turn older than the keep that used to let it through
            self.assertEqual(len(self.w.explains()), first, f"flip {n} judged again")
        day = (gg.read_json(gg.land_dir() / "counts.json").get("days") or {}).get(gg.land_day(self.t)) or {}
        self.assertEqual(day.get("explain_unmoved_fp_moved"), None)
        self.assertEqual(gg.land_unmoved_split(day)["redundantByWhy"], {})
        # A CONFLICTING turn is the one mergeability change the verdict answers differently: judged at once.
        self.pr(LA, mergeable="CONFLICTING")
        self.w.answers.append(wait())
        self.tick()
        self.assertEqual(len(self.w.explains()), first + 1)

    def test_land_status_never_prints_the_unmoved_total_without_its_split(self):
        # A count whose name reads as waste has to say which half is skippable, in the line that prints it.
        day = {"explain": 10, "explain_unmoved": 4, "explain_unmoved_woke": 3, "explain_unmoved_fp_moved": 1}
        split = gg.land_unmoved_split(day)
        self.assertEqual((split["judged"], split["unmoved"], split["due"], split["redundant"]), (10, 4, 3, 1))
        self.assertTrue(set(gg.LAND_JUDGE_DUE) <= set(gg.LAND_JUDGE_WHY))
        self.assertEqual(gg.land_unmoved_split({}), {"judged": 0, "unmoved": 0, "due": 0, "redundant": 0,
                                                     "byWhy": {}, "redundantByWhy": {}})

