    def test_alternating_broker_land_refusals_are_not_read_as_one_and_never_stop_the_entry(self):
        # Router review of glaeda#2239, F1: broker_land kept the indented envelope in stdout, so land_step_class read
        # every refusal with no `refused [code` as its last line, `}`. A lease busy and read Apps busy, alternating,
        # then counted as LAND_STEP_STOP identical refusals and stopped the entry; on a host they keep it waiting.
        self.broker = True
        self.pr(LA)
        self.land()
        self.w.gh_rc["merge"] = 1
        said = ("land: the lane lease for o/r#1 is held by another session; try again after it is released",
                "get: the broker's read Apps are busy for o; try again in 60 s")
        e = {}
        for i in range(gg.LAND_STEP_STOP + 2):
            self.w.gh_err["merge"] = said[i % 2]
            self.w.answers.append(ok_answer(LA))
            e = self.tick(gg.LAND_STEP_BACKOFF_MAX + 1)
        self.assertEqual(len(self.broker_lands()), gg.LAND_STEP_STOP + 2)
        self.assertEqual(e["state"], "waiting", e.get("stop"))
        # each refusal is counted as itself: the last one (read Apps busy) is a first, not an eighth
        self.assertEqual((e["stepFail"]["class"], e["stepFail"]["count"]), (gg.land_step_class(said[1]), 1))

    def test_land_step_class_reads_a_json_documents_words_not_its_closing_brace(self):
        # manaflow-ai/cmux#47213, 2026-11-23 08:14:33Z: a broker land answered ok without merging, its indented envelope
        # was the step's output, and history said `why=}`.
        out = json.dumps({"ok": True, "status": 200, "data": {"ok": True, "merged": False,
                          "reason": "checks still running at abc1234: 3 queued; next: glaeda-gh wait pr o/r#1"}}, indent=1)
        self.assertEqual(gg.land_step_class(out), "checks still running at #: # queued; next: glaeda-gh wait pr o/r##")
        self.assertEqual(gg.land_step_class("refused: busy\n}\n"), "refused: busy")
        self.assertEqual(gg.land_step_class("{}"), "no output")
        self.assertEqual(gg.land_step_class(""), "no output")

    def test_a_draft_pr_stops_at_the_first_refusal_and_names_gh_pr_ready(self):
        """A draft is permanent until someone marks it ready, so one refusal is the whole answer. 2026-11-21,
        leo-workspace#7087 (opened as a draft by the PreCompact checkpoint hook): six identical "Pull Request is
        still a draft" merge calls over ~31 min, with the GraphQL pool at its floor, and a stop naming no step."""
        for said in ("GraphQL: Pull Request is still a draft (mergePullRequest)",
                     "pull request is in draft state", "Draft pull requests cannot be merged"):
            self.assertTrue(gg.LAND_STEP_DRAFT.search(said), said)
        for said in ("GraphQL: Pull Request is not mergeable (mergePullRequest)", "the PR is a draft review"):
            self.assertIsNone(gg.LAND_STEP_DRAFT.search(said), said)
        self.pr(LA)
        # Converted to a draft *after* its request, which is why this check cannot be replaced by the request-time
        # one: at the request this host's read said the PR was ready, so land_draft_refusal has nothing to answer.
        gg.write_json(gg.cache_dir() / gg.file_name(self.KEY),
                      {"key": self.KEY, "data": land_pr(LA), "dataAt": time.time()})
        self.assertIsNone(gg.land_draft_refusal(self.KEY, "o/r", 1))
        self.land()
        self.w.gh_rc["merge"] = 1
        self.w.gh_err["merge"] = "GraphQL: Pull Request is still a draft (mergePullRequest)"
        self.w.answers.append(ok_answer(LA))
        e = self.tick()
        self.assertEqual((e["state"], e["stop"]["code"]), ("stopped", "merge_draft"), e.get("stop"))
        self.assertEqual(e["stop"]["next"], "gh pr ready 1 -R o/r, then glaeda-gh land o/r#1")
        self.assertIn("still a draft", e["stop"]["reason"])
        self.assertNotIn("stepFail", e)  # no streak to count: nothing waits, nothing retries
        self.assertIn("stopped: merge_draft", self.w.sent()[-1][-1])

    def test_land_refuses_a_draft_pr_at_the_request_and_names_gh_pr_ready(self):
        """The other half of the one above: *when* the answer comes. efficiency-standing-lane, 2026-11-21: one host's
        queue stopped 7 rows merge_draft 139 min after their own land requests in total (median 13.6 min, worst
        53.3 min: manaflow-ai/cmuxterm-hq#16729),
        every refusal carrying "land-judge (pass): ok: ... may merge at <sha>" -- a full CI wait, a judgment and a
        merge call spent on `isDraft`, which was already true when `land` was typed, and 65 more minutes sitting
        stopped. A request this host can answer from its cache is answered at once, with the step that clears it."""
        self.pr(LA, draft=True)
        self.store_pr(land_pr(LA, draft=True))
        said: list[str] = []
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "say_waiting", side_effect=said.append), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("nothing is queued")), \
                mock.patch.object(gg.subprocess, "run", side_effect=AssertionError("no read, no judge, no step")):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, False, "b" * 40)
        self.assertEqual(rc, gg.EXIT_FAIL)
        self.assertIn("o/r#1 is a draft", said[0])
        self.assertIn("GitHub refuses every merge on a draft", said[0])
        self.assertIn("stays yours", said[0])  # nothing here marks a PR ready: [hold-own-pr]
        # The step, with the pin carried through, so the re-land is still pinned to the head the caller judged.
        self.assertIn(f"next: gh pr ready 1 -R o/r, then glaeda-gh land o/r#1 --match-head-commit {'b' * 40}",
                      said[0])
        self.assertEqual(list(gg.LandQueue.requests_dir().glob("*.json"))
                         if gg.LandQueue.requests_dir().is_dir() else [], [])
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"], doc["key"]), (gg.EXIT_FAIL, False, "land_draft", self.KEY))
        self.assertEqual(doc["next"], "gh pr ready 1 -R o/r, then glaeda-gh land o/r#1")

    def test_a_pin_this_queue_already_followed_forward_leaves_the_live_row_alone(self):
        """A land the queue already followed forward is answered with the pin the row holds, never re-pinned backwards.
        efficiency-standing-lane, 2026-11-22: glaeda#2542 was queued pinned 27b86dab, followed to 3ec2af7c by
        repin_own_update at 20:00Z, and the head was ed96f931 when a re-pin at 3ec2af7c reached the queue at 20:06Z,
        which parked the row in pin_wait for a head that was already gone. NOW counts that class (land-re-pin-loop,
        14 that day): the agent watching from outside sees a head that is not its pin, re-pins by hand, and by then
        the hand-written pin is the stale one."""
        entry = {"key": self.KEY, "state": "waiting", "pinSha": LB, "requester": "host/lane",
                 "history": [{"event": "repin_own_update", "head": LB[:12], "pin": LA[:12]}]}
        gg.write_json(gg.LandQueue.entries_dir() / gg.file_name(self.KEY), entry)
        said: list[str] = []
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "say_waiting", side_effect=said.append), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("the live row is not re-queued")):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, False, LA)
        self.assertEqual(rc, gg.EXIT_OK)  # not a refusal: the row is live and pinned ahead of this request
        self.assertIn(f"the row holds {LB[:12]}", said[0])
        self.assertIn("park it (pin_wait), so nothing was changed", said[0])
        self.assertIn(f"next: glaeda-gh wait pr o/r#1 --until merged --sha {LB} --timeout 1800", said[0])
        # The row itself is untouched: same state, same pin, no history written by the request.
        self.assertEqual(gg.read_json(gg.LandQueue.entries_dir() / gg.file_name(self.KEY)), entry)
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("the live row is not re-queued")), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, LA)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"], doc["key"]), (gg.EXIT_OK, True, "land_pin_followed", self.KEY))
        self.assertEqual((doc["pin"], doc["was"]), (LB, LA))

    def test_only_this_requester_s_own_live_followed_row_answers_a_pin(self):
        """What the check does *not* read as a follow: a finished row, an unpinned one, one still pinned where the
        caller pinned, another session's row, and a history with no follow away from this pin. Each of those is queued
        exactly as it always was, since only the queue's own recorded follow proves the caller's pin is the stale one."""
        follow = {"event": "repin_own_update", "head": LB[:12], "pin": LA[:12]}
        live = {"state": "waiting", "pinSha": LB, "requester": "host/lane", "history": [follow]}
        self.assertEqual(gg.land_pin_already_followed(live, LA, "host/lane"), LB)
        for event in gg.LAND_PIN_FOLLOW_EVENTS:  # every follow event records the pin it moved away from
            for field in ("pin", "was"):
                self.assertEqual(gg.land_pin_already_followed(
                    {**live, "history": [{"event": event, field: LA[:12]}]}, LA, "host/lane"), LB, (event, field))
        for entry, why in ((None, "no row at all"),
                           ({}, "an empty row"),
                           ({**live, "state": "merged"}, "a merged row"),
                           ({**live, "state": "stopped"}, "a stopped row"),
                           ({**live, "pinSha": ""}, "an unpinned row"),
                           ({**live, "pinSha": "nope"}, "a pin that is no sha"),
                           ({**live, "pinSha": LA}, "a row still pinned where the caller pinned"),
                           ({**live, "requester": "other/lane"}, "another session's row"),
                           ({**live, "history": []}, "no history"),
                           ({**live, "history": [{"event": "queued", "pin": LA[:12]}]}, "no follow event"),
                           ({**live, "history": [{**follow, "pin": LC[:12]}]}, "a follow away from another pin")):
            self.assertEqual(gg.land_pin_already_followed(entry, LA, "host/lane"), "", why)
        self.assertEqual(gg.land_pin_already_followed(live, "", "host/lane"), "", "an unpinned request")

    def test_a_draft_read_that_is_stale_or_shadowed_by_a_write_refuses_nothing(self):
        """A refusal built from a read that may no longer hold is never final: it is queued as before, and the
        merge-time check answers it. So the request-time check keeps inside the live-field bound, and drops a read a
        write that could have marked the PR ready (the brokered `gh pr ready` itself) came after."""
        self.assertEqual(gg.LAND_DRAFT_AGE, gg.BROKER_MAX_AGE)  # isDraft is in BROKER_LIVE_FIELDS
        now = time.time()
        draft = land_pr(LA, draft=True)
        self.store_pr(draft, at=now)
        self.assertIsNotNone(gg.land_draft_refusal(self.KEY, "o/r", 1))
        for at, writes, why in ((now - gg.LAND_DRAFT_AGE - 1, {}, "older than the live-field bound"),
                                (now + 600, {}, "stamped in the future"),
                                (now, {"o/r pr 1": now + 1}, "a `gh pr ready` write after the read"),
                                (now, {"*": now + 1}, "a write with no repository of its own")):
            self.store_pr(draft, at=at)
            gg.write_json(gg.gh_cache_dir() / "writes.json", writes)
            self.assertIsNone(gg.land_draft_refusal(self.KEY, "o/r", 1), why)
        gg.write_json(gg.gh_cache_dir() / "writes.json", {})
        for data, why in ((land_pr(LA), "not a draft"), (land_pr(LA, state="MERGED", draft=True), "not open"),
                          ({"state": "OPEN"}, "no isDraft stored"),):
            self.store_pr(data, at=now)
            self.assertIsNone(gg.land_draft_refusal(self.KEY, "o/r", 1), why)
        gg.write_json(gg.cache_dir() / gg.file_name(self.KEY),
                      {"key": self.KEY, "data": draft, "dataAt": now, "error": "quota"})
        self.assertIsNone(gg.land_draft_refusal(self.KEY, "o/r", 1), "a failed read")
        (gg.cache_dir() / gg.file_name(self.KEY)).unlink()
        self.assertIsNone(gg.land_draft_refusal(self.KEY, "o/r", 1), "no read at all")

    def test_a_pin_the_head_has_already_passed_is_refused_at_the_request(self):
        """A pin is trusted as given, because the cache's head is routinely older than the head an agent just pushed
        and pinned (pin_wait). An *ancestor* of the cached head is the other direction and is certain: 2026-11-21 a
        lane landed leo-workspace#7547 pinned fc1415273c, the commit its own head had merged minutes before, and the
        row waited in pinWait for a head that was already gone while GitHub was down. One local `merge-base
        --is-ancestor` tells the two apart and costs no quota."""
        def git(rest: list[str]) -> str | None:
            # git's own answers: "" (no output) when the command succeeded, None when it failed. This checkout holds
            # every commit asked about, and LA is an ancestor of LB.
            if rest[:2] == ["cat-file", "-e"]:
                return "" if rest[2].split("^")[0] in (LA, LA[:12], LB) else None
            return ("" if rest[:2] == ["merge-base", "--is-ancestor"] and LA.startswith(rest[2])
                    and rest[3] == LB else None)
        said = gg.land_pin_behind_refusal("o/r", 1, LA, LB, git)
        self.assertIsNotNone(said)
        why, nxt = said
        self.assertIn(f"--match-head-commit {LA[:12]} is an ancestor of o/r#1's head {LB[:12]}", why)
        self.assertIn("stop head_moved", why)
        self.assertEqual(nxt, f"glaeda-gh land o/r#1 --match-head-commit {LB}")
        self.assertEqual(said, gg.land_pin_behind_refusal("o/r", 1, LA[:12], LB, git))  # a short pin reads the same
        # Every other case refuses nothing: the pin *is* the head, the pin is a newer commit than the cached head
        # (which is the normal pinned land), this checkout does not hold both commits, or git could not answer.
        self.assertIsNone(gg.land_pin_behind_refusal("o/r", 1, LB, LB, git))
        self.assertIsNone(gg.land_pin_behind_refusal("o/r", 1, LB, LA, git))
        self.assertIsNone(gg.land_pin_behind_refusal("o/r", 1, LA, "", git))
        self.assertIsNone(gg.land_pin_behind_refusal("o/r", 1, "", LB, git))
        self.assertIsNone(gg.land_pin_behind_refusal("o/r", 1, LA, LB, lambda rest: None))

    def test_a_pin_typed_out_from_an_abbreviated_head_is_refused_by_name(self):
        """Measured twice on 2026-11-21: a pin was written by taking the 10-hex head a command had printed and
        filling the rest in, `71b0560d5f` + zeros for a head that really ends `ffc48103c984e90c77ec6672abaeac5`.
        The request was accepted and answered "requested; the daemon takes it next tick", and the row could then
        only wait out a head that does not exist. No commit of the repository has that sha, but nothing local can
        say so cheaply. What can: a 40-hex pin that shares a long prefix with the cached head and then differs is
        not two commits that happen to collide (12 hex is one chance in 2^48), it is an abbreviation someone
        finished by hand."""
        invented = LB[:12] + "0" * 28
        said = gg.land_pin_extends_head_refusal("o/r", 1, invented, LB)
        self.assertIsNotNone(said)
        why, nxt = said
        self.assertIn(f"--match-head-commit {invented[:12]}", why)
        self.assertIn(LB[:12], why, "the head this host last read is named")
        self.assertEqual(nxt, f"glaeda-gh land o/r#1 --match-head-commit {LB}")
        # Nothing else is refused: the pin is the head, a pin of a commit the cache has not seen (the normal
        # pinned land, whose sha shares no prefix), a short pin the caller never extended, or no cached head.
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, LB, LB))
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, LA, LB))
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, LB[:12], LB))
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, invented, ""))
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, "", LB))
        # The bound on the claim: a shared prefix shorter than the one a human reads off a line proves nothing.
        self.assertIsNone(gg.land_pin_extends_head_refusal("o/r", 1, LB[:4] + "0" * 36, LB))

        # The cached head it judges against: only an open PR read inside the bound says one.
        now = time.time()
        self.store_pr(land_pr(LB), at=now)
        self.assertEqual(gg.land_cached_head(self.KEY, gg.LAND_PIN_BEHIND_AGE), LB)
        for data, at, why in ((land_pr(LB), now - gg.LAND_PIN_BEHIND_AGE - 1, "older than the bound"),
                              (land_pr(LB), now + 600, "stamped in the future"),
                              (land_pr(LB, state="MERGED"), now, "not open"),
                              ({"state": "OPEN"}, now, "no head stored")):
            self.store_pr(data, at=at)
            self.assertEqual(gg.land_cached_head(self.KEY, gg.LAND_PIN_BEHIND_AGE), "", why)
        (gg.cache_dir() / gg.file_name(self.KEY)).unlink()
        self.assertEqual(gg.land_cached_head(self.KEY, gg.LAND_PIN_BEHIND_AGE), "", "no read at all")

    def test_land_refuses_a_pin_that_extends_the_cached_head_by_hand(self):
        """The request answers it, like the ancestor case: nothing queued, nothing read from GitHub, and the step
        is the same command with the whole head. A row pinned to a sha no commit has waits out a head that cannot
        come, which is the slowest way for a typed-out abbreviation to be found."""
        invented = LB[:12] + "0" * 28
        self.pr(LB)
        self.store_pr(land_pr(LB))
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("nothing is queued")), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, invented)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"]), (gg.EXIT_FAIL, False, "land_pin_invented"))
        self.assertIn(LB, doc["next"])
        self.assertIn("land_pin_invented", gg.LAND_REQUEST_REFUSED)

    def test_an_all_zero_pin_is_refused_before_this_host_reads_any_head(self):
        """The one invented pin no head is needed to judge. The invented-pin check above judges a pin against a head
        this host holds, and is handed "" when it holds none: no cached read inside LAND_PIN_BEHIND_AGE and a caller
        outside a checkout of the repository. 2026-11-25, efficiency-standing-lane, run from a directory that is a
        checkout of neither repository: `land ...#26325 --sha` + 40 zeros was accepted at exit 0 and answered
        "requested; the daemon takes it next tick" -- and it replaced that row's own correct pin. git's null object id
        is a commit in no repository at all, so this costs one string test and no read of any kind."""
        for zeros in ("0" * 40, "0" * 12, "0" * 7):
            said = gg.land_pin_null_refusal("o/r", 1, zeros)
            self.assertIsNotNone(said, zeros)
            why, nxt = said
            self.assertIn("is all zeros", why)
            self.assertIn("names no commit in any repository", why)
            self.assertIn("never a sha filled in or padded by hand", why)
            self.assertIn("glaeda-gh land o/r#1 --sha HEAD", nxt)
            self.assertIn("glaeda-gh gh api repos/o/r/pulls/1 --jq .head.sha", nxt)
        # Nothing else: no pin, a real one, a short one, and a hand-padded one that still carries its head's prefix
        # (land_pin_extends_head_refusal owns that, against a head, and said nothing when it had none).
        for pin, why in (("", "no pin"), (LA, "a real head"), (LB[:12], "a short pin"),
                         (LB[:12] + "0" * 28, "zeros after a real prefix"), ("0" * 39 + "1", "not all zeros")):
            self.assertIsNone(gg.land_pin_null_refusal("o/r", 1, pin), why)
        # End to end: the first pin answer of all, before the draft read and before check_land_pin's two git calls.
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "land_cached_head", side_effect=AssertionError("no cache read")), \
                mock.patch.object(gg, "land_pin_local_head", side_effect=AssertionError("no git call")), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("nothing is queued")), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, "0" * 40)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"], doc["key"]), (gg.EXIT_FAIL, False, "land_pin_null", self.KEY))
        self.assertIn("--sha HEAD", doc["next"])
        self.assertIn("land_pin_null", gg.LAND_REQUEST_REFUSED)  # a forwarded request carries it back unchanged

    def test_a_pin_no_head_here_could_check_says_the_check_did_not_run(self):
        """The queue still takes the pin -- it must, since the head may be newer than anything read here -- but the
        caller is told the check did not run. Before this, the same one line answered a checked pin and an unchecked
        one, so there was nothing to tell them apart by: 2026-11-25 a hand-padded 40-hex pin and an all-zero pin were
        both accepted from a directory that was no checkout of the target, each costing a daemon tick, a park and a
        re-request."""
        note = gg.land_pin_unchecked_note("o/r", 1, LA)
        self.assertIn(f"--match-head-commit {LA[:12]} was taken as given", note)
        self.assertIn("no read of o/r#1 inside a day", note)
        self.assertIn("the directory you ran in is no checkout of o/r", note)
        self.assertIn("parks the row (pin_wait)", note)
        self.assertIn("next: glaeda-gh land o/r#1 --sha HEAD", note)
        self.assertEqual(gg.land_pin_unchecked_note("o/r", 1, ""), "", "an unpinned request checks nothing")
        # End to end: no cached read of the PR and no checkout of it here, so the invented-pin check was handed ""
        # and judged nothing. The request is queued, and says so.
        self.pr(LA)
        said: list[str] = []
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: ""), \
                mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "say_waiting", side_effect=said.append), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, False, LA)
        self.assertEqual(rc, gg.EXIT_OK)
        self.assertIn("requested; the daemon takes it next tick", out.getvalue())
        self.assertTrue(any("was taken as given" in line for line in said), said)
        self.assertTrue(any("--sha HEAD pins whatever the head is, checked here" in line for line in said), said)
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: ""), \
                mock.patch.object(gg, "daemon_running", return_value=True), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, LA)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["state"]), (gg.EXIT_OK, True, "requested"))
        self.assertIn("was taken as given", doc["pinUnchecked"])
        self.assertNotIn("pinReplaced", doc)
        # A pin this host *can* check says nothing extra: the cached read is the head it was judged against.
        self.store_pr(land_pr(LA))
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: ""), \
                mock.patch.object(gg, "daemon_running", return_value=True), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, LA)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"]), (gg.EXIT_OK, True))
        self.assertNotIn("pinUnchecked", doc)

    def test_a_re_pin_names_the_live_pin_it_replaced(self):
        """A re-pin is ordinary -- the head moved and the requester pinned the new one -- so it is not refused. What
        was missing is the sha it replaced, which is the only way its requester can put the row back. The row this
        session landed on 2026-11-25 was its own, correctly pinned, and one probe request overwrote that pin with no
        word of it; the correct pin had to be read back from GitHub. land_pin_already_followed answers only the case
        the queue itself moved the pin, and only for the same requester, so every other re-pin was silent."""
        live = {"state": "waiting", "pinSha": LB, "requester": "host/lane", "history": []}
        self.assertEqual(gg.land_pin_replaces_note(live, LA, "host/lane"), LB)
        for entry, why in ((None, "no row at all"),
                           ({}, "an empty row"),
                           ({**live, "state": "merged"}, "a merged row"),
                           ({**live, "state": "stopped"}, "a stopped row"),
                           ({**live, "pinSha": ""}, "an unpinned row"),
                           ({**live, "pinSha": "nope"}, "a pin that is no sha"),
                           ({**live, "pinSha": LA}, "the same pin again"),
                           ({**live, "requester": "other/lane"}, "another session's row")):
            self.assertEqual(gg.land_pin_replaces_note(entry, LA, "host/lane"), "", why)
        self.assertEqual(gg.land_pin_replaces_note(live, LB[:12], "host/lane"), "",
                         "a short pin of the sha the row already holds")
        self.assertEqual(gg.land_pin_replaces_note(live, "", "host/lane"), "", "an unpinned request")
        # End to end, with a cached head so the pin is checked and only the replacement is new.
        gg.write_json(gg.LandQueue.entries_dir() / gg.file_name(self.KEY),
                      {"key": self.KEY, "repo": "o/r", "number": 1, "state": "waiting", "pinSha": LB,
                       "requester": "host/lane", "history": []})
        self.pr(LA)
        self.store_pr(land_pr(LA))
        said: list[str] = []
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: ""), \
                mock.patch.object(gg, "daemon_running", return_value=True), \
                mock.patch.object(gg, "run_bounded", side_effect=lambda argv, *a, **k:
                                  gg.subprocess.CompletedProcess(argv, 1, "", "")), \
                mock.patch.object(gg, "say_waiting", side_effect=said.append):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, False, LA)
        self.assertEqual(rc, gg.EXIT_OK)  # not a refusal: a re-pin after a head move is the normal case
        self.assertTrue(any(f"which was queued pinned {LB}" in line for line in said), said)
        self.assertTrue(any(f"next: glaeda-gh land o/r#1 --match-head-commit {LB} puts it back" in line for line in said), said)


    def test_the_moved_pin_refusal_shows_the_hex_at_which_the_two_shas_differ(self):
        """Every sha in this script is abbreviated to 12 hex, which is a name. In the one message whose whole subject
        is that the head is not the pin, a name is not enough: 2026-11-22 on this host, landing
        teamleaderleo/glaeda#2558 pinned to its own head with a typed tail, the queue printed "the head is
        f40f866c791c, not the --sha f40f866c791c it was queued for" -- two identical strings, so the reader could
        not see which sha to pin, and the row's own next step was the only usable part of it. The clause now widens
        to the first hex at which they differ."""
        head, pin = "f40f866c791cf6faad60726b7a48c27236a640fc", "f40f866c791c1e5e2d4ba3dad6a8f5b09ae3b8f6"
        said = gg.land_moved_clause(head, pin)
        self.assertEqual(said, f"the head is {head[:13]}, not the --sha {pin[:13]} it was queued for")
        self.assertNotEqual(head[:13], pin[:13], "the two shas the clause names differ in the text it prints")
        # 12 hex when 12 already differ (every other pair): the width is a floor, not a change of habit.
        self.assertEqual(gg.land_moved_clause(LB, LA), f"the head is {LB[:12]}, not the --sha {LA[:12]} it was "
                                                       "queued for")
        # A pin shorter than the head reads the same, and never past the whole sha of either.
        self.assertEqual(gg.land_moved_clause(head, pin[:13]), gg.land_moved_clause(head, pin))
        self.assertIn(head, gg.land_moved_clause(head, head[:39] + "0"))
        # NOTE rides the head, for the hand-off refusal, which read it somewhere the others did not.
        self.assertEqual(gg.land_moved_clause(LB, LA, " (the broker read it from GitHub)"),
                         f"the head is {LB[:12]} (the broker read it from GitHub), not the --sha {LA[:12]} it was "
                         "queued for")

    def test_a_hand_written_pin_is_judged_against_the_callers_own_checkout_when_the_cache_has_none(self):
        """The invented-pin check judges a pin against this host's cached head, and a PR opened minutes ago has no
        cached read: teamleaderleo/glaeda#2558's request was judged `why=no_data` and accepted, and the row took a
        tick and ~95 s to stop head_moved. That is exactly when a pin is written out by hand -- right after the push
        that opened the PR. The checkout the caller ran in holds that head already, for one local git call.

        Only this check may take it. The ancestor check may not: a checkout routinely holds commits the PR's head
        does not have yet, so a pin that is an ancestor of this head is the ordinary case."""
        head = "f40f866c791cf6faad60726b7a48c27236a640fc"
        with mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"):
            self.assertEqual(gg.land_pin_local_head("o/r", lambda rest: head.upper()), head)
            self.assertEqual(gg.land_pin_local_head("O/R", lambda rest: head), head, "the repo matches by case")
            self.assertEqual(gg.land_pin_local_head("o/other", lambda rest: head), "", "another repo's checkout")
            self.assertEqual(gg.land_pin_local_head("o/r", lambda rest: "nope"), "", "not a sha")
            self.assertEqual(gg.land_pin_local_head("o/r", lambda rest: None), "", "git could not answer")
        with mock.patch.object(gg, "cwd_repo", lambda *a, **k: ""):
            self.assertEqual(gg.land_pin_local_head("o/r", lambda rest: head), "", "not a checkout at all")
        # The refusal names where the head came from, because it is not the cache this time.
        said = gg.land_pin_extends_head_refusal("o/r", 1, head[:12] + "1e5e2d4ba3dad6a8f5b09ae3b8f6", head,
                                                "the HEAD of this checkout of o/r")
        self.assertIsNotNone(said)
        self.assertIn(f"The whole head, the HEAD of this checkout of o/r, is {head}", said[0])
        self.assertEqual(said[1], f"glaeda-gh land o/r#1 --match-head-commit {head}")

    def test_land_takes_the_checkouts_head_for_an_unread_pr_and_refuses_the_typed_pin(self):
        """End to end, the case measured: no cached read of the PR, a pin that is the checkout's own head with a
        typed tail. Nothing is queued and nothing is read from GitHub."""
        head = "f40f866c791cf6faad60726b7a48c27236a640fc"
        invented = head[:12] + "1e5e2d4ba3dad6a8f5b09ae3b8f6"
        self.pr(head)  # GitHub would say this head, but no read of it was ever cached
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"), \
                mock.patch.object(gg, "run_bounded", side_effect=lambda argv, *a, **k:
                                  gg.subprocess.CompletedProcess(argv, 0, head, "")), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("nothing is queued")), \
                contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, invented)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"]), (gg.EXIT_FAIL, False, "land_pin_invented"))
        self.assertIn(f"this checkout of o/r, is {head}", doc["reason"])
        self.assertEqual(doc["next"], f"glaeda-gh land o/r#1 --match-head-commit {head}")

    def test_land_refuses_a_pin_behind_the_head_and_names_the_head_to_pin(self):
        """The request answers it: nothing is queued, nothing is read from GitHub, and the step is the same command
        with the head the cache holds."""
        def bounded(argv: list[str], timeout: float | None = None, **kw: object) -> gg.subprocess.CompletedProcess:
            self.assertEqual(argv[0], "git")
            rest = argv[1:]
            ok = rest[:2] == ["cat-file", "-e"] or rest == ["merge-base", "--is-ancestor", LA, LB]
            return gg.subprocess.CompletedProcess(argv, 0 if ok else 1, "", "")
        self.pr(LB)
        self.store_pr(land_pr(LB))
        said: list[str] = []
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"), \
                mock.patch.object(gg, "run_bounded", side_effect=bounded), \
                mock.patch.object(gg, "say_waiting", side_effect=said.append), \
                mock.patch.object(gg, "land_request", side_effect=AssertionError("nothing is queued")):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, False, LA)
        self.assertEqual(rc, gg.EXIT_FAIL)
        self.assertIn(f"is an ancestor of o/r#1's head {LB[:12]}", said[0])
        self.assertIn(f"next: glaeda-gh land o/r#1 --match-head-commit {LB}", said[0])
        self.assertEqual(list(gg.LandQueue.requests_dir().glob("*.json"))
                         if gg.LandQueue.requests_dir().is_dir() else [], [])
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"), \
                mock.patch.object(gg, "run_bounded", side_effect=bounded), contextlib.redirect_stdout(out):
            rc = gg.cmd_land("o/r#1", [], "host/lane", 0, True, LA)
        doc = json.loads(out.getvalue())
        self.assertEqual((rc, doc["ok"], doc["code"], doc["key"]),
                         (gg.EXIT_FAIL, False, "land_pin_behind", self.KEY))
        self.assertIn("land_pin_behind", gg.LAND_REQUEST_REFUSED)  # a forwarded request carries it back unchanged
        # The pinned land of the head itself is queued as always: the check answers only the ancestor case.
        out = io.StringIO()
        with mock.patch.object(gg, "land_config", return_value={"landJudge": self.w.mh}), \
                mock.patch.object(gg, "land_executor", return_value=None), \
                mock.patch.object(gg, "cwd_repo", lambda *a, **k: "o/r"), \
                mock.patch.object(gg, "run_bounded", side_effect=bounded), contextlib.redirect_stdout(out):
            gg.cmd_land("o/r#1", [], "host/lane", 0, True, LB)
        doc = json.loads(out.getvalue())
        self.assertNotIn("land_pin_behind", json.dumps(doc))
        self.assertEqual(doc["key"], self.KEY)
        self.assertTrue(doc.get("request"), doc)  # queued (the daemon is not running in this test, hence no merge)

    CONFLICT_REFUSAL = ('gh: merge conflict between base and head (HTTP 422) {"message":"merge conflict between base '
                        'and head","documentation_url":"https://docs.github.com/rest/pulls/pulls#update-a-pull-'
                        'request-branch","status":"422"}')

    def union_origin(self, attrs: str = "goals/*.md merge=union\n", path: str = "goals/x.md",
                     main_path: str = "") -> tuple[str, str]:
        """A real origin for o/r (LAND_UNION_URL pointed at it): main and the PR's branch lane/x each appended one
        line at the end of PATH, so git's line merge conflicts there; ATTRS is main's .gitattributes. With MAIN_PATH,
        main appends to that file instead, so git merges the two cleanly. (head, base)."""
        origin = Path(self.tmp.name) / "origin"
        env = {"PATH": os.environ.get("PATH", ""), "HOME": self.tmp.name, "GIT_CONFIG_NOSYSTEM": "1",
               "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t", "GIT_COMMITTER_NAME": "t",
               "GIT_COMMITTER_EMAIL": "t@t"}

        def git(*args: str) -> str:
            return subprocess.run(["git", "-C", os.fspath(origin), *args], check=True, capture_output=True,
                                  text=True, env=env).stdout.strip()
        origin.mkdir()
        git("init", "-q", "-b", "main")
        git("config", "uploadpack.allowFilter", "true")
        git("config", "receive.denyCurrentBranch", "ignore")
        (origin / ".gitattributes").write_text(attrs)
        (origin / path).parent.mkdir(parents=True, exist_ok=True)
        (origin / path).write_text("- 10:00Z goal set\n")
        git("add", "-A")
        git("commit", "-qm", "init")
        git("checkout", "-qb", "lane/x")
        with open(origin / path, "a") as f:
            f.write("- 11:00Z the lane's line\n")
        git("commit", "-qam", "the lane appends")
        head = git("rev-parse", "HEAD")
        git("checkout", "-q", "main")
        (origin / (main_path or path)).parent.mkdir(parents=True, exist_ok=True)
        with open(origin / (main_path or path), "a") as f:
            f.write("- 11:05Z another PR's line, landed first\n")
        git("add", "-A")
        git("commit", "-qam", "main appends")
        base = git("rev-parse", "HEAD")
        url = mock.patch.object(gg, "LAND_UNION_URL", f"file://{origin}")
        url.start()
        self.addCleanup(url.stop)
        self.w.real_git = True
        self.origin_git = git
        return head, base

    def union_conflict_tick(self, head: str, owners: frozenset = frozenset({"o"})) -> dict:
        """HEAD landed pinned, judged stale_green (update-branch named), and GitHub's update-branch refused it for the
        conflict, as it does whatever .gitattributes says. OWNERS stands in for LAND_MERGE_OWNERS (the test repo is
        o/r)."""
        patch = mock.patch.object(gg, "LAND_MERGE_OWNERS", owners)
        patch.start()
        self.addCleanup(patch.stop)
        data = {**land_pr(head), "headRefName": "lane/x", "baseRefName": "main"}
        self.w.set_pr(self.KEY, data, self.t)
        gg.land_request("land", "o/r#1", [], "host/lane", sha=head)
        self.w.gh_rc["update"] = 1
        self.w.gh_err["update"] = self.CONFLICT_REFUSAL
        self.w.answers.append(refusal("stale_green", head, {"kind": "update_branch", "expected_head_sha": head}))
        return self.tick()

    def test_a_conflict_only_in_union_files_is_merged_here_and_the_pinned_land_goes_on(self):
        """manaflow-ai/cmuxterm-hq#17917, 2026-11-21/22: its pinned land stopped update_branch_conflict three times on
        goals/hot-verify-share.md, which .gitattributes marks merge=union, each hand-resolved by merging main: GitHub's
        update-branch ignores .gitattributes. The queue now makes that merge itself and the land goes on."""
        head, base = self.union_origin()
        e = self.union_conflict_tick(head)
        self.assertEqual(len([c for c in self.w.gh_calls("api") if "update-branch" in " ".join(c)]), 1)
        self.assertEqual((e["state"], e["wait"]["kind"], e["wait"]["before"]), ("waiting", "head_change", head),
                         e.get("stop"))
        merged = self.origin_git("rev-parse", "refs/heads/lane/x")
        self.assertNotEqual(merged, head)
        self.assertEqual(self.origin_git("rev-list", "--parents", "-n1", merged).split()[1:], [head, base])
        self.assertEqual(self.origin_git("show", f"{merged}:goals/x.md"),
                         "- 10:00Z goal set\n- 11:00Z the lane's line\n- 11:05Z another PR's line, landed first")
        self.assertEqual(self.origin_git("diff", "--name-only", base, merged), "goals/x.md")  # the PR's own diff only
        done = [h for h in e["history"] if h["event"] == "union_merged"]
        self.assertEqual([(h["head"], h["merge"], h["paths"]) for h in done], [(head[:12], merged[:12], "goals/x.md")])
        # GitHub shows the merge as the new head: the pin follows it (first parent the pin) and the land merges it.
        self.w.set_pr(self.KEY, {**land_pr(merged, parent=head), "headRefName": "lane/x", "baseRefName": "main"},
                      self.t)
        self.w.answers.append(ok_answer(merged))
        e = self.tick()
        self.assertEqual((e["state"], e.get("stop"), e["pinSha"]), ("merged", None, merged))
        self.assert_merged_at(merged)

    def test_a_merge_step_conflict_only_in_union_files_is_merged_here_and_the_pinned_land_goes_on(self):
        """cmuxterm-hq, 2026-11-23: findings PRs #20862 and #20882 that only appended a line to
        docs/findings/CLAIMED.md (merge=union) stopped merge_conflict three times each: land_judge said merge, the
        base moved, and GitHub's merge refused the conflict it ignores .gitattributes to see. The merge step's
        refusal takes the same base merge as update-branch's, once per head, and the land goes on."""
        head, base = self.union_origin()
        patch = mock.patch.object(gg, "LAND_MERGE_OWNERS", frozenset({"o"}))
        patch.start()
        self.addCleanup(patch.stop)
        self.w.set_pr(self.KEY, {**land_pr(head), "headRefName": "lane/x", "baseRefName": "main"}, self.t)
        gg.land_request("land", "o/r#1", [], "host/lane", sha=head)
        self.w.gh_rc["merge"] = 1
        self.w.gh_err["merge"] = "GraphQL: Pull Request has merge conflicts (mergePullRequest)"
        self.w.answers.append(ok_answer(head))
        e = self.tick()
        self.assertEqual((e["state"], e["wait"]["kind"], e["wait"]["before"]), ("waiting", "head_change", head),
                         e.get("stop"))
        merged = self.origin_git("rev-parse", "refs/heads/lane/x")
        self.assertEqual(self.origin_git("rev-list", "--parents", "-n1", merged).split()[1:], [head, base])
        self.assertEqual(self.origin_git("show", f"{merged}:goals/x.md"),
                         "- 10:00Z goal set\n- 11:00Z the lane's line\n- 11:05Z another PR's line, landed first")
        self.assertEqual([h["event"] for h in e["history"] if h["event"] in ("step_refused", "union_merged")],
                         ["step_refused", "union_merged"])
        self.w.gh_rc["merge"] = 0
        self.w.set_pr(self.KEY, {**land_pr(merged, parent=head), "headRefName": "lane/x", "baseRefName": "main"},
                      self.t)
        self.w.answers.append(ok_answer(merged))
        e = self.tick()
        self.assertEqual((e["state"], e.get("stop"), e["pinSha"], e["mergeSha"]), ("merged", None, merged, "f" * 40))
        self.assertEqual([c[-1] for c in self.w.gh_calls("pr", "merge")], [head, merged])  # refused, then merged

    def test_a_true_merge_step_conflict_stops_once_naming_the_merge(self):
        """A merge-step conflict git cannot settle (no merge=union on the path) still stops, as merge_conflict, with
        the reason saying why it was not merged here, and nothing is pushed."""
        head, _ = self.union_origin(attrs="")
        patch = mock.patch.object(gg, "LAND_MERGE_OWNERS", frozenset({"o"}))
        patch.start()
        self.addCleanup(patch.stop)
        self.w.set_pr(self.KEY, {**land_pr(head), "headRefName": "lane/x", "baseRefName": "main"}, self.t)
        gg.land_request("land", "o/r#1", [], "host/lane", sha=head)
        self.w.gh_rc["merge"] = 1
        self.w.gh_err["merge"] = "GraphQL: Pull Request has merge conflicts (mergePullRequest)"
        self.w.answers.append(ok_answer(head))
        e = self.tick()
        self.assertEqual((e["state"], e["stop"]["code"]), ("stopped", "merge_conflict"))
        self.assertIn("not merged here", e["stop"]["reason"])
        self.assertIn("goals/x.md", e["stop"]["reason"])
        self.assertEqual(self.origin_git("rev-parse", "refs/heads/lane/x"), head)

    def stacked_origin(self, squash: bool = True, conflict: bool = False) -> dict[str, str]:
        """A real origin for o/r (LAND_UNION_URL pointed at it), as manaflow-ai/cmux-quillet-look stood on 2026-11-22:
        #2 (stack/a onto main) merged, squashed unless SQUASH is False (a merge commit); #1 (stack/b) still onto
        stack/a with one commit of its own; refs/pull/2/head kept as GitHub keeps it. CONFLICT: main changed #1's
        line too after #2 merged. The shas by name: main, a (#2's head), b (#1's head)."""
        origin = Path(self.tmp.name) / "stacked-origin"
        env = {"PATH": os.environ.get("PATH", ""), "HOME": self.tmp.name, "GIT_CONFIG_NOSYSTEM": "1",
               "GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t", "GIT_COMMITTER_NAME": "t",
               "GIT_COMMITTER_EMAIL": "t@t"}

        def git(*args: str, **more: str) -> str:
            return subprocess.run(["git", "-C", os.fspath(origin), *args], check=True, capture_output=True,
                                  text=True, env={**env, **more}).stdout.strip()
        origin.mkdir()
        git("init", "-q", "-b", "main")
        git("config", "uploadpack.allowFilter", "true")
        git("config", "uploadpack.allowAnySHA1InWant", "true")
        git("config", "receive.denyCurrentBranch", "ignore")
        (origin / "a.txt").write_text("one\n")
        (origin / "b.txt").write_text("one\n")
        git("add", "-A")
        git("commit", "-qm", "init")
        git("checkout", "-qb", "stack/a")
        (origin / "a.txt").write_text("one\ntwo\n")
        git("commit", "-qam", "#2's change")
        a = git("rev-parse", "HEAD")
        git("update-ref", "refs/pull/2/head", a)
        git("checkout", "-qb", "stack/b")
        (origin / "b.txt").write_text("one\nthe lane's line\n")
        git("commit", "-qam", "#1's own change", GIT_AUTHOR_NAME="Lane Author", GIT_AUTHOR_EMAIL="lane@x",
            GIT_AUTHOR_DATE="1700000000 +0000")
        b = git("rev-parse", "HEAD")
        git("checkout", "-q", "main")
        if squash:
            git("merge", "-q", "--squash", "stack/a")
            git("commit", "-qm", "#2's change (#2)")
        else:
            git("merge", "-q", "--no-ff", "-m", "Merge #2", "stack/a")
        if conflict:
            (origin / "b.txt").write_text("one\nmain's own line\n")
            git("commit", "-qam", "main changes b.txt")
        main = git("rev-parse", "HEAD")
        url = mock.patch.object(gg, "LAND_UNION_URL", f"file://{origin}")
        url.start()
        self.addCleanup(url.stop)
        self.w.real_git = True
        self.origin_git = git
        self.w.api["repos/o/r/pulls?head=o:stack%2Fa"] = json.dumps(
            [{"number": 2, "merged_at": "2026-11-22T18:00:00Z", "sha": a}])
        return {"main": main, "a": a, "b": b}

    def stacked_tick(self, head: str) -> dict:
        """#1 landed pinned at HEAD, onto stack/a, and land_judge refused it stacked_base naming the retarget."""
        owners = mock.patch.object(gg, "LAND_MERGE_OWNERS", frozenset({"o"}))  # the test repo is o/r
        owners.start()
        self.addCleanup(owners.stop)
        self.w.set_pr(self.KEY, {**land_pr(head), "headRefName": "stack/b", "baseRefName": "stack/a"}, self.t)
        gg.land_request("land", "o/r#1", [], "host/lane", sha=head)
        self.w.answers.append(refusal("stacked_base", head, {"kind": "retarget", "base": "main"},
                                      "gh pr edit 1 -R o/r --base main"))
        return self.tick()

    def retargets(self) -> list[list[str]]:
        return [c for c in self.w.gh_calls() if c[:4] == ["api", "-X", "PATCH", "repos/o/r/pulls/1"]
                or c[:2] == ["pr", "edit"]]

    def test_a_stacked_pr_whose_base_squash_merged_is_rebased_off_it_then_retargeted(self):
        """manaflow-ai/cmux-quillet-look#3, 2026-11-22 18:05Z: #2 (its base's PR) squash-merged; the land stopped
        "stacked_base: 3 identical refusals in a row" (each `gh pr edit --base` refused for classic projects), and
        retargeted by hand it read CONFLICTING until a person rebased it --onto main off #2's head. The queue now
        rebases its own commit off #2's head, pushes it leased at the judged head, retargets it through REST, and the
        pin follows the head it made."""
        sha = self.stacked_origin()
        e = self.stacked_tick(sha["b"])
        new = self.origin_git("rev-parse", "refs/heads/stack/b")
        self.assertNotEqual(new, sha["b"], e.get("stop"))
        self.assertEqual(self.origin_git("rev-list", "--parents", "-n1", new).split()[1:], [sha["main"]])
        self.assertEqual(self.origin_git("diff", "--name-only", sha["main"], new), "b.txt")  # its own diff only
        self.assertEqual(self.origin_git("show", f"{new}:b.txt"), "one\nthe lane's line")
        self.assertEqual(self.origin_git("log", "-1", "--format=%an <%ae> %at %s", new),
                         "Lane Author <lane@x> 1700000000 #1's own change")
        self.assertEqual(self.retargets(), [["api", "-X", "PATCH", "repos/o/r/pulls/1", "-f", "base=main", "--jq",
                                             ".base.ref"]])
        done = [h for h in e["history"] if h["event"] == "stacked_rebased"]
        self.assertEqual([(h["head"], h["rebased"], h["after"], h["pull"], h["commits"]) for h in done],
                         [(sha["b"][:12], new[:12], sha["a"][:12], 2, 1)])
        self.assertEqual(e["pinSha"], new)
        self.assertIn(f"{sha['b'][:12]} -> {new[:12]}", e["stackedRebase"])
        # GitHub shows it onto main at the new head: judged ok and merged pinned, the merge notice saying the rebase
        self.w.set_pr(self.KEY, {**land_pr(new), "headRefName": "stack/b", "baseRefName": "main"}, self.t)
        self.w.answers.append(ok_answer(new))
        e = self.tick()
        self.assertEqual((e["state"], e.get("stop")), ("merged", None))
        self.assert_merged_at(new)
        said = " ".join(" ".join(c) for c in self.w.sent())
        self.assertIn("rebased its 1 own commit after #2's head", said)

    def test_a_stacked_pr_whose_base_merged_with_a_merge_commit_is_only_retargeted(self):
        sha = self.stacked_origin(squash=False)
        e = self.stacked_tick(sha["b"])
        self.assertEqual(self.origin_git("rev-parse", "refs/heads/stack/b"), sha["b"])  # nothing pushed
        self.assertEqual(len(self.retargets()), 1, e.get("stop"))
        self.assertEqual([h for h in e["history"] if h["event"] == "stacked_rebased"], [])
        self.assertEqual(e["pinSha"], sha["b"])

    def test_a_stacked_rebase_that_conflicts_stops_pushes_nothing_and_names_the_hand_step(self):
        sha = self.stacked_origin(conflict=True)
        e = self.stacked_tick(sha["b"])
        self.assertEqual((e["state"], e["stop"]["code"]), ("stopped", "retarget_conflict"))
        self.assertIn(f"conflicts at {sha['b'][:12]} in b.txt", e["stop"]["reason"])
        self.assertIn("git rebase --onto origin/main <the base PR's last head>", e["stop"]["next"])
        self.assertEqual(self.origin_git("rev-parse", "refs/heads/stack/b"), sha["b"])
        self.assertEqual(self.retargets(), [])  # the base is not changed either

    def test_a_stacked_rebase_whose_read_fails_is_a_refused_step_not_a_bare_retarget(self):
        """A failure decides nothing: the base is not changed (which would leave it conflicting with no stacked_base
        refusal to come back to), the step backs off and the next judgment names it again."""
        sha = self.stacked_origin()
        self.w.api["repos/o/r/pulls?head=o:stack%2Fa"] = None
        e = self.stacked_tick(sha["b"])
        self.assertEqual(self.retargets(), [])
        self.assertEqual(e["state"], "waiting", e.get("stop"))
        self.assertEqual([h["event"] for h in e["history"] if h["event"].startswith("stacked_rebase")],
                         ["stacked_rebase_failed"])

    def test_a_stacked_pr_of_an_owner_this_queue_never_pushes_to_is_only_retargeted(self):
        sha = self.stacked_origin()
        with mock.patch.object(gg, "LAND_MERGE_OWNERS", frozenset({"manaflow-ai"})):
            self.w.set_pr(self.KEY, {**land_pr(sha["b"]), "headRefName": "stack/b", "baseRefName": "stack/a"}, self.t)
            gg.land_request("land", "o/r#1", [], "host/lane", sha=sha["b"])
            self.w.answers.append(refusal("stacked_base", sha["b"], {"kind": "retarget", "base": "main"}))
