    def no_data_unreadable(self, n: int) -> None:
        for _ in range(n):
            self.w.answers.append((3, {"ok": False, "code": "unreadable", "head": LA,
                                       "reason": "land-judge: refused: unreadable: GitHub timed out",
                                       "next": "", "action": {"v": 1, "kind": "retry", "after_s": 120}}))

    def no_data_judgments(self, seconds: float, step: float = 10.0) -> list[float]:
        """Run the queue SECONDS with no cached copy of the PR; when each live judgment ran (seconds from the start)."""
        start, at = self.t, []
        while self.t - start < seconds:
            before = len(self.w.judgments())
            self.tick(step)
            if len(self.w.judgments()) > before:
                at.append(round(self.t - start))
        return at

    def test_a_pr_the_daemon_cannot_read_backs_off_between_no_data_judgments(self):
        """Queue host, 2026-11-22 14:37-15:37Z: 118 unreadable judgments why=no_data, each ~177 s of a worker, because
        the no-data path judged again LAND_NO_DATA_AFTER after each answer and never read its retry's wake. The
        judgments now follow the retry's backoff (doubling to LAND_RETRY_MAX), still at least every LAND_RETRY_MAX."""
        self.nudge_reads = False
        self.land()
        self.no_data_unreadable(40)
        at = self.no_data_judgments(4 * 3600)
        gaps = [b - a for a, b in zip(at, at[1:])]
        # before: one every 130 s (40 in the first 87 min); now 130, 260, 500, 980, 1940 s, then every 1800 s: 11
        self.assertLessEqual(len(at), 12, at)
        self.assertTrue(all(b >= a for a, b in zip(gaps, gaps[1:])), gaps)  # never faster than the one before
        self.assertLessEqual(max(gaps), gg.LAND_RETRY_MAX + 20, gaps)  # never stranded: bounded
        self.assertEqual(self.q.entries[self.KEY]["state"], "waiting")

    def test_the_daemons_first_copy_after_a_no_data_judgment_is_judged_at_once(self):
        """The backoff waits for nothing but its wake or the PR's first copy: the read the daemon could not do arrives
        and the land is judged on it that pass, pinned to the head it shows."""
        self.nudge_reads = False
        self.land()
        self.no_data_unreadable(3)
        at = self.no_data_judgments(600)
        self.assertEqual(len(at), 3, at)  # LAND_NO_DATA_AFTER, then the retry's 120 s and 240 s; the next 480 s on
        e = self.q.entries[self.KEY]
        self.assertGreater(e["wakeAt"], self.t + 60)
        self.pr(LA)
        self.w.answers.insert(0, ok_answer(LA))
        e = self.tick(2)
        self.assertEqual(self.w.judgments()[-1][-3:], ["--sha", LA, "--json"])
        self.assertEqual(e["state"], "merged")
        self.assertIn("data_seen", [h.get("why") for h in e["history"]])

    def test_a_full_pin_the_cache_contradicts_still_stops(self):
        """The trust is in the pin, not over a read: a cached head that is not the pin still stops head_moved."""
        self.pr(LA)
        self.w.api[f"repos/o/r/commits/{LA}"] = json.dumps([LC])  # the cache read no parents: one read says a push
        gg.land_request("land", "o/r#1", [], "host/lane", sha=LB)
        self.tick(1)
        e = self.tick(30)  # a worker read the head's parents first
        self.assertEqual(self.w.gh_calls("pr", "merge"), [])
        self.assertEqual(e.get("state"), "stopped")
        self.assertIn("head_moved", json.dumps(e))

    # -- due rows starved by the login's latch (huge-blue, 2026-11-18 17:18-19:53Z)

    def stuck(self, n: int, wake_ago: float, judged_ago: float | None = None, kind: str = "retry",
              seen: str | None = None, state: str = "waiting", after: list[str] | None = None) -> str:
        """An open entry as huge-blue held them: KIND waiting, its wake WAKE_AGO s past (negative: ahead), judged
        JUDGED_AGO s ago ("judged code=unreadable step=retry" a minute before the wake)."""
        key = f"pr:o/r#{n}"
        head = f"{n:x}".rjust(40, "a")
        self.w.set_pr(key, land_pr(head), self.t - 600)
        e = {"key": key, "repo": "o/r", "number": n, "created": self.t - 90000, "history": [], "mergeSha": "",
             "reviewed": [], "state": state, "wait": {"kind": kind, "sha": head} if state == "waiting" else None,
             "wakeAt": self.t - wake_ago if state == "waiting" else None, "head": head, "seenHead": head,
             "seen": seen if seen is not None else gg.land_fingerprint(self.w.cache[key]),
             "explain": {"at": self.t - (judged_ago if judged_ago is not None else wake_ago + 60), "ok": False,
                         "code": "unreadable", "head": head, "action": {"kind": kind}},
             "requester": f"host/lane{n}", "requesterFrom": "", "queuedBy": "", "gen": 1, "after": after or []}
        self.q.entries[key] = e
        self.q.save(e)
        return key

    def retries(self, n: int) -> None:
        for _ in range(n):
            self.w.answers.append((3, {"ok": False, "code": "unreadable", "reason": "land-judge: refused: unreadable",
                                       "next": "", "action": {"v": 1, "kind": "retry", "after_s": 120}}))

    def explained(self) -> list[str]:
        return [c[4] for c in self.w.explains()]

    def test_due_rows_go_oldest_wake_first_ahead_of_rows_judged_only_for_a_change(self):
        """No latch at all. Due rows (retry, woke 2-4 h ago) are judged before an entry judged only because its cache
        changed (a wait on its checks, its wake ahead, last judged 26 h ago), oldest wake first: sorted by the last
        judgment, the 22 rows judged at 17:17 sat behind 300 others."""
        self.stuck(11, 4 * 3600)
        self.stuck(12, 2 * 3600)
        self.stuck(13, 3 * 3600)
        self.stuck(21, -3600, judged_ago=26 * 3600, kind="pr", seen="an older fingerprint")
        self.retries(4)
        self.tick()
        self.assertEqual(self.explained(), ["11", "13", "12", "21"])

    def test_due_rows_under_a_cycling_latch_say_so_and_go_first_at_its_clear(self):
        """The replay: three rows waiting kind=retry, their wake 2-4 h past, and the login's latch holding, clearing for
        a moment (each row still in the reset spread), holding again, then clearing. Each row's status names the
        latch; at its second window its requester is told once, naming lw#5944; at the next clear it goes at once,
        oldest wake first, with no reset spread."""
        logs: list[dict] = []
        patches = [mock.patch.object(gg, "land_jitter", lambda key, reset=0.0: 90.0),
                   mock.patch.object(gg, "log", logs.append)]
        for p in patches:
            p.start()
            self.addCleanup(p.stop)
        keys = [self.stuck(11, 4 * 3600), self.stuck(12, 2 * 3600), self.stuck(13, 3 * 3600)]
        reset1 = self.t + 600
        self.latch("rest", reset1)
        self.tick(30)
        self.assertEqual(self.w.explains(), [])
        for k in keys:
            e = self.q.entries[k]
            self.assertEqual(e["latchHeld"]["windows"], 1)
            self.assertIn(f"held by the login latch until {time.strftime('%H:%MZ', time.gmtime(reset1))}",
                          gg.land_line(e, self.t))
            self.assertIn("woke ", gg.land_line(e, self.t))
        pool = [r for r in logs if r.get("event") == "land-pool"][-1]
        self.assertEqual((pool["latched"], pool["due"], pool["dueLatchHeld"]), (3, 3, 3))
        self.assertEqual(pool["oldestDue"]["pr"], "o/r#11")
        self.assertGreaterEqual(pool["oldestDue"]["waitingS"], 4 * 3600)
        for _ in range(5):  # the same window: no new history, no message
            self.tick(60)
        self.assertEqual([h["event"] for h in self.q.entries[keys[0]]["history"]].count("latch_held"), 1)
        self.assertEqual(self.w.sent(), [])
        self.q = self.queue()  # a re-exec inside the same hold: the same window, not a second one
        self.tick(60)
        self.assertEqual([self.q.entries[k]["latchHeld"]["windows"] for k in keys], [1, 1, 1])
        self.assertEqual(self.w.sent(), [])
        # It clears; every row's place in the reset spread is still ahead, and the login is spent again before it
        self.tick(reset1 + 1 - self.t)
        self.assertEqual(self.w.explains(), [])
        reset2 = self.t + 1500
        self.latch("rest", reset2)
        self.tick(30)
        self.assertEqual(self.w.explains(), [])
        self.assertEqual([self.q.entries[k]["latchHeld"]["windows"] for k in keys], [2, 2, 2])
        # "nothing to do" is a log line, never a wake (LandQueue.notify)
        self.assertEqual(self.w.sent(), [])
        sent = [(d["to"], d["message"]) for d in logs if d.get("event") == "land-notice-quiet"]
        self.assertEqual(sorted(s[0] for s in sent), ["host/lane11", "host/lane12", "host/lane13"])
        # The line quotes why the owner has no unlatched source (here: no check on this host), never a fixed PR
        self.assertTrue(all("latch" in s[-1] and "no latch-free check on this host" in s[-1]
                            and "leo-workspace#5944" not in s[-1] for s in sent), sent)
        self.tick(60)
        self.assertEqual(len([d for d in logs if d.get("event") == "land-notice-quiet"]), 3, "said once")
        # The next clear: at once, past no spread, oldest wake first
        self.retries(3)
        self.tick(reset2 + 1 - self.t)
        # LAND_RESET_JUDGES_PER_MIN (2) of them at once, the third a minute later (the reset stagger)
        self.assertEqual(self.explained(), ["11", "13"])
        self.assertIn("reset_staggered", [h["event"] for h in self.q.entries[keys[1]]["history"]])
        self.tick(60)
        self.assertEqual(self.explained(), ["11", "13", "12"])
        for k in keys:
            e = self.q.entries[k]
            self.assertNotIn("latchHeld", e)
            self.assertIn("latch_released", [h["event"] for h in e["history"]])

    def test_a_due_row_no_worker_takes_says_why_past_the_bound(self):
        """No latch, every worker busy: a row past its wake by LAND_DUE_LATE gets one due_late in its history, its
        status says every worker is busy, and the land-pool line counts it."""
        logs: list[dict] = []
        p = mock.patch.object(gg, "log", logs.append)
        p.start()
        self.addCleanup(p.stop)
        self.w.config["workers"] = 1

        class Busy:
            def done(self) -> bool:
                return False
        self.q.jobs["pr:o/r#99"] = Busy()
        self.q.job_started["pr:o/r#99"] = (self.q.now - 700, "job")
        key = self.stuck(11, 3 * 3600)
        self.tick(30)
        self.tick(30)
        e = self.q.entries[key]
        self.assertEqual([h["event"] for h in e["history"]].count("due_late"), 1)
        # the row names each holder's job and how long it has held its worker, not only its PR
        late = next(h for h in e["history"] if h["event"] == "due_late")
        self.assertRegex(late["holders"], r"^o/r#99 \? 7\d\ds$")
        self.assertIn("every worker busy", gg.land_line(e, self.t))
        pool = [r for r in logs if r.get("event") == "land-pool"][-1]
        self.assertEqual((pool["gated"], pool["dueLate"], pool["firstGated"]), (1, 1, "o/r#11"))
        del self.q.jobs["pr:o/r#99"]
        self.retries(1)
        self.tick(30)
        e = self.q.entries[key]
        self.assertEqual(self.explained(), ["11"])
        self.assertNotIn("dueLate", e)

    def test_a_worker_that_frees_between_passes_takes_the_oldest_waiting_row_without_a_pass(self):
        """huge-blue, 2026-11-22 11:31Z: the pass runs once per daemon tick, 90-100 s apart under a long queue, and
        workers that freed 30 s into it sat idle until the next one while 864 rows were due. refill hands a freed
        worker the next row the last pass left waiting for one, oldest due first, with no pass of its own."""
        self.w.config["workers"] = 1

        class Busy:
            def done(self) -> bool:
                return False
        self.q.jobs["pr:o/r#99"] = Busy()
        self.stuck(11, 2 * 3600)
        self.stuck(12, 3 * 3600)
        self.retries(2)
        self.tick(30)
        self.assertEqual(self.q.next_up, ["pr:o/r#12", "pr:o/r#11"])  # the pass's order: oldest wake first
        self.assertEqual(self.explained(), [])
        self.assertEqual(self.q.refill(self.t), 0, "no worker free: nothing considered")
        del self.q.jobs["pr:o/r#99"]  # the worker frees between two passes
        self.assertEqual(self.q.refill(self.t + 1), 2)
        # taken at once, oldest row first, before any pass (the fake judge ends at once, so the worker frees again)
        self.assertEqual(self.explained(), ["12", "11"])
        self.assertEqual(self.q.next_up, [])
        self.assertEqual(self.q.refill(self.t + 2), 0, "nothing left waiting")

    def test_refill_takes_no_row_while_the_login_latch_held_the_pass(self):
        """A latch the pass saw holds every row it skipped: a refill between passes starts none of them."""
        self.q.next_up = ["pr:o/r#11"]
        self.stuck(11, 2 * 3600)
        self.q.pass_latch = ("rest", self.t + 600)
        self.assertEqual(self.q.refill(self.t), 0)
        self.assertEqual(self.explained(), [])

    def test_rows_this_hosts_gates_hold_late_overflow_to_a_peer_with_room(self):
        """land.json "overflow": a due row held here LAND_OVERFLOW_AFTER past its due time (every worker busy) goes to
        the first peer whose room answer has room, at most that many, oldest due first; a row due only a minute, or
        landing --after another, stays. Here it is "forwarded", naming the peer, and no worker here judges it."""
        logs: list[dict] = []
        p = mock.patch.object(gg, "log", logs.append)
        p.start()
        self.addCleanup(p.stop)
        self.w.config["workers"] = 1
        self.w.config["overflow"] = [["reach", "full-peer", "glaeda-gh", "land", "serve"],
                                     ["reach", "idle-peer", "glaeda-gh", "land", "serve"]]
        asked: list[tuple[str, dict]] = []
        room = {"full-peer": 0, "idle-peer": 1}

        def serve(cmd: list[str], req: dict, deadline: float) -> dict:
            asked.append((cmd[1], req))
            if req["op"] == "room":
                return {"ok": True, "room": room[cmd[1]], "host": cmd[1],
                        "readable": {o: "" for o in req.get("owners") or []}}
            return {"ok": True, "accepted": [r["id"] for r in req["requests"]], "refused": [], "host": cmd[1]}
        self.q.forward = serve

        class Busy:
            def done(self) -> bool:
                return False
        self.q.jobs["pr:o/r#99"] = Busy()
        oldest, second = self.stuck(11, 3 * 3600), self.stuck(12, 2 * 3600)
        fresh = self.stuck(13, 60)
        chained = self.stuck(14, 4 * 3600, after=["o/r#12"])
        self.tick(30)
        sent = [(host, [r["target"] for r in req["requests"]]) for host, req in asked if req["op"] == "batch"]
        self.assertEqual(sent, [("idle-peer", ["o/r#11"])])
        self.assertEqual([h for h, req in asked if req["op"] == "room"], ["full-peer", "idle-peer"])
        e = self.q.entries[oldest]
        self.assertEqual((e["state"], e["forwardedTo"]), ("forwarded", "idle-peer"))
        self.assertEqual([h["event"] for h in e["history"]].count("overflowed"), 1)
        req = [r for _, q in asked if q["op"] == "batch" for r in q["requests"]][0]
        self.assertEqual((req["requester"], req["handoff"]), ("host/lane11", True))
        for key in (second, fresh, chained):
            self.assertNotEqual(self.q.entries[key]["state"], "forwarded")
        self.tick(30)  # within LAND_OVERFLOW_EVERY: no new pass
        self.assertEqual(len([1 for _, q in asked if q["op"] == "batch"]), 1)
        del self.q.jobs["pr:o/r#99"]
        self.q.jobs["pr:o/r#98"] = Busy()
        self.tick(gg.LAND_OVERFLOW_EVERY + 1)
        sent = [[r["target"] for r in q["requests"]] for _, q in asked if q["op"] == "batch"]
        self.assertEqual(sent, [["o/r#11"], ["o/r#12"]])
        self.assertEqual(self.q.entries[second]["state"], "forwarded")
        self.assertNotEqual(self.q.entries[fresh]["state"], "forwarded")
        self.assertNotEqual(self.q.entries[chained]["state"], "forwarded")
        self.assertEqual(self.explained(), [])  # nothing judged here: the one worker stayed busy throughout

    def test_a_peer_that_refuses_or_is_down_leaves_the_rows_here(self):
        self.w.config["workers"] = 1
        self.w.config["overflow"] = [["reach", "down-peer", "glaeda-gh", "land", "serve"]]

