    def test_land_recovers_stale_checks_after_pin_seen(self):
        # No override: a pinned override row is judged at once while its checks run (LAND_OVERRIDE_PIN_KINDS),
        # so the stale-read recovery this covers is a plain pinned row's.
        # The first cache read already saw the pin and running jobs. No webhook or other waited-pass read
        # arrives. The recovery sweep reads that same head after the copy ages, before the one-hour wait.
        gg.land_request("land", "o/r#1", [], "host/lane", sha=LA)
        self.pr(LA, checks=[("Skills", "IN_PROGRESS", None)])
        e = self.tick()
        self.assertEqual((e["pinSeen"], e["wait"]["why"]), (True, "checks running"))
        self.w.cache[self.KEY]["dataAt"] = self.t + 1  # read after the land request, still running
        original_wake = e["wakeAt"]
        self.q.feed_quiet = lambda *args: True

        def finish(key):
            self.w.refreshed.append(key)
            self.pr(LA, checks=[("Skills", "COMPLETED", "SUCCESS")])

        self.q.refresh = finish
        self.t += gg.LAND_OWN_REFRESH_AFTER - 1
        self.q.tick(self.t, dirty=set())
        self.assertEqual(self.w.refreshed, [])
        self.t += gg.LAND_RECOVERY_SWEEP
        self.assertLess(self.t, original_wake)
        self.q.tick(self.t, dirty=set())
        self.assertEqual(self.w.refreshed, [self.KEY])
        self.w.answers.append(ok_answer(LA))
        self.q.tick(self.t + 1, dirty=set())
        self.assert_merged_at(LA)
        self.assertEqual((len(self.w.explains()), self.w.refreshed), (1, [self.KEY]))

    def test_land_check_event_on_a_stale_running_pin_shares_the_host_read_budget(self):
        # No override: a pinned override row is judged at once while its checks run (LAND_OVERRIDE_PIN_KINDS),
        # so the stale-read recovery this covers is a plain pinned row's.
        self.pr(LA, checks=[("Skills", "IN_PROGRESS", None)])
        gg.land_request("land", "o/r#1", [], "host/lane", sha=LA)
        self.tick()
        self.t += gg.LAND_OWN_REFRESH_AFTER + 1
        self.q.recovery_at = self.t + gg.LAND_RECOVERY_SWEEP  # a head event between sweeps
        self.q.own_refreshed = [self.t] * gg.LAND_OWN_REFRESH_MAX
        self.q.tick(self.t, dirty={self.KEY})
        self.assertEqual(self.w.refreshed, [])
        self.q.own_refreshed.pop()

        def still_running(key):
            self.w.refreshed.append(key)
            self.pr(LA, checks=[("Skills", "IN_PROGRESS", None)])

        self.q.refresh = still_running
        self.q.tick(self.t + 1, dirty={self.KEY})
        self.q.tick(self.t + 2, dirty={self.KEY})
        self.assertEqual((self.w.refreshed, self.w.explains(), self.merge_envs()), ([self.KEY], [], []))
        self.pr(LA, checks=[("Skills", "COMPLETED", "SUCCESS")])
        self.w.answers.append(ok_answer(LA))
        self.q.tick(self.t + 3, dirty={self.KEY})  # fresh terminal evidence still judges at a full read budget
        self.assert_merged_at(LA)

    def stale_conflict_tick(self, fresh: str | None) -> dict:
        """An unpinned land request sent after a push: the cached copy, read 30 s before it, still shows the old head
        LA conflicting, and land_judge answers conflicts_base on it (LAND_BEFORE_REQUEST_READ). A read gives FRESH."""
        self.w.set_pr(self.KEY, land_pr(LA, mergeable="CONFLICTING"), self.t - 30)
        self.q.feed_quiet = lambda *args: True  # the feed missed the push: its quiet must not spare the read
        self.fresh_head = fresh
        self.land()
        self.w.answers.append(refusal("conflicts_base", LA, {"kind": "stop", "stop": "conflict", "why": "merge main"},
                                      nxt="merge main"))
        return self.tick()

    def test_an_unpinned_conflict_on_a_copy_older_than_the_request_reads_before_it_stops(self):
        """hq#20521's second data point: `land` right after a push returned the old head's conflict stop at once. The
        stop waits for one read; the fresh copy's head is judged, and the requester is told nothing about the old."""
        e = self.stale_conflict_tick(LB)
        self.assertEqual((e["state"], e["wait"]["kind"]), ("waiting", "retry"), e.get("stop"))
        self.w.answers.append(ok_answer(LB))
        self.tick()
        self.tick()
        self.assertEqual(self.w.refreshed, [self.KEY])
        self.assert_merged_at(LB)
        self.assertEqual([c for c in self.w.sent() if "stopped" in c[-1]], [])

    def test_a_conflict_still_there_after_the_read_stops_once(self):
        e = self.stale_conflict_tick(LA)  # the read shows the same head: the stop is real
        self.w.answers.append(refusal("conflicts_base", LA, {"kind": "stop", "stop": "conflict", "why": "merge main"},
                                      nxt="merge main"))
        for _ in range(3):
            e = self.tick()
        self.assertEqual((e["state"], e["stop"]["code"], self.w.refreshed), ("stopped", "conflict", [self.KEY]))
        self.assertEqual(len([h for h in e["history"] if h["event"] == "stop_read_first"]), 1)

    def test_a_pinned_conflict_or_a_copy_read_after_the_request_stops_at_once(self):
        self.w.set_pr(self.KEY, land_pr(LA, mergeable="CONFLICTING"), self.t + 1)  # read after the request
        self.land()
        self.w.answers.append(refusal("conflicts_base", LA, {"kind": "stop", "stop": "conflict", "why": "merge main"},
                                      nxt="merge main"))
        e = self.tick()
        self.assertEqual((e["state"], e["stop"]["code"], self.w.refreshed), ("stopped", "conflict", []))

    def test_own_login_refreshes_follow_a_land_request_only_paced_and_capped(self):
        self.pr(LA)
        self.w.cache[self.KEY]["dataAt"] = self.t - 3600
        c = self.w.cache[self.KEY]
        e = {"key": self.KEY, "state": "waiting", "wait": {"kind": "pr"}, "wakeAt": self.t - 1}
        self.assertFalse(self.q.refresh_due(e, c))  # no land request: the daemon's pass reads it
        e["requestedAt"] = c["dataAt"] - 1
        self.assertFalse(self.q.refresh_due(e, c))  # read since the request
        e["requestedAt"] = c["dataAt"] + gg.LAND_OWN_REFRESH_AFTER - 1
        self.assertFalse(self.q.refresh_due(e, c))  # the copy was fresh enough when asked: aged since, not stale then
        e["requestedAt"] = self.t
        e["refresh"] = {"at": self.t - gg.LAND_OWN_REFRESH_AFTER + 1}
        self.assertFalse(self.q.refresh_due(e, c))  # read this recently already
        e["refresh"] = {}
        self.q.own_refreshed = [self.t - 1] * gg.LAND_OWN_REFRESH_MAX
        self.assertFalse(self.q.refresh_due(e, c))  # the host's hourly cap
        self.q.own_refreshed = [self.t - gg.LAND_WINDOW_S - 1] * gg.LAND_OWN_REFRESH_MAX
        self.assertTrue(self.q.refresh_due(e, c))
        self.assertEqual(len(self.q.own_refreshed), 1)

    def test_a_stale_land_judge_checkout_warns_once_and_clears(self):
        """gcp-codex-lane-12, 2026-11-17: a lane VM's leo-workspace sat at #5512 and its land_judge refused every merge
        as unreadable. The startup check warns (never refuses) once, prints in `land status`, and clears once."""
        self.stale_why = "land-judge's checkout /ws is stale: 30 commits behind origin/main (over 20)"
        self.pr(LA)
        self.land()
        self.w.answers.append(ok_answer(LA))
        self.tick()
        self.assert_merged_at(LA)  # a warning, not a refusal
        self.assertEqual([n[0] for n in self.w.notices if n[0].startswith("land-checkout")], ["land-checkout-stale"])
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            gg.cmd_land_status(None, False)
        self.assertIn("WARNING: land-judge's checkout /ws is stale", out.getvalue())
        self.tick(gg.LAND_MH_BEHIND_EVERY + 1)
        self.assertEqual(len([n for n in self.w.notices if n[0] == "land-checkout-stale"]), 1)  # said once
        self.stale_why = None
        self.tick(gg.LAND_MH_BEHIND_EVERY + 1)
        self.assertFalse((gg.land_dir() / gg.LAND_STALE_CHECKOUT_FILE).exists())

    def test_checkout_behind_reads_commits_hours_and_fetch_age(self):
        fetch = Path(self.tmp.name) / "FETCH_HEAD"
        fetch.write_text("")
        now = fetch.stat().st_mtime
        answers = {"rev-parse --show-toplevel": "/ws", "rev-list --count HEAD..origin/main": "28",
                   "log -1 --format=%ct HEAD": str(int(now - 9 * 3600)), "log -1 --format=%ct origin/main": str(int(now)),
                   "rev-parse --path-format=absolute --git-path FETCH_HEAD": os.fspath(fetch)}
        git = lambda args: answers.get(" ".join(args))  # noqa: E731
        no_log = Path(self.tmp.name) / "no-deploys.log"  # never the host's own ws-sync record
        why = gg.land_checkout_behind(Path("/ws/tools/land-judge"), 20, 6.0, now, git, no_log)
        self.assertIn("28 commits behind origin/main (over 20)", why)
        self.assertIn("9.0 h newer than HEAD", why)
        self.assertIn("/ws/tools/ws-deploy --local", why)
        self.assertNotIn("last fetched", why)
        self.assertIn("last fetched 7.0 h ago", gg.land_checkout_behind(Path("/ws/x"), 100, 6.0, now + 7 * 3600, git,
                                                                         no_log))
        self.assertIsNone(gg.land_checkout_behind(Path("/ws/x"), 100, 24.0, now, git, no_log))
        self.assertIsNone(gg.land_checkout_behind(Path("/nogit/x"), 0, 0.1, now, lambda args: None))

    def checkout_git(self, now: float, head: str, main: str, dirty: str = "") -> tuple[Any, Path]:
        """A fake `git -C` for land_checkout_behind: a checkout at HEAD, origin/main at MAIN, every fetch file at NOW."""
        fetch = Path(self.tmp.name) / "FETCH_HEAD"
        fetch.write_text("")
        os.utime(fetch, (now, now))
        answers = {"rev-parse --show-toplevel": "/ws", "rev-list --count HEAD..origin/main": "0" if head == main else "3",
                   "log -1 --format=%ct HEAD": str(int(now)), "log -1 --format=%ct origin/main": str(int(now)),
                   "rev-parse HEAD": head, "rev-parse origin/main": main,
                   "status --porcelain --untracked-files=no": dirty,
                   "rev-parse --path-format=absolute --git-path FETCH_HEAD": os.fspath(fetch)}
        return (lambda args: answers.get(" ".join(args))), Path(self.tmp.name) / "deploys.log"

    def test_a_ws_sync_no_op_at_head_counts_as_a_fetch(self):
        """interim-coord, 2026-11-18: huge-blue's land said "last fetched 7.7 h ago" while ws-sync ran `no-op f2923c5`
        every 10 minutes at that checkout's HEAD. ws-sync's own record of a fetch that found main at HEAD is a fetch."""
        then = NOW - 8 * 3600
        head = "f2923c569789d780be3702ff901320efd4a7511a"
        git, log_path = self.checkout_git(then, head, head)
        stamp = lambda t: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(t))  # noqa: E731
        log_path.write_text(f"{stamp(NOW - 1200)} deployed 38f0454..f2923c5 paths: tools/x\n"
                            f"{stamp(NOW - 600)} no-op f2923c5\n")
        self.assertIsNone(gg.land_checkout_behind(Path("/ws/tools/land-judge"), 20, 6.0, NOW, git, log_path))
        # the newest run found main somewhere else: it says nothing of this checkout
        log_path.write_text(f"{stamp(NOW - 600)} no-op 0123456\n")
        why = gg.land_checkout_behind(Path("/ws/tools/land-judge"), 20, 6.0, NOW, git, log_path)
        self.assertIn("main has not been fetched for 8.0 h", why)
        self.assertNotIn("stale", why)
        self.assertNotIn("last fetched", why)  # at its origin/main: main may have moved, the code is not known old
        other, _ = self.checkout_git(then, "a" * 40, "b" * 40)
        self.assertIn("last fetched 8.0 h ago", gg.land_checkout_behind(Path("/ws/x"), 20, 6.0, NOW, other, log_path))

