    def test_the_latch_holds_only_lands_with_no_unlatched_source(self):
        # huge-blue, 2026-11-18 15:24Z: the login's GraphQL latched, 382 open lands, workers busy=0, nothing judged,
        # though land_judge reads manaflow-ai through the lander App pools.
        self.latch_dir.mkdir(parents=True, exist_ok=True)
        (self.latch_dir / "rest-exhausted.json").write_text(json.dumps({"until": self.t + 3000, "at": self.t}))
        self.w.config["latchFreeCommand"] = ["/fake/ready", "--owner", "{owner}"]
        asked: list[list[str]] = []
        run = self.w.run

        def ready(argv, timeout, env):
            if argv[0] == "/fake/ready":
                asked.append(list(argv))
                if argv[-1] == "o":
                    return subprocess.CompletedProcess(argv, 0, "", "")
                return subprocess.CompletedProcess(argv, 1, "", f"gh-app-token: not ready for {argv[-1]}: "
                                                                f"no App pool here serves {argv[-1]}\n")
            return run(argv, timeout, env)
        self.q.run = ready
        self.pr(LA)
        self.pr(LA, key="pr:p/r#2")
        self.land()
        self.land("p/r#2")
        self.w.answers.append(ok_answer(LA))
        self.tick()
        self.tick()
        self.assert_merged_at(LA)  # o's reads have an unlatched source: judged and merged under the latch
        self.assertEqual(self.q.entries["pr:p/r#2"]["state"], "queued")  # p's have none: held, as before
        self.assertEqual(sorted({a[-1] for a in asked}), ["o", "p"])
        self.assertLessEqual(len(asked), 2, "asked once per owner per LAND_LATCH_FREE_EVERY")
        # huge-blue, 2026-11-19: the starved-latch notice quotes ready's own reason (teamleaderleo: no App pool serves
        # it), not a fixed "leo-workspace#5944"
        self.assertEqual(self.q.latch_free_why(self.q.entries["pr:p/r#2"]), "no App pool here serves p")
        self.assertEqual(gg.latch_free_reason(subprocess.CompletedProcess([], 124, "", "timed out after 10s")),
                         "timed out after 10s")
        self.assertEqual(gg.latch_free_reason(subprocess.CompletedProcess([], 2, "", "")),
                         "the latch-free check exited 2")

    def test_a_lane_vm_judges_an_owner_the_brokers_read_app_covers_under_the_login_mark(self):
        # gcp-agent-lane-1, 2026-11-19 12:28-14:25Z: a copied login mark held 16 lands four windows; the ready command
        # can never say yes on a lane VM (no App credential there by design), though the broker answers a pinned
        # land's reads (LANE_GH_LAND) from its read App, which cosmic-gray judged the same PRs on.
        self.latch_dir.mkdir(parents=True, exist_ok=True)
        (self.latch_dir / "rest-exhausted.json").write_text(json.dumps(
            {"until": self.t + 3000, "at": self.t, "source": "x-ratelimit-reset", "by": "lane-gh"}))
        self.w.config["latchFreeCommand"] = ["/fake/ready", "--owner", "{owner}"]
        self.w.config["brokerReadOwners"] = ["O"]
        asked: list[list[str]] = []
        run = self.w.run

        def ready(argv, timeout, env):
            if argv[0] == "/fake/ready":
                asked.append(list(argv))
                return subprocess.CompletedProcess(argv, 1, "", "gh-app-token: not ready for o: no landing-role App")
            return run(argv, timeout, env)
        self.q.run = ready
        self.q.broker_client = lambda: True
        self.pr(LA)
        self.pr(LA, key="pr:p/r#2")
        self.land()
        self.land("p/r#2")
        self.w.answers.append(ok_answer(LA))
        self.tick()
        self.tick()
        # o: the broker's read App covers it, judged under the copied mark and sent to the broker's land
        self.assertEqual([json.loads(c[4]) for c in self.w.calls if c[:3] == ["/fake/lane-gh", "call", "land"]],
                         [{"number": 1, "sha": LA}])
