    def test_a_full_pool_with_rows_waiting_grows_until_github_refuses(self):
        """Leo: "you shouldnt need to set minimums in the first place". huge-blue, 2026-11-22 09:44-09:59Z: land.json
        "workers": 12, 12 of 12 busy, ~1,000 due rows gated a pass, judgments 3-13 min of GitHub waits at about 65 MB
        and a few % of a core each. A full pool with due rows waiting grows by a quarter a step up to its memory
        ceiling; a quota refusal halves it; an idle or unfull pool stays; land.json "workers" fixes it."""
        q = self.q
        self.assertEqual(q.workers(), 4)
        with mock.patch.object(gg, "land_mem_available_mb", return_value=40 * 1024):  # 80 workers' worth
            for n in range(4):
                q.jobs[f"pr:o/r#{n + 100}"] = mock.Mock(done=lambda: False)
            q.now, q.pass_gated = 1000.0, 7
            q.adapt_pool()
            self.assertEqual(q.workers(), 5)
            q.adapt_pool()  # within LAND_POOL_ADAPT_S: no step
            self.assertEqual(q.workers(), 5)
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()  # 5 jobs needed to be full: 4 running, so it holds
            self.assertEqual(q.workers(), 5)
            sizes = []
            for _ in range(20):
                while len(q.jobs) < q.workers():
                    q.jobs[f"pr:o/r#{len(q.jobs) + 100}"] = mock.Mock(done=lambda: False)
                q.now += gg.LAND_POOL_ADAPT_S
                q.adapt_pool()
                sizes.append(q.workers())
            self.assertEqual(sizes[:4], [6, 7, 9, 12])
            self.assertEqual(sizes[-1], 80)  # 40 GB available: half of it at LAND_JUDGE_MEM_MB each
            q.pass_gated = 0  # nothing waits for a worker: no growth
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()
            self.assertEqual(q.workers(), 80)
            q.pass_gated = 3
            q.now += 1
            q.park_quota({"key": "pr:o/r#1", "state": "judging", "history": []}, "API rate limit exceeded")
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()
            self.assertEqual(q.workers(), 40)
            self.w.config["workers"] = 12
            self.assertEqual(q.workers(), 12)
        q.jobs.clear()

    def test_the_pool_grows_past_the_read_room_and_the_snapshot_waits_stay_inside_it(self):
        """cmux-cp-1, 2026-11-22 20:54Z: 175 workers held 262 waited PRs, each worker keeping a snapshot wait's place.
        Capping the workers at the read room fixed that and pinned the pool at LAND_WATCH_FLOOR: cmux-cp-1, 2026-11-25
        06:35-12:35Z, 16 workers, 22 of ~23 busy on average with 75% of the CPU free, a due row waiting a median 5.5
        min for each judgment. The pool grows to its memory ceiling while rows wait for a worker; the snapshot waits,
        what puts reads first, stay inside the room; a quota refusal still halves."""
        q, room = self.q, [6]
        q.read_room = lambda: room[0]
        with mock.patch.object(gg, "land_mem_available_mb", return_value=40 * 1024):  # 80 workers' worth
            q.now, q.pass_gated = 1000.0, 7
            for _ in range(20):
                while len(q.jobs) < q.workers():
                    q.jobs[f"pr:o/r#{len(q.jobs) + 100}"] = mock.Mock(done=lambda: False)
                q.now += gg.LAND_POOL_ADAPT_S
                q.adapt_pool()
            self.assertEqual(q.workers(), 80)  # past the room of 6: the memory ceiling
            room[0] = 3  # GitHub slowed: the workers stay
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()
            self.assertEqual(q.workers(), 80)
            q.jobs.clear()
            # the snapshot waits are what the room bounds: 3 places, whatever the workers
            q.snapshot_waiting = set()
            for n in range(3):
                q.snapshot_waiting.add(f"pr:o/r#{n + 500}")
                q.entries[f"pr:o/r#{n + 500}"] = {"snapshotWait": {"since": q.now}}
            self.assertFalse(q.snapshot_room(True))
            room[0] = 4
            self.assertTrue(q.snapshot_room(True))
            room[0] = None  # no room known: the workers' places alone
            self.assertTrue(q.snapshot_room(True))
            for n in range(3):
                q.entries.pop(f"pr:o/r#{n + 500}")
            q.snapshot_waiting = set()
            q.pass_gated = 3
            q.now += 1
            q.park_quota({"key": "pr:o/r#1", "state": "judging", "history": []}, "API rate limit exceeded")
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()
            self.assertEqual(q.workers(), 40)  # a quota refusal halves it, as before
        q.jobs.clear()
        # a daemon up for less than the window counts its reads over its uptime
        d = gg.Daemon.__new__(gg.Daemon)
        d.now, d.started_tick, d.read_done = NOW, NOW - 120, {"pr": [NOW - 30] * 60}
        self.assertEqual(d.land_read_room(), int(60 * gg.READ_PROGRESS_WINDOW / 120 * gg.LAND_WATCH_SHARE))

    def test_a_restarted_queue_keeps_its_pool_size(self):
        """hq#18502: huge-blue re-execs its daemon every 10-30 min. 2026-11-22, land.json's "workers" removed at 12:28Z:
        the pool grew 16 -> 20 -> 25, a re-exec at 12:39Z put it back at 16 (land_worker_ceiling), under the fixed 32,
        and the override went back. A new queue starts at the size the last one's pool line said, at once (not at its
        next land-pool line), bounded by the memory ceiling; a stale or missing line starts from the cores."""
        q = self.q
        with mock.patch.object(gg, "land_mem_available_mb", return_value=40 * 1024):  # 80 workers' worth
            q.now, q.pass_gated = self.t, 9
            for _ in range(6):
                while len(q.jobs) < q.workers():
                    q.jobs[f"pr:o/r#{len(q.jobs) + 100}"] = mock.Mock(done=lambda: False)
                q.now += gg.LAND_POOL_ADAPT_S
                q.adapt_pool()
            grown = q.workers()
            self.assertGreater(grown, 4)
            self.assertEqual(gg.read_json(gg.land_dir() / gg.LAND_POOL_FILE)["workers"], grown)
            q.jobs.clear()
            with mock.patch.object(gg.time, "time", return_value=q.now + 30):
                self.assertEqual(self.queue().workers(), grown)  # the re-exec keeps it
            with mock.patch.object(gg, "land_mem_available_mb", return_value=4 * 1024):  # 8 workers' worth
                with mock.patch.object(gg.time, "time", return_value=q.now + 30):
                    self.assertEqual(self.queue().workers(), 8)  # never over the memory ceiling
            with mock.patch.object(gg.time, "time", return_value=q.now + gg.LAND_ROOM_FRESH + 1):
                self.assertEqual(self.queue().workers(), 4)  # a stale line: the cores (8 in setUp)
            (gg.land_dir() / gg.LAND_POOL_FILE).unlink()
            self.assertEqual(self.queue().workers(), 4)
            # an operator's fixed size is where the pool goes on from once it is taken out
            self.w.config["workers"] = 32
            q.now += gg.LAND_POOL_ADAPT_S
            q.adapt_pool()
            del self.w.config["workers"]
            self.assertEqual(q.workers(), 32)

